(function(){"use strict";window.NITI_OLD_EXAMS=[{"id":"archive-2555-s-1-1","year":"2555","semester":"ภาคฤดูร้อน","number":1,"page":1,"course":"LAW2001 (LA 201 / LW 204)","title":"ปี 2555 ภาคฤดูร้อน · ข้อ 1","sections":["1299"],"kind":"old-exam-source","source":"แนวข้อสอบเก่าวิชาทรัพย์สิน.pdf","question":"ข้อ 1. นายแก้วกับนายขวดทำสัญญากันด้วยวาจาให้นายขวดมีสิทธิเก็บกินบนที่ดินของนายแก้วเป็น เวลา 5 ปี เมื่อนายขวดเข้ามาใช้สิทธิเก็บกินได้ 3 ปี นายแก้วขายที่ดินให้นายถ้วย นายถ้วยต้องการทำ ประโยชน์ในที่ดินด้วยตนเอง จึงไม่ยอมให้นายขวดมาใช้สิทธิเก็บกินบนที่ดินอีก\n\nดังนี้ ให้วินิจฉัยว่า นายขวดจะอ้างสิทธิเก็บกินบนที่ดินแปลงนี้อีก 2 ปี ขึ้นต่อสู้ได้หรือไม่ นายถ้วย จะต้องยอมให้นายขวดใช้สิทธิเก็บกินจนครบ 5 ปี หรือไม่ เพราะเหตุใด จงอธิบาย","rule":"มาตรา 1299 วรรคแรก ภายในบังคับแห่งบทบัญญัติในประมวลกฎหมายนี้หรือกฎหมายอื่น ท่าน ว่า การได้มาโดยนิติกรรมซึ่งอสังหาริมทรัพย์หรือทรัพยสิทธิอันเกี่ยวกับอสังหาริมทรัพย์นั้นไม่ บริบูรณ์ เว้นแต่นิติกรรมจะได้ทำเป็นหนังสือและได้จดทะเบียนการได้มากับพนักงานเจ้าหน้าที่","application":"ตามกฎหมาย การได้มาซึ่งอสังหาริมทรัพย์หรือทรัพยสิทธิอันเกี่ยวกับอสังหาริมทรัพย์โดยทางนิติ กรรมนั้น จะบริบูรณ์เป็นทรัพยสิทธิได้ จะต้องทำเป็นหนังสือและจดทะเบียนการได้มากับพนักงาน เจ้าหน้าที่ ซึ่งถ้าฝ่าฝืนจะมีผลเป็นเพียงบุคคลสิทธิ ใช้กล่าวอ้างได้เฉพาะคู่สัญญาเท่านั้น ไม่สามารถยกขึ้น กล่าวอ้างต่อบุคคลภายนอกได้ (มาตรา 1299 วรรคแรก) กรณีตามอุทาหรณ์ การที่นายแก้วกับนายขวดทำสัญญากันด้วยวาจา ให้นายขวดมีสิทธิเก็บกินบนที่ดินของ นายแก้วเป็นเวลา 5 ปีนั้น ถือว่านายขวดเป็นผู้ได้มาซึ่งทรัพยสิทธิในอสังหาริมทรัพย์โดยนิติกรรม เมื่อ ไม่ได้ทำเป็นหนังสือและจดทะเบียนกับพนักงานเจ้าหน้าที่ สิทธิการได้มาดังกล่าวจึงไม่บริบูรณ์เป็น ทรัพยสิทธิ แต่มีผลผูกพันเป็นบุคคลสิทธิระหว่างนายแก้วกับนายขวดเท่านั้น\n\nดังนั้น เมื่อต่อมานายแก้วขายที่ดินให้นายถ้วย นายถ้วยจึงไม่ต้องผูกพันในข้อตกลงที่นายแก้วมีต่อ นายขวด และนายขวดไม่สามารถอ้างการได้สิทธิเก็บกินบนที่ดินขึ้นต่อสู้กับนายถ้วยได้ นายถ้วยจึงไม่ต้อง ให้นายขวดใช้เก็บกินบนที่ดินนั้นต่อไปแต่อย่างใด","conclusion":"สรุป นายถ้วยไม่ต้องให้นายขวดใช้สิทธิเก็บกินจนครบ 5 ปี","otherSections":[]},{"id":"archive-2555-s-3-2","year":"2555","semester":"ภาคฤดูร้อน","number":3,"page":2,"course":"LAW2001 (LA 201 / LW 204)","title":"ปี 2555 ภาคฤดูร้อน · ข้อ 3","sections":["1367","1377"],"kind":"old-exam-source","source":"แนวข้อสอบเก่าวิชาทรัพย์สิน.pdf","question":"ข้อ 3. นายกล้าทำสัญญาขายที่ดิน น.ส.3 ของตนให้กับนายเข้ม โดยเป็นการทำสัญญาซื้อขายกันเองและมี การชำระราคาที่ดินให้นายกล้าครบถ้วน และนายกล้าก็ส่งมอบที่ดินให้นายเข้มแล้ว หลังจากนายเข้มสร้าง บ้านอยู่ในที่ดินนั้นติดต่อกันได้ห้าปี นายกล้าถึงแก่ความตาย นายแก้วบุตรของนายกล้าได้จดทะเบียนรับ มรดกที่ดินแปลงนั้น แล้วแจ้งให้นายเข้มย้ายออกไปจากที่ดินนั้น แต่นายเข้มอ้างว่าที่ดินเป็นของตน และ ไม่ยอมย้ายออกไป ต่อจากนั้นอีก 4 เดือน นายแก้วจึงฟ้องขับไล่และเรียกที่ดินคืนจากนายเข้ม\n\nดังนี้ให้วินิจฉัยว่า ระหว่างนายแก้วกับนายเข้ม ผู้ใดมีสิทธิในที่ดินพิพาทดีกว่ากัน และนายเข้มต้อง ออกไปจากที่ดินนั้นหรือไม่ เพราะเหตุใด","rule":"มาตรา 1367 บุคคลใดยึดถือทรัพย์สินโดยเจตนาจะยึดถือเพื่อตน ท่านว่าบุคคลนั้นได้ซึ่งสิทธิ ครอบครอง\n\nมาตรา 1377 วรรคหนึ่ง ถ้าผู้ครอบครองสละเจตนาครอบครอง หรือไม่ยึดถือทรัพย์สินต่อไป ไซร้ การครอบครองย่อมสิ้นสุดลง\n\nมาตรา 1378 การโอนไปซึ่งการครอบครองนั้น ย่อมทำได้โดยส่งมอบทรัพย์สินที่ครอบครอง","application":"ตามอุทาหรณ์ การที่นายกล้าทำสัญญาขายที่ดิน น.ส.3 ของตนให้กับนายเข้ม โดยเป็นการทำสัญญา ซื้อขายกันเองนั้น สัญญาซื้อขายที่ดินระหว่างนายกล้ากับนายเข้มย่อมตกเป็นโมฆะเพราะไม่ได้จดทะเบียน กับพนักงานเจ้าหน้าที่ แต่อย่างไรก็ตาม เนื่องจากที่ดินดังกล่าวเป็นที่ดิน น.ส.3 ซึ่งมีเพียงสิทธิครอบครอง และการซื้อขายดังกล่าวได้มีการชำระราคาครบถ้วนและได้มีการส่งมอบที่ดินให้แก่นายเข้มผู้ซื้อแล้ว การ ครอบครองที่ดินของนายกล้าผู้ขายจึงสิ้นสุดลงตามมาตรา 1377 วรรคแรก เพราะนายกล้าได้สละเจตนา ครอบครองและไม่ได้ยึดถือที่ดินนั้นต่อไปแล้ว ส่วนนายเข้มก็ได้ซึ่งสิทธิครอบครองที่ดินนั้นแล้วโดยการ ส่งมอบทรัพย์สินที่ครอบครองตามมาตรา 1378 และนายเข้มได้เข้ายึดถือที่ดินนั้นด้วยเจตนายึดถือเพื่อตนใน ฐานะเจ้าของตามมาตรา 1367\n\nแต่ต่อมาอีก 5 ปี เมื่อนายกล้าถึงแก่ความตาย\n\nดังนี้ แม้นายแก้วบุตรของนายกล้าจะได้จดทะเบียนรับมรดกที่ดินนั้นแล้วแจ้งให้นายเข้มย้ายออกไป จากที่ดินนั้น นายเข้มก็ไม่ต้องย้ายออกไปจากที่ดินนั้นตามที่นายแก้วต้องการ เพราะนายเข้มเป็นผู้มีสิทธิ ครอบครองเหนือที่ดินนั้นดีกว่านายแก้ว เนื่องจากนายแก้วผู้รับมรดกไม่มีสิทธิดีกว่านายกล้าเจ้ามรดกตาม หลักที่ว่า “ผู้รับโอนไม่มีสิทธิดีกว่าผู้โอน” นั่นเอง","conclusion":"สรุป นายเข้มมีสิทธิในที่ดินพิพาทดีกว่านายแก้ว และนายเข้มไม่ต้องย้ายออกไปจากที่ดินนั้น","otherSections":["1378"]},{"id":"archive-2555-s-4-3","year":"2555","semester":"ภาคฤดูร้อน","number":4,"page":3,"course":"LAW2001 (LA 201 / LW 204)","title":"ปี 2555 ภาคฤดูร้อน · ข้อ 4","sections":["1382","1387"],"kind":"old-exam-source","source":"แนวข้อสอบเก่าวิชาทรัพย์สิน.pdf","question":"ข้อ 4. นายแห้วเป็นเจ้าของที่ดินแปลงหนึ่งอยู่ติดกับทางสาธารณะซึ่งเป็นทางดินลูกรังกว้างสองเมตร ครึ่ง นายแห้วจึงได้ใช้ทางผ่านที่ดินของนายมัน โดยทำเป็นถนนลาดยางกว้างสามเมตรเพื่อใช้รถปิ๊กอัพผ่าน เข้าออกระหว่างที่ดินของตนกับถนนพหลโยธินซึ่งสะดวกกว่า หลังจากนายแห้วใช้ทางผ่านที่ดินของนาย มันติดต่อกันเป็นเวลากว่าสิบปี โดยนายมันไม่รู้เรื่องแต่อย่างใด ต่อมานายแห้วได้สร้างโรงงานในที่ดินของ ตน ทำให้ต้องใช้รถยนต์บรรทุกสิบล้อผ่านเข้าออกเพื่อขนส่งสินค้าวันละหลายเที่ยว นายแห้วจึงเปลี่ยนจาก ถนนลาดยางเป็นถนนคอนกรีตกว้างหกเมตร หลังจากนั้น นายมันรู้เรื่องจึงมาปรึกษาท่าน เพราะไม่ ต้องการให้นายแห้วใช้ถนนนั้นผ่านที่ดินของตน\n\nดังนี้ให้ท่านวินิจฉัยว่าระหว่างนายแห้วกับนายมันมีสิทธิและหน้าที่เหนือที่ดินแปลงดังกล่าว อย่างไร จงอธิบาย","rule":"มาตรา 1382 บุคคลใดครอบครองทรัพย์สินของผู้อื่นไว้โดยความสงบและโดยเปิดเผยด้วยเจตนา เป็นเจ้าของ ถ้าเป็นอสังหาริมทรัพย์ได้ครอบครองติดต่อกันเป็นเวลาสิบปี ถ้าเป็นสังหาริมทรัพย์ได้ ครอบครองติดต่อกันเป็นเวลาห้าปีไซร้ ท่านว่าบุคคลนั้นได้กรรมสิทธิ์\n\nมาตรา 1387 อสังหาริมทรัพย์อาจต้องตกอยู่ในภาระจำยอมอันเป็นเหตุให้เจ้าของต้องยอมรับกรรม บางอย่างซึ่งกระทบถึงทรัพย์สินของตน หรือต้องงดเว้นการใช้สิทธิบางอย่างอันมีอยู่ในกรรมสิทธิ์ทรัพย์สิน นั้นเพื่อประโยชน์แก่อสังหาริมทรัพย์อื่น\n\nมาตรา 1388 เจ้าของสามยทรัพย์ไม่มีสิทธิทำการเปลี่ยนแปลงในภารยทรัพย์ หรือใน สามยทรัพย์ ซึ่งทำให้เกิดภาระเพิ่มขึ้นแก่ภารยทรัพย์","application":"กรณีตามอุทาหรณ์ การที่นายแห้วได้ใช้ทางผ่านที่ดินของนายมัน โดยทำเป็นถนนลาดยาง กว้าง 3 เมตร ผ่านที่ดินของนายมันเพื่อใช้รถปิ๊กอัพผ่านเข้าออกระหว่างที่ดินของนายแห้วกับถนน พหลโยธิน โดยนายมันไม่รู้เรื่องติดต่อกันเป็นเวลาเกิน 10 ปีแล้ว ย่อมถือว่านายแห้วได้ภาระจำยอมเหนือ ที่ดินของนายมันโดยอายุความปรปักษ์ คือการได้มาซึ่งภาระจำยอมโดยอายุความ ตามมาตรา 1387, 1401 และมาตรา 1382\n\nต่อมาการที่นายแห้วได้สร้างโรงงานในที่ดินของตน และต้องการใช้รถยนต์บรรทุกสิบล้อผ่านเข้า ออกเพื่อขนส่งสินค้าวันละหลายเที่ยว นายแห้วจึงเปลี่ยนจากถนนลาดยางเป็นถนนคอนกรีตกว้าง 6 เมตร นั้น การกระทำดังกล่าวของนายแห้วเป็นเรื่องที่เจ้าของสามยทรัพย์ทำการเปลี่ยนแปลงในภารยทรัพย์ซึ่งทำ ให้เกิดภาระเพิ่มขึ้นแก่ภารยทรัพย์\n\nดังนั้น นายแห้วจะกระทำไม่ได้ตามมาตร 1388","conclusion":"สรุป นายแห้วได้ภาระจำยอมเป็นถนนลาดยางกว้าง 3 เมตร ผ่านที่ดินของนายมันแล้ว และนายมัน จะห้ามนายแห้วไม่ให้ใช้ทางภาระจำยอมนั้นไม่ได้ แต่นายแห้วจะเปลี่ยนถนนลาดยางซึ่งเดิมกว้าง 3 เมตร เป็นถนนคอนกรีตกว้าง 6 เมตรไม่ได้","otherSections":["1388"]},{"id":"archive-2555-2-3-7","year":"2555","semester":"ภาค 2","number":3,"page":7,"course":"LAW2001 (LA 201 / LW 204)","title":"ปี 2555 ภาค 2 · ข้อ 3","sections":["1382","1387","1401"],"kind":"old-exam-source","source":"แนวข้อสอบเก่าวิชาทรัพย์สิน.pdf","question":"ข้อ 3. น้ำแบ่งขายที่ดินของน้ำให้ฟ้าโดยทั้งน้ำและฟ้าตกลงให้ที่ดินของฟ้ามีทางเข้าออกสู่ทางสาธารณะผ่าน ที่ดินแปลงของน้ำในส่วนที่เหลือ แต่ไม่ได้จดทะเบียนการได้มา เมื่อฟ้าซื้อที่ดินจากน้ำมาแล้ว ได้เข้ามาปลูก บ้านอยู่อาศัยในที่ดินแปลงนั้น แทนที่จะเดินในทางที่ตกลงไว้กับน้ำ\n\nฟ้ากลับใช้ทางผ่านในส่วนอื่นของที่ดินของน้ำ โดยไม่บอกน้ำและยังทำถนนคอนกรีตเพื่อให้ รถยนต์เข้าออก นอกจากนั้นฟ้ายังเข้ามาในที่ดินของน้ำโดยเข้ามาทิ้งขยะในที่ดินของน้ำทุกวันด้วย ฟ้าได้ทำ เช่นนี้ตลอดกว่าสิบปีโดยน้ำไม่ทราบ เมื่อน้ำทราบจึงได้มาห้ามและบอกให้ฟ้าเลิกใช้ถนนที่ฟ้าสร้างให้มาใช้ ถนนเส้นที่ตกลงเดิม และเลิกเข้ามาทิ้งขยะในที่ดินของน้ำ ฟ้าตกลงเลิกทิ้งขยะ แต่ถนนฟ้าไม่ยอมเพราะถนน ที่ตนสร้างสะดวกสบายกว่า แต่พอผ่านมาได้สามเดือนฟ้าได้เข้าทิ้งขยะในที่ดินของน้ำอีก คราวนี้น้ำทนไม่ ไหว หนึ่งเดือนหลังจากนั้น น้ำจึงได้ฟ้องต่อศาลให้ฟ้าเลิกทิ้งขยะและรื้อถนนที่ฟ้าสร้างออกไป ให้ท่านวินิจฉัยถึงสิทธิของฟ้าในถนนที่ฟ้าสร้าง และการทิ้งขยะในที่ดินของน้ำ","rule":"มาตรา 1374 ถ้าผู้ครอบครองถูกรบกวนในการครอบครองทรัพย์สิน เพราะมีผู้สอดเข้าเกี่ยวข้องโดย มิชอบด้วยกฎหมายไซร้ ท่านว่าผู้ครอบครองมีสิทธิจะให้ปลดเปลื้องการรบกวนนั้นได้ ถ้าเป็นที่น่าวิตกว่า จะยังมีการรบกวนอีก ผู้ครอบครองจะขอต่อศาลให้สั่งห้ามก็ได้ การฟ้องคดีเพื่อปลดเปลื้องการรบกวนนั้น ท่านว่าต้องฟ้องภายในปีหนึ่งนับแต่เวลาถูกรบกวน\n\nมาตรา 1382 บุคคลใดครอบครองทรัพย์สินของผู้อื่นไว้โดยความสงบและโดยเปิดเผยด้วยเจตนา เป็นเจ้าของ ถ้าเป็นอสังหาริมทรัพย์ได้ครอบครองติดต่อกันเป็นเวลาสิบปี ถ้าเป็นสังหาริมทรัพย์ได้ ครอบครองติดต่อกันเป็นเวลาห้าปีไซร้ ท่านว่าบุคคลนั้นได้กรรมสิทธิ์\n\nมาตรา 1387 อสังหาริมทรัพย์อาจต้องตกอยู่ในภาระจำยอมอันเป็นเหตุให้เจ้าของต้องยอมรับกรรม บางอย่างซึ่งกระทบถึงทรัพย์สินของตน หรือต้องงดเว้นการใช้สิทธิบางอย่างอันมีอยู่ในกรรมสิทธิ์ทรัพย์สิน นั้นเพื่อประโยชน์แก่อสังหาริมทรัพย์อื่น\n\nมาตรา 1401 ภาระจำยอมอาจได้มาโดยอายุความ ท่านให้นำบทบัญญัติว่าด้วยอายุความได้สิทธิอัน กล่าวไว้ในลักษณะ 3 แห่งบรรพนี้มาใช้บังคับโดยอนุโลม","application":"กรณีตามอุทาหรณ์ มีประเด็นที่จะต้องวินิจฉัย 2 ประเด็น คือ\n\nประเด็นที่ 1 เกี่ยวกับสิทธิของฟ้าในถนนที่ฟ้าสร้าง การที่น้ำแบ่งขายที่ดินของน้ำให้ฟ้า และตกลงให้ฟ้ามีทางเข้าออกสู่ทางสาธารณะผ่านที่ดินแปลงของน้ำใน ส่วนที่เหลือนั้น ถือว่าฟ้าได้ภาระจำยอมโดยทางนิติกรรม และแม้ไม่ได้จดทะเบียนการได้มาก็สามารถใช้ บังคับกันได้ในระหว่างคู่กรณี แต่เมื่อฟ้าซื้อที่ดินจากน้ำมาแล้วและได้เข้ามาปลูกบ้านอยู่อาศัยในที่ดินแปลง นั้น แทนที่จะเดินเข้าออกในทางที่ตกลงไว้กับน้ำ กลับใช้ทางผ่านในส่วนอื่นของที่ดินของน้ำโดยไม่บอก น้ำ และยังทำถนนคอนกรีตเพื่อให้รถยนต์เข้าออกจนครบกำหนด 10 ปี โดยที่น้ำไม่ทราบ กรณีนี้จึงถือได้ว่า ฟ้าซึ่งเป็นเจ้าของสามยทรัพย์ได้ใช้ประโยชน์ในภารยทรัพย์ (ที่ดินของน้ำ) โดยสงบและโดยเปิดเผย และ ด้วยเจตนาจะได้สิทธิภาระจำยอมในภารยทรัพย์นั้น ดังนั้นฟ้าย่อมได้ภาระจำยอมในถนนที่ฟ้าสร้างโดยการ ครอบครองปรปักษ์ตามมาตรา 1382 ประกอบมาตรา 1401 และน้ำซึ่งเป็นเจ้าของภารยทรัพย์จะฟ้องให้ฟ้ารื้อ ถนนที่ฟ้าสร้างออกไปไม่ได้ ตามมาตรา 1387\n\nประเด็นที่ 2 เกี่ยวกับการทิ้งขยะของฟ้าในที่ดินของน้ำ การที่ฟ้าได้นำขยะมาทิ้งในที่ดินของน้ำทุกวันนั้น ถือว่าน้ำผู้ครอบคอรงที่ดินถูกฟ้ารบกวนการครอบครอง โดยมิชอบด้วยกฎหมาย น้ำจึงมีสิทธิบอกห้ามและให้ฟ้าเลิกเข้ามาทิ้งขยะในที่ดินของน้ำได้ตาม มาตรา 1374 วรรคแรก และเมื่อฟ้าตกลงเลิกทิ้งขยะแล้ว การรบกวนการครอบครองย่อมระงับไป แต่ อย่างไรก็ตาม เมื่อปรากฏว่า พอผ่านมาได้สามเดือนฟ้าได้เข้ามาทิ้งขยะในที่ดินของน้ำอีก จึงถือว่าน้ำได้ถูก รบกวนการครอบครองอีก ดังนั้นน้ำจึงมีสิทธิฟ้องเป็นคดีต่อศาล เพื่อให้ศาลสั่งห้ามไม่ให้ฟ้านำขยะเข้ามา ทิ้งในที่ดินของน้ำได้ แต่ต้องฟ้องภายใน 1 ปี นับแต่วันที่ถูกรบกวนตามมาตรา 1374 วรรคสอง และตาม\n\nข้อเท็จจริงน้ำได้ฟ้องคดีต่อศาลหลังจากถูกฟ้ากระทำการดังกล่าวได้หนึ่งเดือน ดังนั้นน้ำจึงสามารถฟ้องศาล เพื่อสั่งให้ฟ้าเลิกทิ้งขยะในที่ดินของน้ำตามมาตรา 1374 ได้","conclusion":"สรุป ฟ้าได้ภาระจำยอมในถนนที่ฟ้าสร้างโดยการครอบครองปรปักษ์ น้ำจะฟ้องศาลเพื่อให้ศาลสั่ง ให้ฟ้ารื้อถนนที่ฟ้าสร้างออกไปไม่ได้ แต่น้ำสามารถฟ้องศาลเพื่อให้ศาลสั่งให้ฟ้าเลิกทิ้งขยะในที่ดินของน้ำ ได้","otherSections":["1374"]},{"id":"archive-2555-2-4-9","year":"2555","semester":"ภาค 2","number":4,"page":9,"course":"LAW2001 (LA 201 / LW 204)","title":"ปี 2555 ภาค 2 · ข้อ 4","sections":["1367","1375","1382","1387","1401"],"kind":"old-exam-source","source":"แนวข้อสอบเก่าวิชาทรัพย์สิน.pdf","question":"ข้อ 4. แสงทำนาบนที่ดินมือเปล่าแปลงหนึ่งของโสม โดยที่แสงเข้าในผิดคิดว่าเป็นที่ดินที่ซื้อมาจาก สอง และใช้ทางผ่านที่ดินสี่แปลงเพื่อเข้าไปทำนาบนที่ดินของโสมแปลงนั้น ที่ดินแปลงแรกที่เดินผ่านเป็น ของสี แปลงที่สองเป็นของสวย แปลงที่สามเป็นที่ดินซึ่งเตรียมไว้สร้างโรงพยาบาลของรัฐแต่ยังไม่ได้ ก่อสร้าง แปลงที่สี่เป็นที่ดินของสด แสงใช้ทางผ่านที่ดินของสี ของสวย ที่ดินของโรงพยาบาล และที่ดิน ของสดมาตลอดสิบกว่าปีแล้ว ต่อมาจังหวัดได้เข้ามาก่อสร้างโรงพยาบาล ตอนก่อสร้างอยู่หนึ่งปีกว่า แสง ต้องไปใช้ทางอื่นผ่านเข้าไปทำนาบนที่ดินแปลงที่แสงครอบครอง เมื่อสร้างโรงพยาบาลเสร็จ แสงกลับมาใช้ ทางผ่านทางเดิมของสี ของสวย ผ่านที่ดินของโรงพยาบาล และที่ดินของสดอีก สดห้ามไม่ให้แสงใช้ ทางผ่านที่ดินของตน เพราะว่าภาระจำยอมในที่ดินมือเปล่าที่ผ่านที่ดินของสดได้สิ้นไปแล้ว\n\nให้ท่านอธิบายกับแสงถึงสิทธิที่จะใช้ทางผ่านที่ดินทั้งสี่แปลงว่าแสง มีสิทธิหรือไม่มีสิทธิอย่างไร บ้าง เพราะเหตุใด และที่ดินของโสมที่แสงเข้าไปครอบครองทำนา โสมฟ้องศาลเรียกคืนได้หรือไม่ เพราะ เหตุใด","rule":"มาตรา 1367 บุคคลใดยึดถือทรัพย์สินโดยเจตนาจะยึดถือเพื่อตน ท่านว่าบุคคลนั้นได้ซึ่งสิทธิ ครอบครอง\n\nมาตรา 1375 ถ้าผู้ครอบครองถูกแย่งการครอบครองโดยมิชอบด้วยกฎหมายไซร้ ท่านว่าผู้ ครอบครองมีสิทธิจะได้คืนซึ่งการครอบครอง เว้นแต่อีกฝ่ายหนึ่งมีสิทธิเหนือทรัพย์สินดีกว่า ซึ่งจะเป็นเหตุ ให้เรียกคืนจากผู้ครอบครองได้ การฟ้องคดีเพื่อเอาคืนซึ่งการครอบครองนั้น ท่านว่าต้องฟ้องภายในหนึ่งปีนับแต่เวลาถูกแย่งการ ครอบครอง\n\nมาตรา 1382 บุคคลใดครอบครองทรัพย์สินของผู้อื่นไว้โดยความสงบและโดยเปิดเผยด้วยเจตนา เป็นเจ้าของ ถ้าเป็นอสังหาริมทรัพย์ได้ครอบครองติดต่อกันเป็นเวลาสิบปี ถ้าเป็นสังหาริมทรัพย์ได้ ครอบครองติดต่อกันเป็นเวลาห้าปีไซร้ ท่านว่าบุคคลนั้นได้กรรมสิทธิ์\n\nมาตรา 1387 อสังหาริมทรัพย์อาจต้องตกอยู่ในภาระจำยอมอันเป็นเหตุให้เจ้าของต้องยอมรับกรรม บางอย่างซึ่งกระทบถึงทรัพย์สินของตน หรือต้องงดเว้นการใช้สิทธิบางอย่างอันมีอยู่ในกรรมสิทธิ์ทรัพย์สิน นั้นเพื่อประโยชน์แก่อสังหาริมทรัพย์อื่น\n\nมาตรา 1399 ภาระจำยอมนั้น ถ้ามิได้ใช้สิบปี ท่านว่าย่อมสิ้นไป\n\nมาตรา 1401 ภาระจำยอมอาจได้มาโดยอายุความ ท่านให้นำบทบัญญัติว่าด้วยอายุความได้สิทธิอัน กล่าวไว้ในลักษณะ 3 แห่งบรรพนี้มาใช้บังคับโดยอนุโลม","application":"กรณีตามอุทาหรณ์ ประเด็นแรกที่ต้องวินิจฉัย คือ\n\nแสงมีสิทธิหรือไม่มีสิทธิอย่างไรบ้างที่จะใช้ทางผ่านที่ดินทั้งสี่แปลง เห็นว่า การที่แสงทำนาบน ที่ดินมือเปล่าแปลงหนึ่งของโสม โดยที่แสงเข้าใจผิดคิดว่าเป็นที่ดินของตนที่ซื้อมาจากสองนั้น ถือเป็นกรณี ที่แสงยึดถือที่ดินโดยเจตนาจะยึดถือเพื่อตน ดังนั้นแสงจึงได้สิทธิครอบครองในที่ดินของโสมตาม มาตรา 1367 เมื่อปรากฏข้อเท็จจริงว่า แสงใช้ทางผ่านที่ดินสี่แปลงเพื่อเข้าไปทำนาบนที่ดินของโสม โดยที่ดินแปลงแรก เป็นของสี แปลงที่สองเป็นของสวย แปลงที่สามเป็นที่ดินซึ่งเตรียมไว้สร้างโรงพยาบาลของรัฐ แต่ยังไม่ได้ ก่อสร้าง แปลงที่สี่เป็นที่ดินของสด\n\nดังนี้ การที่แสงใช้ทางผ่านที่ดินแปลงแรก แปลงที่สอง และแปลงที่สี่นั้น ย่อมถือว่าแสงผู้ ครอบครองสามยทรัพย์ได้ใช้ประโยชน์ในภารยทรัพย์โดยความสงบ เปิดเผย และมีเจตนาจะได้สิทธิภาระจำ ยอมในภารยทรัพย์แล้ว เมื่อแสงเดินผ่านที่ดินทั้งสามแปลงมาตลอด 10 ปีกว่าแล้ว ย่อมทำให้แสงได้ภาระจำ ยอมโดยการครอบครองปรปักษ์บนที่ดินของสี ของสวย และของสดตามมาตรา 1401 ประกอบ มาตรา 1382 และ 1387 ส่วนที่ดินแปลงที่สาม ซึ่งเตรียมสร้างโรงพยาบาลซึ่งเป็นของรัฐนั้นถือเป็นสาธารณ สมบัติของแผ่นดิน จึงครอบครองปรปักษ์ไม่ได้ ดังนั้นแม้แสงจะใช้เป็นทางเดินผ่านนานเท่าใดก็ย่อมไม่ได้ ภาระจำยอมโดยการครอบครองปรปักษ์ และรัฐย่อมมีสิทธิฟ้องไม่ให้แสงใช้ทางผ่านที่ดินได้ และเมื่อปรากฏว่า ต่อมาจังหวัดได้เข้ามาก่อสร้างโรงพยาบาล โดยใช้เวลาก่อสร้างอยู่หนึ่งปีกว่า และแสง ต้องไปใช้ทางอื่นผ่านเข้าไปทำนาบนที่ดินแปลงที่แสงครอบครอง ซึ่งเมื่อสร้างโรงพยาบาลเสร็จแสงก็ กลับมาใช้ทางผ่านทางเดิมของสี ของสวย ผ่านที่ดินของโรงพยาบาล และที่ดินของสดอีกนั้น กรณีนี้ยังไม่ ถือว่า ภาระจำยอมบนที่ดินทั้งสามแปลงของสี ของสวย และของสดนั้น สิ้นไปแต่อย่างใด เพราะตาม มาตรา 1399 นั้นได้กำหนดไว้ว่า ภาระจำยอมจะสิ้นไปโดยระยะเวลา ก็ต่อเมื่อมิได้มีการใช้ตั้งแต่สิบปีขึ้น ไป ดังนั้น แสงจึงมีสิทธิที่จะใช้ทางผ่านที่ดินทั้งสามแปลง สดจะห้ามไม่ไห้แสงใช้ทางผ่านที่ดินของตน ไม่ได้ ประเด็นที่สอง ที่ต้องวินิจฉัยคือ ที่ดินของโสมที่แสงเข้าไปครอบครองทำนา โสมฟ้องศาลเรียกคืนได้หรือไม่ เห็นว่า แม้ตามข้อเท็จจริง โสมจะถูกแสงแย่งการครอบครองที่ดินโดยมิชอบด้วยกฎหมาย ตามมาตรา 1375 วรรคแรก อันทำให้โสม ผู้ครอบครองที่ดินมีสิทธิฟ้องเรียกคืนที่ดินจากแสงได้ก็ตาม แต่การฟ้องคดีเพื่อเอาคืนซึงการครอบครอง นั้น มาตรา 1375 วรรคสอง กำหนดว่าจะต้องฟ้องภายในหนึ่งปีนับแต่เวลาถูกแย่งการครอบครอง\n\nดังนั้น เมื่อระยะเวลานับแต่วันที่แสงแย่งการครอบครองที่ดินมาจากโสมนั้น ล่วงเวลามาเกินหนึ่งปี แล้ว โสมจึงฟ้องเรียกคืนไม่ได้","conclusion":"สรุป แสงมีสิทธิหรือไม่มีสิทธิอย่างไรบ้างที่จะใช้ทางผ่านที่ดินทั้งสี่แปลงเป็นไปตามที่ได้อธิบายไว้ ข้างต้น และที่ดินของโสมที่แสงเข้าไปครอบครองทำนา โสมจะฟ้องศาลเรียกคืนไม่ได้","otherSections":["1399"]},{"id":"archive-2555-1-1-12","year":"2555","semester":"ภาค 1","number":1,"page":12,"course":"LAW2001 (LA 201 / LW 204)","title":"ปี 2555 ภาค 1 · ข้อ 1","sections":["1299"],"kind":"old-exam-source","source":"แนวข้อสอบเก่าวิชาทรัพย์สิน.pdf","question":"ข้อ 1. ชัยทำสัญญายกที่ดินมีโฉนดแปลงหนึ่งตีใช้หนี้ให้เชิดเจ้าหนี้ แต่ทั้งสองยังไม่ได้จดทะเบียนกับ พนักงานเจ้าหน้าที่ หลังจากชัยส่งมอบที่ดินให้เชิดครอบครองได้สามปี เกียรติเจ้าหนี้ของชัยได้ฟ้องศาลให้ ชัยชำระหนี้และศาลพิพากษาให้เกียรติชนะคดี เกียรติจึงนำเจ้าพนักงานบังคับคดีเข้ายึดที่ดินแปลงที่ชัยเคย ทำสัญญาตีใช้หนี้ให้เชิดไปแล้ว เพื่อออกขายทอดตลาดนำเงินมาใช้หนี้เกียรติ เชิดรู้เรื่องจึงร้องขัดทรัพย์โดยอ้างว่าเชิดเป็นเจ้าของที่ดินแปลงนั้น เพราะชัยเอาที่ดินนั้นตีใช้หนี้ให้ตน แล้ว เจ้าพนักงานบังคับคดีจึงไม่มีสิทธินำออกขายทอดตลาด\n\nดังนี้ ให้วินิจฉัยว่า เชิดจะร้องขัดทรัพย์ได้หรือไม่ เพราะเหตุใด","rule":"มาตรา 1299 วรรคแรก ภายในบังคับแห่งบทบัญญัติในประมวลกฎหมายนี้หรือกฎหมายอื่น ท่าน ว่า การได้มาโดยนิติกรรมซึ่งอสังหาริมทรัพย์หรือทรัพยสิทธิอันเกี่ยวกับอสังหาริมทรัพย์นั้นไม่ บริบูรณ์ เว้นแต่นิติกรรมจะได้ทำเป็นหนังสือและได้จดทะเบียนการได้มากับพนักงานเจ้าหน้าที่","application":"ตามกฎหมาย การได้มาซึ่งอสังหาริมทรัพย์หรือทรัพยสิทธิอันเกี่ยวกับอสังหาริมทรัพย์โดยทางนิติ กรรมนั้น จะบริบูรณ์เป็นทรัพยสิทธิได้ จะต้องทำเป็นหนังสือและจดทะเบียนการได้มากับพนักงาน เจ้าหน้าที่ ซึ่งถ้าฝ่าฝืนจะมีผลเป็นเพียงบุคคลสิทธิ ใช้กล่าวอ้างได้เฉพาะคู่สัญญาเท่านั้น ไม่สามารถยกขึ้น กล่าวอ้างต่อบุคคลภายนอกได้ (มาตรา 1299 วรรคแรก) กรณีตามอุทาหรณ์ การที่ชัยทำสัญญายกที่ดินมีโฉนดแปลงหนึ่งตีใช้หนี้ให้แก่เชิดนั้น ถือว่าเชิดเป็นผู้ได้มา ซึ่งทรัพยสิทธิอันเกี่ยวกับอสังหาริมทรัพย์โดยทางนิติกรรม เมื่อปรากฏว่าสัญญาดังกล่าวไม่ได้จดทะเบียน กับพนักงานเจ้าหน้าที่ นิติกรรมจึงไม่บริบูรณ์ในฐานะทรัพยสิทธิ เชิดจะยกสัญญานี้ขึ้นเป็นข้อต่อสู้ บุคคลภายนอกไม่ได้ แต่ยังคงมีผลบังคับระหว่างชัยกับเชิดในฐานะบุคคลสิทธิตามมาตรา 1299 วรรคแรก ดังนั้น เมื่อปรากฏข้อเท็จจริงว่า เกียรติเจ้าหนี้ของชัยได้ฟ้องศาลให้ชัยชำระหนี้ และศาลได้พิพากษาให้ เกียรติชนะคดี เกียรติจึงสามารถนำเจ้าพนักงานบังคับคดีเข้ายึดที่ดินแปลงที่ชัยเคยทำสัญญาตีใช้หนี้ ให้เชิด เพื่อออกขายทอดตลาดนำเงินมาใช้หนี้เกียรติได้ เชิดจะร้องขัดทรัพย์โดยอ้างว่าเชิดเป็นเจ้าของที่ดินแปลง นั้น เพราะชัยเอาที่ดินนั้นตีใช้หนี้ให้ตนแล้ว เจ้าพนักงานบังคับคดีจึงไม่มีสิทธินำออกขายทอดตลาด ไม่ได้ เพราะสัญญานำอสังหาริมทรัพย์คือที่ดินดังกล่าวตีใช้หนี้ไม่ได้จดทะเบียนการได้มากับพนักงาน เจ้าหน้าที่ การโอนกรรมสิทธิ์จึงถือว่าไม่บริบูรณ์ในฐานะทรัพยสิทธิ เชิดจึงเอาสัญญาดังกล่าวขึ้นต่อสู้ เกียรติไม่ได้\n\nดังนั้นเกียรติซึ่งเป็นเจ้าหนี้ตามคำพิพากษา และเป็นบุคคลภายนอกจึงมีสิทธิในที่ดินดีกว่าเชิด และ สามารถนำยึดที่ดินพิพาทได้","conclusion":"สรุป เชิดจะร้องขัดทรัพย์ไม่ได้","otherSections":[]},{"id":"archive-2555-1-3-13","year":"2555","semester":"ภาค 1","number":3,"page":13,"course":"LAW2001 (LA 201 / LW 204)","title":"ปี 2555 ภาค 1 · ข้อ 3","sections":["1367","1368","1377"],"kind":"old-exam-source","source":"แนวข้อสอบเก่าวิชาทรัพย์สิน.pdf","question":"ข้อ 3. พุธครอบครองที่ดินมือเปล่าแปลงหนึ่งร่วมกับนายศุกร์ เมื่อครอบครองไปได้หนึ่งปี พุธกับศุกร์ทำ สัญญาเป็นหนังสือตกลงขายส่วนของตนให้กับศุกร์ โดยพุธตกลงกับศุกร์ว่าตนยังไม่ต้องรื้อถอนบ้าน\n\nออกไป คงอยู่อาศัยในที่ดินนั้นต่อไปได้ พุธอยู่ต่อมาได้หนึ่งปี พุธได้ขายที่ดินแปลงนั้นให้จันทร์ โดยจันทร์ สุจริต เพราะเห็นพุธอยู่ในที่ดินแปลงนั้นมานานแล้ว และจันทร์เชื่อที่พุธบอกว่าศุกร์เช่าที่ดินแปลงนั้นจาก พุธ ต่อมาเมื่อศุกร์ไปยื่นขอออกโฉนดที่ดิน จันทร์ได้มาคัดค้าน\n\nตามข้อเท็จจริงนี้ ถ้าท่านเป็นศาล จะวินิจฉัยคดีนี้อย่างไร เพราะเหตุใด","rule":"มาตรา 1367 บุคคลใดยึดถือทรัพย์สินโดยเจตนาจะยึดถือเพื่อตน ท่านว่าบุคคลนั้นได้ซึ่งสิทธิ ครอบครอง\n\nมาตรา 1368 บุคคลอาจได้มาซึ่งสิทธิครอบครองโดยผู้อื่นยึดถือไว้ให้\n\nมาตรา 1377 วรรคหนึ่ง ถ้าผู้ครอบครองสละเจตนาครอบครอง หรือไม่ยึดถือทรัพย์สินต่อไป ไซร้ การครอบครองย่อมสิ้นสุดลง\n\nมาตรา 1380 การโอนไปซึ่งการครอบครองย่อมเป็นผลแม้ผู้โอนยังยึดถือทรัพย์สินอยู่ ถ้าผู้โอน แสดงเจตนาว่าต่อไปจะยึดถือทรัพย์สินนั้นแทนผู้รับโอน ถ้าทรัพย์สินนั้นผู้แทนของผู้โอนยึดถืออยู่ การโอนไปซึ่งการครอบครองจะทำโดยผู้โอนสั่งผู้แทนว่า ต่อไป ให้ยึดถือทรัพย์สินไว้แทนผู้รับโอนก็ได้","application":"กรณีตามอุทาหรณ์ การที่พุธทำสัญญาเป็นหนังสือตกลงขายที่ดินมือเปล่าส่วนของตนให้กับศุกร์ นั้น ถือว่าพุธได้สละการครอบครองในที่ดินแล้ว สิทธิการครอบครองที่ดินของพุธจึงสิ้นสุดลงตาม มาตรา 1377 วรรคแรก และถึงแม้พุธจะยังคงอาศัยอยู่ในที่ดินดังกล่าวต่อไป การโอนที่ดินดังกล่าวก็เป็นผล แล้ว เพราะเป็นการโอนตามมาตรา 1380 ซึ่งบัญญัติว่า การโอนไปซึ่งการครอบครองย่อมเป็นผลแม้ผู้โอนยัง ยึดถือทรัพย์สินอยู่ ถ้าผู้โอนแสดงเจตนาว่าต่อไปจะยึดถือทรัพย์สินนั้นแทนผู้รับโอน และกรณีนี้ถือเป็นกรณี ที่ศุกร์ได้สิทธิครอบครองที่ดินโดยมีผู้อื่นยึดถือไว้ให้ตามมาตรา 1368\n\nดังนั้น แม้พุธจะยังคงอาศัยอยู่ในที่ดินแปลงนั้นต่อไม่ ก็ไม่ทำให้ได้สิทธิครอบครองตาม มาตรา 1367 ศุกร์ย่อมมีสิทธิครอบครองที่ดินมือเปล่าแปลงนั้นดีกว่าพุธ เมื่อปรากฏข้อเท็จจริงว่า ต่อมาศุกร์ได้ไปยื่นขอออกโฉนดที่ดินแปลงนั้น กรณีนี้ถึงแม้พุธจะขายที่ดินแปลง นั้นให้จันทร์แล้ว โดยจันทร์สุจริต เพราะเห็นพุธอยู่ในที่ดินแปลงนั้นมานานแล้ว และเชื่อที่พุธบอกว่าศุกร์ เช่าที่ดินแปลงนั้นจากพุธก็ตาม แต่เมื่อที่ดินแปลงนั้นเป็นของศุกร์ซึ่งมีสิทธิยื่นขอออกโฉนดได้ จันทร์จึงไม่ มีสิทธิคัดค้าน เพราะถือว่าจันทร์รับโอนที่ดินแปลงนั้นมาจากผู้ที่ไม่มีสิทธิในที่ดินแต่อย่างใด","conclusion":"สรุป ถ้าข้าพเจ้าเป็นศาล จะวินิจฉัยคดีนี้ว่าศุกร์มีสิทธิที่จะยื่นขอออกโฉนดที่ดินแปลงนี้ได้ เพราะ ที่ดินเป็นของศุกร์ จันทร์ไม่มีสิทธิคัดค้าน","otherSections":["1380"]},{"id":"archive-2555-1-4-15","year":"2555","semester":"ภาค 1","number":4,"page":15,"course":"LAW2001 (LA 201 / LW 204)","title":"ปี 2555 ภาค 1 · ข้อ 4","sections":["1382","1387","1401"],"kind":"old-exam-source","source":"แนวข้อสอบเก่าวิชาทรัพย์สิน.pdf","question":"ข้อ 4. แดงเป็นเจ้าของที่ดินแปลงหนึ่ง แดงให้ดำเช่าที่ดินปลูกบ้านอาศัยอยู่ เมื่อเข้าไปปลูกบ้านบนที่ดิน แปลงนั้น ไฟฟ้ายังเข้าไม่ถึง แดงได้บอกให้ดำวางเสา สายไฟฟ้าผ่านที่ดินของขาวเข้าไปใช้ในที่ดินได้ โดย แดงบอกกับดำว่าตนได้ขออนุญาตขาวเจ้าของที่ดินแล้ว แต่ความจริงไม่ใช่ แดงไม่เคยขอหรือบอกขาวเลย ดำ จึงได้วางเสาและสายไฟฟ้าผ่านที่ดินของขาว นอกจากนั้นยังได้สร้างศาลาที่พักไว้หน้าที่ดินของขาว ดำเช่า ที่ดินปลูกบ้านและวางสายไฟฟ้ามาได้ห้าปี เหลืองได้มาขอซื้อบ้านหลังนี้จากดำและเช่าที่ดินของแดง ต่อ เหลืองซื้อบ้านและอยู่อาศัยในที่ดินแปลงนี้ ใช้เสาสายไฟฟ้าผ่านที่ดินของขาว และใช้ศาลาที่พักหน้า ที่ดินของขาวเพื่อขึ้นรถยนต์โดยสารประจำมาได้เจ็ดปี ขาวได้มาแจ้งให้เหลืองรื้อเสาไฟฟ้าและ สายไฟฟ้า และศาลาที่พักออกไปจากที่ดินของตน และทำที่ดินให้เป็นดังเดิม มิฉะนั้นจะฟ้องร้องต่อศาล\n\nให้ท่านให้คำแนะนำต่อเหลืองว่า เหลืองจะต้องรื้อเสา สายไฟฟ้า และศาลาออกไปหรือไม่ เพราะ เหตุใด","rule":"มาตรา 1382 บุคคลใดครอบครองทรัพย์สินของผู้อื่นไว้โดยความสงบและโดยเปิดเผยด้วยเจตนา เป็นเจ้าของ ถ้าเป็นอสังหาริมทรัพย์ได้ครอบครองติดต่อกันเป็นเวลาสิบปี ถ้าเป็นสังหาริมทรัพย์ได้ ครอบครองติดต่อกันเป็นเวลาห้าปีไซร้ ท่านว่าบุคคลนั้นได้กรรมสิทธิ์\n\nมาตรา 1387 อสังหาริมทรัพย์อาจต้องตกอยู่ในภาระจำยอมอันเป็นเหตุให้เจ้าของต้องยอมรับกรรม บางอย่างซึ่งกระทบถึงทรัพย์สินของตน หรือต้องงดเว้นการใช้สิทธิบางอย่างอันมีอยู่ในกรรมสิทธิ์ทรัพย์สิน นั้นเพื่อประโยชน์แก่อสังหาริมทรัพย์อื่น\n\nมาตรา 1401 ภาระจำยอมอาจได้มาโดยอายุความ ท่านให้นำบทบัญญัติว่าด้วยอายุความได้สิทธิอัน กล่าวไว้ในลักษณะ 3 แห่งบรรพนี้มาใช้บังคับโดยอนุโลม","application":"โดยหลัก การได้ภาระจำยอมโดยอายุความ เป็นการได้ทรัพยสิทธิเกี่ยวกับอสังหาริมทรัพย์โดยทาง อื่นนอกจากนิติกรรม ซึ่งตามมาตรา 1401 บัญญัติให้นำบทบัญญัติว่าด้วยอายุความได้สิทธิตาม มาตรา 1387 มาใช้บังคับโดยอนุโลม กล่าวคือ ต้องเป็นการครอบครองทรัพย์สินของผู้อื่นโดยความ สงบ เปิดเผย และเจตนาเป็นเจ้าของและครอบครองติดต่อกันเป็นเวลา 10 ปี แต่อย่างไรก็ตาม ภาระจำยอมจะเกิดมีขึ้นได้ก็เพื่อประโยชน์แก่อสังหาริมทรัพย์อื่นซึ่งเรียกว่าสามยทรัพย์ เท่านั้น ตามมาตรา 1387 ดังนั้น ถ้าเป็นการใช้อสังหาริมทรัพย์เพื่อประโยชน์ส่วนตัวแม้จะใช้ติดต่อกันนาน เกินกว่า 10 ปี ก็ไม่ทำให้เกิดภาระจำยอมโดยอายุความขึ้นได้ กรณีตามอุทาหรณ์ การที่แดงได้บอกให้ดำวางเสาและสายไฟฟ้าผ่านที่ดินของขาวเข้าไปใช้ในที่ดินได้ โดย แดงบอกกับดำว่าตนได้ขออนุญาตขาวเจ้าของที่ดินแล้ว แต่ความจริงแดงไม่เคยขอหรือบอกขาวเลย ดำจึง ได้วางเสาและสายไฟฟ้าผ่านที่ดินของขาวนั้น ถือเป็นกรณีที่ดำไม่ได้มีเจตนาจะยึดถือเป็นเจ้าของที่ดินของ ขาว เพื่อให้ได้ภาระจำยอมแต่อย่างใด เพราะการที่แดงบอกกับดำว่าตนได้ขออนุญาตขาวแล้วนั้น แสดงว่า\n\nการวางเสาและสายไฟฟ้าของดำ เป็นการแสดงเจตนาขออาศัยวางผ่านที่ดินของขาวเท่านั้น จึงไม่ก่อให้เกิด เจตนาปรปักษ์ อันจะทำให้ได้ภาระจำยอมมาโดยอายุความตามมาตรา 1401 ประกอบมาตรา 1382 ส่วนกรณีศาลาที่พักนั้น ถือเป็นการที่ดำสร้างขึ้นเพื่อประโยชน์ส่วนตัว ไม่ใช่เป็นการใช้ที่ดินของขาวเพื่อ ประโยชน์แก่อสังหาริมทรัพย์อื่นแต่อย่างใด จึงไม่ก่อให้เกิดภาระจำยอม ดังนั้นแม้ว่าดำจะใช้ศาลาที่พักนั้น นานเท่าใด ก็ไม่ทำให้ได้ภาระจำยอมเหนือที่ดินของขาวโดยอายุความปรปักษ์ตามมาตรา 1401 ประกอบ มาตรา 1382 และมาตรา 1387\n\nดังนั้น แม้จะปรากฏข้อเท็จจริงว่า เหลืองได้มาขอซื้อบ้านต่อจากดำและเช่าที่ดินแดงต่อโดยยังคงใช้ เสาและสายไฟฟ้าผ่านที่ดินของขาว และใช้ศาลาที่พักหน้าที่ดินของขาวเพื่อขึ้นรถยนต์โดยสารประจำมาได้ เจ็ดปีก็ตาม เหลืองก็ไม่สามารถนับอายุความภาระจำยอมต่อจากดำได้ เพราะการใช้ที่ดินของขาววางเสาและ สายไฟฟ้าดำไม่ได้มีเจตนาปรปักษ์ ส่วนการใช้ศาลาที่พักก็ไม่ก่อให้เกิดภาระจำยอม ดังนั้นเมื่อขาวเจ้าของ ที่ดินได้มาแจ้งให้เหลืองรื้อเสาและสายไฟฟ้า รวมทั้งศาลาที่พักออกไปจากที่ดินของตน และทำที่ดินให้เป็น ดังเดิม เหลืองจะต้องรื้อเสาไฟ สายไฟฟ้า และศาลาที่พักออกไป","conclusion":"สรุป ข้าพเจ้าจะให้คำแนะนำต่อเหลืองว่า เหลืองจะต้องรื้อเสาไฟฟ้า สายไฟฟ้า และศาลาออกไป จากที่ดินของขาว","otherSections":[]},{"id":"archive-2554-s-1-17","year":"2554","semester":"ภาคฤดูร้อน","number":1,"page":17,"course":"LAW2001 (LA 201 / LW 204)","title":"ปี 2554 ภาคฤดูร้อน · ข้อ 1","sections":["1299"],"kind":"old-exam-source","source":"แนวข้อสอบเก่าวิชาทรัพย์สิน.pdf","question":"ข้อ 1. เบี้ยวทำสัญญาอนุญาตให้กลมทำทางภาระจำยอมเป็นถนนผ่านที่ดินของเบี้ยว โดยไม่มีกำหนด ระยะเวลา แต่สัญญาดังกล่าวไม่ได้จดทะเบียนกับพนักงานเจ้าหน้าที่ หลังจากกลมใช้ทางภาระจำยอม ได้ 5 ปี เบี้ยวก็ถึงแก่ความตาย แบนบุตรของเบี้ยวได้จดทะเบียนรับมรดกที่ดินแปลงนั้นในฐานะทายาทโดย ธรรม และแบนได้ทำสัญญาขายที่ดินดังกล่าวให้กับสมปอง หลังจากจดทะเบียนรับโอนกรรมสิทธิ์แล้ว สมปองจึงห้ามไม่ให้กลมใช้ทางภาระจำยอมอีกต่อไป แต่กลม อ้างสัญญาที่ตนทำไว้กับเบี้ยวขึ้นต่อสู้ว่า ตนยังสามารถใช้ทางภาระจำยอมได้ต่อไป\n\nดังนี้สมปองจะห้ามไม่ให้กลมใช้ทางภาระจำยอมต่อไปได้หรือไม่ และข้อต่อสู้ของกลมรับฟังได้ หรือไม่ เพราะเหตุใด","rule":"มาตรา 1299 ภายในบังคับแห่งบทบัญญัติในประมวลกฎหมายนี้หรือกฎหมายอื่น ท่านว่า การ ได้มาโดยนิติกรรมซึ่งอสังหาริมทรัพย์หรือทรัพยสิทธิอันเกี่ยวกับอสังหาริมทรัพย์นั้นไม่บริบูรณ์ เว้นแต่นิติ กรรมจะได้ทำเป็นหนังสือและได้จดทะเบียนการได้มากับพนักงานเจ้าหน้าที่","application":"ตามกฎหมาย การได้มาซึ่งอสังหาริมทรัพย์หรือทรัพยสิทธิอันเกี่ยวกับอสังหาริมทรัพย์โดยทางนิติ กรรมนั้น จะบริบูรณ์เป็นทรัพยสิทธิได้ จะต้องทำเป็นหนังสือและจดทะเบียนการได้มากับพนักงาน เจ้าหน้าที่ ซึ่งถ้าฝ่าฝืนจะมีผลเป็นเพียงบุคคลสิทธิ ใช้กล่าวอ้างได้เฉพาะคู่สัญญาเท่านั้น ไม่สามารถยกขึ้น กล่าวอ้างต่อบุคคลภายนอกได้ (มาตรา 1299 วรรคแรก) กรณีตามอุทาหรณ์ การที่เบี้ยวทำสัญญาอนุญาตให้กลมทำทางภาระจำยอมเป็นถนนผ่านที่ดินของเบี้ยวโดย ไม่มีกำหนดระยะเวลานั้น กลมจึงเป็นผู้ได้มาซึ่งทรัพยสิทธิอันเกี่ยวกับอสังหาริมทรัพย์โดยทางนิติ กรรม แต่เมื่อปรากฏว่าสัญญาดังกล่าวไม่ได้จดทะเบียนกับพนักงานเจ้าหน้าที่ นิติกรรมจึงไม่บริบูรณ์ใน ฐานะทรัพยสิทธิ และจะยกขึ้นเป็นข้อต่อสู้บุคคลภายนอกไม่ได้ แต่ยังคงมีผลบังคับระหว่างเบี้ยวกับกลม ซึ่งเป็นคู่สัญญาในฐานะบุคคลสิทธิตามมาตรา 1299 วรรคแรก ต่อมาเมื่อเบี้ยวถึงแก่ความตาย แบนบุตรของเบี้ยวได้จดทะเบียนรับมรดกที่ดินแปลงนั้นในฐานะทายาทโดย ธรรม อันเป็นการรับทรัพย์มรดกตามกฎหมายว่าด้วยมรดก ดังนั้น แบนผู้รับมรดกจึงต้องรับไปทั้งสิทธิ และหน้าที่ของเบี้ยวเจ้ามรดกที่มีต่อกลมดังกล่าวด้วย\n\nอย่างไรก็ตาม เมื่อปรากฏข้อเท็จจริงว่า แบนได้ทำสัญญาขายที่ดินดังกล่าวให้กับสมปอง และสมปองได้จด ทะเบียนรับโอนกรรมสิทธิ์แล้ว สมปองย่อมเป็นเจ้าของกรรมสิทธิ์ในที่ดินแปลงนั้น และถือเป็น บุคคลภายนอก\n\nดังนั้น เมื่อภาระจำยอมดังกล่าวไม่บริบูรณ์ในฐานะทรัพยสิทธิ จึงไม่สามารถบังคับใช้กับสมปอง ซึ่งเป็นบุคคลภายนอกได้ สมปองในฐานะเจ้าของกรรมสิทธิ์จึงมีสิทธิห้ามไม่ให้กลมใช้ทางภาระจำยอม ต่อไปได้ และข้อต่อสู้ของกลมที่ว่าตนทำสัญญาไว้กับเบี้ยวจึงยังสามารถใช้ทางภาระจำยอมได้ต่อไปนั้นรับ ฟังไม่ได้ เพราะกลมไม่สามารถยกสัญญาที่ไม่บริบูรณ์นั้นขึ้นต่อสู้กับสมปองได้ตามเหตุผลที่กล่าวแล้ว ข้างต้น","conclusion":"สรุป สมปองจะห้ามไม่ให้กลมใช้ทางภาระจำยอมต่อไปได้ และข้อต่อสู้ของกลมรับฟังไม่ได้","otherSections":[]},{"id":"archive-2554-s-2-18","year":"2554","semester":"ภาคฤดูร้อน","number":2,"page":18,"course":"LAW2001 (LA 201 / LW 204)","title":"ปี 2554 ภาคฤดูร้อน · ข้อ 2","sections":["144"],"kind":"old-exam-source","source":"แนวข้อสอบเก่าวิชาทรัพย์สิน.pdf","question":"ข้อ 2. มั่นได้ซื้อพระเครื่ององค์หนึ่งในราคา 5,000 บาท จากร้านพุทธศิลป์ซึ่งเปิดร้านจำหน่ายพระเครื่องและ วัตถุมงคลที่ข้างวัดมหาธาตุ ท่าพระจันทร์ ซึ่งเป็นแหล่งจำหน่ายพระเครื่องและวัตถุมงคลต่างๆ โดยมั่นไม่รู้ ว่าพระเครื่ององค์ดังกล่าวเป็นของเมฆที่ถูกคนร้ายขโมยไป และนำไปขายที่ร้านพุทธศิลป์ในราคา 2,000 บาท หลังจากซื้อพระเครื่องดังกล่าวแล้ว มั่นได้นำไปใส่กรอบ ทองคำเป็นเงิน 20,000 บาท ต่อมาเจ้าหน้าที่ตำรวจจับคนร้ายได้ และสืบทราบว่าพระของกลางอยู่ที่ มั่น ดังนี้ ให้วินิจฉัยว่า เมฆจะเรียกให้มั่นคืนพระเครื่ององค์นั้นพร้อมกรอบทองให้กับตนได้หรือไม่ และ ระหว่างมั่นกับเมฆมีสิทธิเรียกร้องใดๆต่อกันได้บ้าง เพราะเหตุใด","rule":"มาตรา 144 ส่วนควบของทรัพย์ หมายความว่า ส่วนซึ่งโดยสภาพแห่งทรัพย์หรือโดยจารีตประเพณี แห่งท้องถิ่นเป็นสาระสำคัญในความเป็นอยู่แห่งทรัพย์นั้น และไม่อาจแยกจากกันได้นอกจากจะทำลาย ทำ ให้บุบสลาย หรือทำให้ทรัพย์นั้นเปลี่ยนแปลงรูปทรงหรือสภาพไป เจ้าของทรัพย์ย่อมมีกรรมสิทธิ์ในส่วนควบของทรัพย์นั้น\n\nมาตรา 1332 บุคคลผู้ซื้อทรัพย์สินมาโดยสุจริตในการขายทอดตลาด หรือในท้องตลาด หรือจาก พ่อค้าซึ่งขายของชนิดนั้น ไม่จำต้องคืนให้แก่เจ้าของแท้จริง เว้นแต่เจ้าของจะชดใช้ราคาที่ซื้อมา","application":"ตามกฎหมาย บุคคลผู้ซื้อทรัพย์สินมาโดยสุจริตจากการขายทอดตลาดของเอกชน หรือใน ท้องตลาด หรือจากพ่อค้าซึ่งขายของชนิดนั้น ย่อมได้รับความคุ้มครองตามมาตรา 1332 คือ แม้เจ้าของ ทรัพย์สินที่แท้จริงจะติดตามทวงคืน ก็ไม่จำต้องคืนทรัพย์สินให้แก่เจ้าของ เว้นแต่เจ้าของทรัพย์สินนั้นจะ ชดใช้ราคาที่ตนซื้อมา กรณีตามอุทาหรณ์ การที่มั่นซื้อพระเครื่องดังกล่าวจากร้านพุทธศิลป์ซึ่งเปิดร้านจำหน่ายพระเครื่องและวัตถุ มงคลที่ข้างวัดมหาธาตุ ท่าพระจันทร์ ซึ่งเป็นแหล่งจำหน่ายพระเครื่องและวัตถุมงคลต่างๆ โดยมั่นไม่รู้ว่า\n\nพระเครื่ององค์นั้นเป็นของเมฆที่ถูกคนร้ายขโมยไปและนำไปขายที่ร้านพุทธศิลป์นั้น มั่นย่อมเป็นบุคคลผู้ ซื้อทรัพย์สินมาโดยสุจริตจากท้องตลาด และจากพ่อค้าซึ่งขายสินค้าชนิดนั้น ดังนั้นมั่นจึงได้รับความ คุ้มครองตามมาตรา 1332 คือ มั่นไม่จำต้องคืนพระเครื่ององค์นั้นให้กับเมฆ แม้เมฆจะเป็นเจ้าของที่แท้จริงก็ ตาม เว้นเสียแต่ว่าเมฆจะชดใช้ราคาพระเครื่องที่มั่นได้ซื้อมา คือ 5,000 บาท เมฆจึงจะสามารถเรียกให้มั่น คืนพระเครื่ององค์นั้นได้ ส่วนกรณีที่มั่นนำพระเครื่องไปใส่กรอบทองคำเป็นเงิน 20,000 บาทนั้น เมื่อปรากฏว่ากรอบพระทองคำ ไม่ใช่สาระสำคัญในความเป็นอยู่ของพระเครื่อง จึงไม่ถือเป็นส่วนควบของพระเครื่อง ตามมาตรา 144 อัน จะทำให้เมฆเจ้าของทรัพย์ได้กรรมสิทธิ์ในกรอบพระทองคำด้วยแต่อย่างใด\n\nดังนั้น กรอบพระทองคำจึงยังคงเป็นกรรมสิทธิ์ของมั่น เมฆไม่มีสิทธิเรียกเอากรอบพระทองคำ จากมั่น","conclusion":"สรุป หากเมฆต้องการจะเรียกให้มั่นคืนพระเครื่อง จะต้องชดใช้เงินให้แก่มั่น 5,000 บาท ส่วนกรอบ พระทองคำนั้น เมฆไม่มีสิทธิเรียกเอากรอบพระทองคำจากมั่น","otherSections":["1332"]},{"id":"archive-2554-s-3-19","year":"2554","semester":"ภาคฤดูร้อน","number":3,"page":19,"course":"LAW2001 (LA 201 / LW 204)","title":"ปี 2554 ภาคฤดูร้อน · ข้อ 3","sections":["1382"],"kind":"old-exam-source","source":"แนวข้อสอบเก่าวิชาทรัพย์สิน.pdf","question":"ข้อ 3. นายแมนเข้าไปทำนาในที่ดินมีโฉนดแปลงหนึ่งของนางมั่งมีมาได้ 4 ปี ต่อมานายแมนถูกศาลพิพากษา จำคุกเป็นเวลา 1 ปี 6 เดือน เมื่อออกจากคุกแล้ว นายแมนได้เข้าไปครอบครองทำนาในที่ดินของนางมั่งมี อีก 4 ปี 6 เดือน\n\nให้ท่านวินิจฉัยว่า นายแมนอ้างกรรมสิทธิ์ในการครอบครองปรปักษ์บนที่ดินของนางมั่งมีได้ หรือไม่ จงอธิบาย","rule":"มาตรา 1382 บุคคลใดครอบครองทรัพย์สินของผู้อื่นไว้โดยความสงบและโดยเปิดเผยด้วยเจตนา เป็นเจ้าของ ถ้าเป็นอสังหาริมทรัพย์ได้ครอบครองติดต่อกันเป็นเวลาสิบปี ถ้าเป็นสังหาริมทรัพย์ได้ ครอบครองติดต่อกันเป็นเวลาห้าปีไซร้ ท่านว่าบุคคลนั้นได้กรรมสิทธิ์\n\nมาตรา 1384 “ถ้าผู้ครอบครองขาดยึดถือทรัพย์สินโดยไม่สมัคร และได้คืนภายในเวลาหนึ่งปีนับแต่ วันขาดยึดถือ หรือได้คืนโดยฟ้องคดีภายในกำหนดนั้นไซร้ ท่านมิให้ถือว่าการครอบครองสะดุดหยุดลง”","application":"กรณีตามอุทาหรณ์ โดยหลักแล้วการได้กรรมสิทธิ์ในอสังหาริมทรัพย์โดยการครอบครองปรปักษ์ตาม\n\nมาตรา 1382 จะประกอบด้วยหลักเกณฑ์ดังนี้ 1. เป็นทรัพย์สินของผู้อื่น โดยผู้อื่นมีกรรมสิทธิ์ 2. ได้ครอบครองโดยความสงบ 3. ครอบครองโดยเปิดเผย 4. ครอบครองโดยเจตนาเป็นเจ้าของ\n\n5. ครอบครองติดต่อกันมาเป็นเวลา 10 ปี สำหรับการครอบครองติดต่อกันนั้น จะต้องเป็นกรณีที่ผู้ครอบครองได้ครอบครองหรือยึดถือทรัพย์สินนั้น ตลอดเรื่อยมาโดยไม่มีเจตนาสละการครอบครอง หรือขาดการยึดถือโดยใจสมัครในบางช่วงบางตอน และ ถ้าหากเป็นการขาดการยึดถือโดยไม่สมัครใจ เพราะมีเหตุมาขัดขวาง กฎหมายถือว่าการขาดการยึดถือนั้น ไม่ทำให้อายุความการครอบครองสะดุดหยุดลง หากได้ทรัพย์สินคืนภายใน 1 ปี นับแต่วันที่ขาดการ ยึดถือ ทั้งนี้ตามมาตรา 1384 กรณีตามอุทาหรณ์ ประเด็นที่ต้องวินิจฉัยมีว่า นายแมนจะอ้างกรรมสิทธิ์ในการครอบครองปรปักษ์บนที่ดิน ของนางมั่งมีได้หรือไม่ เห็นว่า การที่นายแมนเข้าไปครอบครองปรปักษ์ทำนาในที่ดินมีโฉนดของนางมั่งมี มาได้ 4 ปี และต่อมาได้ถูกศาลพิพากษาจำคุกนั้น ถือเป็นกรณีที่นายแมนขาดการยึดถือที่ดินโดยไม่สมัคร ใจ เนื่องจากมีเหตุมาขัดขวางหรือไม่มีเจตนาสละการครอบครอง แต่อย่างไรก็ตาม เมื่อปรากฏว่านายแมน ไม่อาจกลับเข้าครอบครองที่ดินอีกได้ภายใน 1 ปี นับแต่วันที่ขาดการยึดถือ เนื่องจากศาลพิพากษาจำคุกนาย แมน 1 ปี 6 เดือน จึงมีผลทำให้การครอบครองของนายแมนสิ้นสุดลง ตามมาตรา 1384 ดังนั้น แม้ต่อมานายแมนจะพ้นโทษจำคุก และกลับเข้าครอบครองปรปักษ์ที่ดินของนางมั่งมีอีก นายแมนก็ ไม่สามารถจะนำระยะเวลาการครอบครองเดิม (4 ปี) มานับรวมกับการครอบครองขณะตนถูก จำคุก (1 ปี 6 เดือน) และภายหลังออกจากคุก (4 ปี 6 เดือน) ได้ หากนายแมนจะนับก็ต้องเริ่มนับตั้งแต่เมื่อ ออกจากคุกแล้วมาครอบครองใหม่ จึงเท่ากับนายแมนเพิ่งครอบครองปรปักษ์ได้เพียง 4 ปี 6 เดือ ซึ่งยังไม่ ครบ 10 ปี นายแมนจึงยังไม่ได้กรรมสิทธิ์ในการครอบครองปรปักษ์ที่ดินของนางมั่งมีตาม มาตรา 1382 ดังนั้น นายแมนจะอ้างกรรมสิทธิ์ในการครอบครองปรปักษ์ที่ดินของนางมั่งมีไม่ได้","conclusion":"สรุป นายแมนอ้างกรรมสิทธิ์ในการครอบครองปรปักษ์บนที่ดินของนางมั่งมีไม่ได้","otherSections":["1384"]},{"id":"archive-2554-s-4-20","year":"2554","semester":"ภาคฤดูร้อน","number":4,"page":20,"course":"LAW2001 (LA 201 / LW 204)","title":"ปี 2554 ภาคฤดูร้อน · ข้อ 4","sections":["1387","1299"],"kind":"old-exam-source","source":"แนวข้อสอบเก่าวิชาทรัพย์สิน.pdf","question":"ข้อ 4. จันทร์จดทะเบียนภาระจำยอมให้อังคารใช้น้ำในบ่อน้ำซึ่งอยู่ในที่ดินของจันทร์ได้ หลังจากที่อังคารใช้ น้ำจากบ่อของจันทร์มาได้ 5 ปี อังคารก็ไม่เคยมาใช้น้ำจากบ่อน้ำนี้อีกถึง 5 ปี ต่อมาอังคารขายที่ดินให้กับ พุธ เมื่อพุธซื้อที่ดินแล้วจึงมาใช้น้ำในที่ดินของจันทร์\n\nดังนี้ จันทร์จะไม่อนุญาตให้พุธนำน้ำจากบ่อน้ำของตนไปใช้ได้หรือไม่ จงอธิบาย","rule":"มาตรา 1387 อสังหาริมทรัพย์อาจต้องตกอยู่ในภาระจำยอมอันเป็นเหตุให้เจ้าของต้องยอมรับกรรม บางอย่างซึ่งกระทบถึงทรัพย์สินของตน หรือต้องงดเว้นการใช้สิทธิบางอย่างอันมีอยู่ในกรรมสิทธิ์ทรัพย์สิน นั้นเพื่อประโยชน์แก่อสังหาริมทรัพย์อื่น\n\nมาตรา 1399 ภาระจำยอมนั้น ถ้ามิได้ใช้สิบปี ท่านว่าย่อมสิ้นไป","application":"ตามกฎหมาย ภาระจำยอมนั้นเป็นทรัพย์สินที่มีขึ้นเพื่อประโยชน์กับอสังหาริมทรัพย์ อื่น (มาตรา 1387) ดังนั้น ภาระจำยอมจึงตกติดไปกับอสังหาริมทรัพย์ทั้งภารทรัพย์และสามยทรัพย์ เสมอ ไม่ว่าอสังหาริมทรัพย์ทั้งสองนั้นจะโอนไปเป็นของบุคคลใด เว้นแต่จะตกลงกันเป็นอย่างอื่น และ หากไม่ได้ใช้ภาระจำยอมติดต่อกันเป็นเวลา 10 ปี ภาระจำยอมนั้นย่อมระงับสิ้นไปตามมาตรา 1399 ซึ่งถือ เป็นอายุความเสียสิทธิ กรณีตามอุทาหรณ์ การที่จันทร์จดทะเบียนภาระจำยอมให้อังคารมีสิทธิใช้น้ำในบ่อน้ำ ซึ่งอยู่ในที่ดินของ จันทร์ได้นั้น ภาระจำยอมดังกล่าวย่อมบริบูรณ์เป็นทรัพยสิทธิ (มาตรา 1299 วรรคแรก) และการที่อังคาร ได้ใช้น้ำจากบ่อน้ำในที่ดินของจันทร์เพียง 5 ปี แล้วก็ไม่เคยมาใช้น้ำจากบ่อน้ำนี้อีกเลยเป็นเวลาถึง 5 ปี นั้น เมื่อปรากฏว่าการที่ไม่ได้ใช้ภาระจำยอมนั้นยังไม่ถึง 10 ปี จึงยังไม่มีผลทำให้ภาระจำยอมที่มีอยู่ระงับ ไปตามมาตรา 1399 และเมื่อปรากฏข้อเท็จจริงว่าต่อมาอังคารขายที่ดินให้กับพุธ พุธผู้รับโอนที่ดินมาจึงเป็นเจ้าของกรรมสิทธิ์ ในที่ดินและมีสิทธิในภาระจำยอมดังกล่าว คือ มีสิทธิเข้าไปใช้น้ำจากบ่อน้ำในที่ดินของจันทร์ ได้ (มาตรา 1387) ดังนั้น เมื่อภาระจำยอมดังกล่าวเป็นทรัพยสิทธิ ผูกพันอยู่กับทรัพย์สินที่เป็น อสังหาริมทรัพย์ จันทร์จึงไม่มีสิทธิห้ามพุธไม่ให้มาใช้น้ำจากบ่อน้ำซึ่งอยู่ในที่ดินของตนได้","conclusion":"สรุป จันทร์จะไม่อนุญาตให้พุธนำน้ำจากบ่อน้ำของตนไปใช้ไม่ได้","otherSections":["1399"]},{"id":"archive-2554-1-1-22","year":"2554","semester":"ภาค 1","number":1,"page":22,"course":"LAW2001 (LA 201 / LW 204)","title":"ปี 2554 ภาค 1 · ข้อ 1","sections":["144","146","1299"],"kind":"old-exam-source","source":"แนวข้อสอบเก่าวิชาทรัพย์สิน.pdf","question":"ข้อ 1. เข้มทำสัญญาอนุญาตให้ป้อมสร้างบ้านอยู่ในที่ดินมีโฉนดของตนเป็นเวลา 20 ปี โดยสัญญามีข้อความ ระบุว่า เมื่อครบกำหนด 20 ปีแล้วให้บ้านตกเป็นกรรมสิทธิ์ของเข้มเจ้าของที่ดินทันที แต่สัญญาดังกล่าว ไม่ได้จดทะเบียนกับพนักงานเจ้าหน้าที่ หลังจากป้อมสร้างบ้านอยู่ในที่ดินของเข้มครบกำหนด 20 ปี แล้ว เข้มแจ้งให้ป้อมย้ายออกไปจากบ้านและที่ดินนั้น เพราะต้องการจะขายบ้านและที่ดินนั้น แต่ป้อมยังคงอาศัยอยู่ในบ้านและที่ดินต่อไป หลังจากนั้นอีก 5 เดือนเข้มได้ทำสัญญาและจดทะเบียนกับ พนักงานเจ้าหน้าที่ขายบ้านพร้อมที่ดินนั้นให้แหม่ม เมื่อป้อมรู้เรื่องดังกล่าว ป้อมจึงทำสัญญาขายบ้านหลัง นั้นให้แตน โดยให้แตนรื้อถอนบ้านออกไป ดังนี้\n\nให้วินิจฉัยว่า แตนจะรื้อถอนบ้านออกไปได้หรือไม่ และระหว่างแตนกับแหม่มผู้ใดมีกรรมสิทธิ์ใน บ้านพิพาทดีกว่ากัน เพราะเหตุใด","rule":"มาตรา 144 ส่วนควบของทรัพย์ หมายความว่า ส่วนซึ่งโดยสภาพแห่งทรัพย์หรือโดยจารีตประเพณี แห่งท้องถิ่นเป็นสาระสำคัญในความเป็นอยู่ของทรัพย์นั้น และไม่อาจแยกจากกันได้นอกจากจะทำลาย ทำ ให้บุบสลาย หรือทำให้ทรัพย์นั้นเปลี่ยนแปลงรูปทรงหรือสภาพไป เจ้าของทรัพย์ย่อมมีกรรมสิทธิ์ในส่วนควบของทรัพย์นั้น\n\nมาตรา 146 ทรัพย์ซึ่งติดกับที่ดินหรือติดกับโรงเรือนเพียงชั่วคราวไม่ถือว่าเป็นส่วนควบกับที่ดิน หรือโรงเรือนนั้น ความข้อนี้ให้ใช้บังคับแก่โรงเรือนหรือสิ่งปลูกสร้างอย่างอื่น ซึ่งผู้มีสิทธิในที่ดินของผู้อื่น ใช้สิทธินั้นปลูกสร้างไว้ในที่ดินนั้นด้วย\n\nมาตรา 1299 วรรคแรก ภายในบังคับแห่งบทบัญญัติในประมวลกฎหมายนี้หรือกฎหมายอื่น ท่าน ว่า การได้มาโดยนิติกรรมซึ่งอสังหาริมทรัพย์หรือทรัพยสิทธิอันเกี่ยวกับอสังหาริมทรัพย์นั้นไม่บริบูรณ์ เว้น แต่นิติกรรมจะได้ทำเป็นหนังสือและได้จดทะเบียนการได้มากับพนักงานเจ้าหน้าที่","application":"ตามกฎหมาย การได้มาซึ่งอสังหาริมทรัพย์หรือทรัพยสิทธิอันเกี่ยวกับอสังหาริมทรัพย์โดยทางนิติ กรรมนั้น จะบริบูรณ์เป็นทรัพยสิทธิได้ จะต้องทำเป็นหนังสือและจดทะเบียนการได้มากับพนักงาน เจ้าหน้าที่ ซึ่งถ้าฝ่าฝืนจะมีผลเป็นเพียงบุคคลสิทธิ ใช้กล่าวอ้างได้เฉพาะคู่สัญญาเท่านั้น ไม่สามารถยกขึ้น กล่าวอ้างต่อบุคคลภายนอกได้ (มาตรา 1299 วรรคแรก) กรณีตามอุทาหรณ์ การที่เข้มทำสัญญาอนุญาตให้ป้อมสร้างบ้านในที่ดินมีโฉนดของตนเป็นเวลา 20 ปี ป้อม จึงเป็นผู้มีสิทธิเหนือพื้นดินของเข้ม อันเป็นการได้มาซึ่งทรัพยสิทธิอันเกี่ยวกับอสังหาริมทรัพย์โดยทางนิติ\n\nกรรม เมื่อปรากฏว่านิติกรรมดังกล่าวเพียงแต่ทำเป็นหนังสือไม่ได้จดทะเบียนกับพนักงานเจ้าหน้าที่ ย่อมมี ผลทำให้นิติกรรมนั้นไม่บริบูรณ์ในฐานะทรัพยสิทธิ แต่ยังคงมีผลบังคับระหว่างเข้มกับป้อมในฐานะบุคคล สิทธิตามมาตรา 1299 วรรคแรก ดังนั้น บ้านจึงยังไม่เป็นส่วนควบของที่ดิน เพราะป้อมเป็นผู้มีสิทธิในที่ดิน ของผู้อื่นและได้ใช้สิทธินั้นปลูกสร้างไว้ตามมาตรา 146 แต่อย่างไรก็ตาม เมื่อครบกำหนด 20 ปี สิทธิในที่ดินของเข้มที่ป้อมมีอยู่ย่อมสิ้นสุดลง เนื่องจากข้อความใน สัญญากำหนดให้บ้านตกเป็นกรรมสิทธิ์ของเข้มทันทีเมื่อครบ 20 ปี จึงเท่ากับป้อมได้แสดงเจตนาสละ กรรมสิทธิ์ในบ้านไว้ล่วงหน้าแล้ว\n\nดังนั้น บ้านจึงตกเป็นกรรมสิทธิ์ของเข้มในฐานะที่เป็นส่วนควบของที่ดินตามมาตรา 144 เข้มจึงมี สิทธิทำสัญญาและจดทะเบียนขายบ้านพร้อมที่ดินให้กับแหม่มได้ และแหม่มผู้รับโอนย่อมมีกรรมสิทธิ์ใน บ้านและที่ดินนั้นโดยสมบูรณ์ ส่วนกรณีของแตนนั้นเมื่อป้อมไม่มีกรรมสิทธิ์ในบ้านหลังดังกล่าวแล้ว ป้อมจึงไม่สามารถนำบ้านไปทำ สัญญาขายให้กับแตนได้ ดังนั้น แตนผู้รับโอนตามสัญญาซื้อขายจึงไม่มีสิทธิในบ้านดีไปกว่าป้อมผู้โอนและ ไม่สามารถรื้อถอนบ้านออกไปได้","conclusion":"สรุป แหม่มเป็นผู้ที่มีกรรมสิทธิ์ในบ้านพิพาทดีกว่าแตน และแตนไม่สามารถรื้อถอนบ้านออกไป จากที่ดินนั้นได้","otherSections":[]},{"id":"archive-2554-1-4-25","year":"2554","semester":"ภาค 1","number":4,"page":25,"course":"LAW2001 (LA 201 / LW 204)","title":"ปี 2554 ภาค 1 · ข้อ 4","sections":["1382"],"kind":"old-exam-source","source":"แนวข้อสอบเก่าวิชาทรัพย์สิน.pdf","question":"ข้อ 4. แสงดาวซื้อที่ดินแปลงหนึ่งมาจากสันทราย โดยแสงดาวคิดว่าที่ดินแปลงนี้เป็นที่ดินมือเปล่ายังไม่มี โฉนด เมื่อสันทรายส่งมอบการครอบครองให้ แสงดาวจึงเข้าไปปลูกบ้านครอบครองทำไร่อ้อยอยู่บนที่ดิน แปลงนั้น ความจริงที่ดินแปลงนั้นเป็นที่ดินมีโฉนดเป็นกรรมสิทธิ์ของสุดสวย สันทรายได้ครอบครองทำ ประโยชน์มาเป็นเวลากว่าห้าปี ก่อนที่จะขายให้แสงดาว แต่ในระหว่างห้าปีสุดสวยเจ้าของที่ดินได้มาล้อม รั้วลวดหนามเพื่อมิให้ใครเข้ามาบุกรุกที่ดินแปลงนั้น ทำให้สันทรายเข้าไปทำไร่ไม่ได้อยู่เก้าเดือน เมื่อรั้วพัง ลงสันทรายจึงเข้าไปทำไร่ต่อได้สามปี หลังจากนั้นได้ขายที่ดินแปลงนั้นให้แสงดาว แสงดาวปลูกบ้านทำไร่ อ้อยมาได้ห้าปี สุดสวยได้ให้แสงดาวออกไปจากที่ดินแปลงนั้น แสงดาวไม่ยอมออกไปจากที่ดินแปลง นั้น โดยอ้างว่าสุดสวยหมดระยะเวลาเรียกคืนการครอบครองที่ดินแปลงนั้นจากตนแล้ว\n\nข้ออ้างของแสงดาวรับฟังได้หรือไม่ ให้นักศึกษาอธิบาย","rule":"มาตรา 1382 บุคคลใดครอบครองทรัพย์สินของผู้อื่นไว้โดยความสงบและโดยเปิดเผยด้วยเจตนา เป็นเจ้าของ ถ้าเป็นอสังหาริมทรัพย์ได้ครอบครองติดต่อกันเป็นเวลาสิบปี ถ้าเป็นสังหาริมทรัพย์ได้ ครอบครองติดต่อกันเป็นเวลาห้าปีไซร้ ท่านว่าบุคคลนั้นได้กรรมสิทธิ์\n\nมาตรา 1385 ถ้าโอนการครอบครองแก่กัน ผู้รับโอนจะนับเวลาซึ่งผู้โอนครอบครองอยู่ก่อนนั้น รวมเข้ากับเวลาครอบครองของตนก็ได้ ถ้าผู้รับโอนนับรวมเช่นนั้น และถ้ามีข้อบกพร่องในระหว่าง ครอบครองของผู้โอนไซร้ ท่านว่าข้อบกพร่องนั้นอาจยกขึ้นเป็นข้อต่อสู้ผู้รับโอนได้","application":"โดยหลักแล้ว การได้กรรมสิทธิ์ในอสังหาริมทรัพย์โดยการครอบครองปรปักษ์ตาม\n\nมาตรา 1382 จะต้องประกอบด้วยหลักเกณฑ์ดังนี้ คือ 1. เป็นทรัพย์สินของผู้อื่นโดยผู้อื่นมีกรรมสิทธิ์ 2. ได้ครอบครองโดยความสงบ 3. ครอบครองโดยเปิดเผย 4. ครอบครองโดยเจตนาเป็นเจ้าของ 5. ครอบครองติดต่อกันมาเป็นเวลา 10 ปี\n\nกรณีตามอุทาหรณ์ การที่สันทรายได้ครอบครองทำประโยชน์ในที่ดินของสุดสวยมาเป็นเวลากว่า ห้าปีก่อนที่จะขายให้แสงดาวนั้น เมื่อปรากฏว่าในระหว่างห้าปีสุดสวยได้มาล้อมรั้วลวดหนามในที่ดินแปลง นั้น ทำให้สันทรายเข้าไปทำไร่ไม่ได้อยู่เก้าเดือน และเมื่อรั้วพังลงสันทรายจึงเข้าไปทำไร่ต่อได้สาม ปี ดังนั้น การครอบครองที่ดินช่วงแรกกับช่วงหลังของสันทรายจึงไม่ติดต่อกัน แสงดาวจึงรับโอนเวลาการ ครอบครองที่ดินจากสันทรายได้เพียงสามปี เพราะการครอบครองช่วงแรกของสันทรายมีข้อบกพร่องตาม มาตรา 1385 เมื่อข้อเท็จจริงระบุว่า หลังจากซื้อที่ดินมา แสงดาวปลูกบ้านทำไร่อ้อยในที่ดินมาได้ห้าปี ซึ่งเมื่อรวมกับการ ครอบครองของสันทรายแล้ว ย่อมถือว่าแสงดาวครอบครองที่ดินได้เพียงแปดปีตามมาตรา 1385 แสงดาว จึงยังไม่ได้กรรมสิทธิ์โดยการครอบครองปรปักษ์ตามมาตรา 1382\n\nดังนั้น ข้ออ้างของแสงดาวที่ว่าสุดสวยหมดระยะเวลาการเรียกคืนการครอบครองที่ดินแปลงนั้น จากตนแล้ว จึงรับฟังไม่ได้ เพราะที่ดินของสุดสวยเป็นที่ดินที่มีกรรมสิทธิ์ไม่ใช่ที่ดินมือเปล่า สุดสวยใน ฐานะเจ้าของกรรมสิทธิ์ย่อมมีสิทธิติดตามเอาคืนที่ดินของตนจากผู้ไม่มีสิทธิได้ทุกเมื่อ","conclusion":"สรุป ข้ออ้างของแสงดาวรับฟังไม่ได้","otherSections":["1385"]},{"id":"archive-2553-s-1-27","year":"2553","semester":"ภาคฤดูร้อน","number":1,"page":27,"course":"LAW2001 (LA 201 / LW 204)","title":"ปี 2553 ภาคฤดูร้อน · ข้อ 1","sections":["1299","1382"],"kind":"old-exam-source","source":"แนวข้อสอบเก่าวิชาทรัพย์สิน.pdf","question":"ข้อ 1. นายเสือครอบครองปรปักษ์ที่ดินมีโฉนดของนายช้างเป็นเวลา 12 ปี แต่ยังไม่ได้จดทะเบียนเปลี่ยนชื่อ ในโฉนดเป็นชื่อของตน ต่อมานายช้างได้นำที่ดินแปลงนี้ไปขายให้กับนายกวางโดยทำสัญญาเป็นหนังสือ และจดทะเบียนกับพนักงานเจ้าหน้าที่และนายกวางก็ไม่รู้เรื่องการครอบครองปรปักษ์ของนายเสือมา ก่อน หลังจากนั้น 1 ปี นายกวางถึงแก่ความตาย น.ส.หนูบุตรของนายกวางได้จดทะเบียนรับโอนกรรมสิทธิ์ ที่ดินมรดกแปลงนี้ในฐานะทายาทโดยธรรม และได้ฟ้องขับไล่นายเสือให้ออกจากที่ดินแปลงนั้น นายเสือต่อสู้ว่าตนได้กรรมสิทธิ์ที่ดินแปลงนี้โดยการครอบครองปรปักษ์แล้ว น.ส.หนูได้ที่ดินมาโดยไม่ได้ เสียค่าตอบแทนย่อมไม่มีสิทธิดีกว่าตน\n\nดังนี้ ให้ท่านวินิจฉัยว่าข้อต่อสู้ของนายเสือรับฟังได้หรือไม่","rule":"มาตรา 1299 วรรคสอง ถ้ามีผู้ได้มาซึ่งอสังหาริมทรัพย์ หรือทรัพยสิทธิอันเกี่ยวกับอสังหาริมทรัพย์โดยทาง อื่นนอกจากนิติกรรม สิทธิของผู้ได้มานั้น ถ้ายังมิได้จดทะเบียนไซร้ ท่านว่าจะมีการเปลี่ยนแปลงทาง ทะเบียนไม่ได้ และสิทธิอันยังมิได้จดทะเบียนนั้น มิให้ยกเป็นข้อต่อสู้บุคคลภายนอกผู้ได้สิทธิมาโดยเสีย ค่าตอบแทนและโดยสุจริตและได้จดทะเบียนสิทธิโดยสุจริตแล้ว","application":"กรณีตามอุทาหรณ์ การที่นายเสือครอบครองปรปักษ์ที่ดินมีโฉนดของนายช้างเป็นเวลา 12 ปี ถือว่า นายเสือได้กรรมสิทธิ์ในที่ดินของนายช้างโดยการครอบครองปรปักษ์ (ป.พ.พ. มาตรา 1382) อันเป็นการ ได้มาซึ่งอสังหาริมทรัพย์โดยทางอื่นนอกจากนิติกรรมตามมาตรา 1299 วรรคสอง ดังนั้น เมื่อนายเสือยังมิได้ จดทะเบียนเปลี่ยนชื่อในโฉนดเป็นชื่อของตน และระหว่างนั้นนายช้างได้ขายที่ดินแปลงนี้ให้กับนายก วาง โดยทำสัญญาเป็นหนังสือและจดทะเบียนกับพนักงานเจ้าหน้าที่ และนายกวางก็ไม่รู้เรื่องการ ครอบครองปรปักษ์ของนายเสือมาก่อน จึงทำให้สิทธิการได้มาของนายเสือไม่สามารถยกขึ้นต่อสู้นายกวาง ผู้เป็นบุคคลภายนอกซึ่งได้สิทธิในที่ดินนี้มาโดยสุจริต (ไม่รู้เรื่องการครอบครองปรปักษ์ของนายเสือ) และ โดยเสียค่าตอบแทน (ซื้อ) และจดทะเบียนสิทธิของตนโดยสุจริตแล้วได้ และเมื่อข้อเท็จจริงปรากฏว่า น.ส.หนูได้จดทะเบียนรับโอนกรรมสิทธิ์ที่ดินมรดกแปลงนี้มาในฐานะทายาท โดยธรรมของนายกวาง จึงถือเป็นผู้สืบสิทธิของนายกวาง ผู้ซึ่งมีสิทธิในที่ดินพิพาทดีกว่านายเสือมาตั้งแต่ แรกแล้ว น.ส.หนูจึงมีสิทธิในที่ดินพิพาทดีกว่านายเสือด้วย\n\nดังนั้น ข้อต่อสู้ของนายเสือที่ว่า ตนได้กรรมสิทธิ์ในที่ดินแปลงนี้โดยการครอบครองปรปักษ์ แล้ว น.ส.หนูได้ที่ดินมาโดยไม่ได้เสียค่าตอบแทนย่อมไม่มีสิทธิดีกว่าตนจึงรับฟังไม่ได้","conclusion":"สรุป ข้อต่อสู้ของนายเสือรับฟังไม่ได้","otherSections":[]},{"id":"archive-2553-s-3-29","year":"2553","semester":"ภาคฤดูร้อน","number":3,"page":29,"course":"LAW2001 (LA 201 / LW 204)","title":"ปี 2553 ภาคฤดูร้อน · ข้อ 3","sections":["1377","1382"],"kind":"old-exam-source","source":"แนวข้อสอบเก่าวิชาทรัพย์สิน.pdf","question":"ข้อ 3. นายดำครอบครองปรปักษ์ทำนาในที่ดินมีโฉนดของนายแดงมาได้ 4 ปี นายดำถึงแก่กรรมนายเขียว บุตรของนายดำปฏิเสธไม่สนใจที่จะครอบครองต่อจึงปล่อยที่ดินให้รกร้างอยู่ 10 เดือน ต่อมานายเขียวตก งานจึงเปลี่ยนใจเข้าไปทำนาบนที่ดินของนายแดงอีกได้นาน 6 ปี นายแดงจึงฟ้องขับไล่นายเขียวออกจาก ที่ดินแปลงนั้น\n\nให้ท่านวินิจฉัยว่า นายเขียวจะได้สิทธิอย่างใดจากการที่ตนครอบครองที่ดินต่อจากนายดำบิดาของ ตนหรือไม่ จงอธิบาย","rule":"มาตรา 1377 วรรคแรก ถ้าผู้ครอบครองสละเจตนาครอบครอง หรือไม่ยุดถือทรัพย์สินต่อไป ไซร้ การครอบครองย่อมสุดสิ้นลง\n\nมาตรา 1382 บุคคลใดครอบครองทรัพย์สินของผู้อื่นไว้โดยความสงบและโดยเปิดเผยด้วยเจตนา เป็นเจ้าของ ถ้าเป็นอสังหาริมทรัพย์ได้ครอบครองติดต่อกันเป็นเวลาสิบปี ถ้าเป็นสังหาริมทรัพย์ได้ ครอบครองติดต่อกันเป็นเวลาห้าปีไซร้ ท่านว่าบุคคลนั้นได้กรรมสิทธิ์\n\nมาตรา 1385 ถ้าโอนการครอบครองแก่กัน ผู้รับโอนจะนับเวลาซึ่งผู้โอนครอบครองอยู่ก่อนนั้น รวมเข้ากับเวลาครอบครองของตนก็ได้ ถ้าผู้รับโอนนับรวมเช่นนั้น และถ้ามีข้อบกพร่องในระหว่าง ครอบครองของผู้โอนไซร้ ท่านว่าข้อบกพร่องนั้นอาจยกขึ้นเป็นข้อต่อสู้ผู้รับโอนได้","application":"โดยหลักแล้ว การได้กรรมสิทธิ์ในอสังหาริมทรัพย์โดยการครอบครองปรปักษ์ตาม มาตรา 1382 จะต้องประกอบด้วยหลักเกณฑ์ดังนี้ คือ\n\n1 เป็นทรัพย์สินของผู้อื่นโดยผู้อื่นมีกรรมสิทธิ์\n\n2 ได้ครอบครองโดยความสงบ\n\n3 ครอบครองโดยเปิดเผย\n\n4 ครอบครองโดยเจตนาเป็นเจ้าของ\n\n5 ครอบครองติดต่อกันมาเป็นเวลา 10 ปี\n\nกรณีตามอุทาหรณ์ การที่นายเขียวบุตรของนายดำปฏิเสธไม่สนใจครอบครองปรปักษ์ที่ดินของนาย แดงต่อจากนายดำบิดาซึ่งถึงแก่กรรมนั้น ย่อมถือว่านายเขียวสละเจตนาครอบครองที่ดินพิพาทแล้ว อายุ ความการครอบครองปรปักษ์จึงสิ้นสุดลงตามมาตรา 1377 วรรคแรก\n\nดังนั้น แม้ต่อมาอีก 10 เดือน หลังจากทิ้งร้างไป นายเขียวจะเข้ามาครอบครองที่ดินของนายแดงอีก 6 ปีก็ ตาม นายเขียวก็ไม่สามารถนำเอาระยะเวลาการครอบครองของนายดำผู้เป็นบิดามานับรวมกับการ ครอบครองของตนเองตามมาตรา 1385 ได้\n\nดังนั้น เมื่อนายเขียวครอบครองปรปักษ์ที่นาแปลงนี้ได้เพียง 6 ปี ซึ่งยังไม่ถึง 10 ปี จึงไม่ครบ หลักเกณฑ์ตามมาตรา 1382 ที่จะทำให้ได้กรรมสิทธิ์โดยการครอบครองปรปักษ์นายเขียวจึงยังไม่ได้สิทธิ ใดๆบนที่ดินแปลงนี้","conclusion":"สรุป นายเขียวไม่ได้สิทธิใดๆจากการที่ตนครอบครองที่ดินต่อจากนายดำผู้เป็นบิดา","otherSections":["1385"]},{"id":"archive-2553-s-4-30","year":"2553","semester":"ภาคฤดูร้อน","number":4,"page":30,"course":"LAW2001 (LA 201 / LW 204)","title":"ปี 2553 ภาคฤดูร้อน · ข้อ 4","sections":["1382","1401","1299"],"kind":"old-exam-source","source":"แนวข้อสอบเก่าวิชาทรัพย์สิน.pdf","question":"ข้อ 4. อาทิตย์เป็นเจ้าของที่นาแปลงหนึ่ง ทุกๆปีในฤดูทำนาอาทิตย์ต้องใช้ทางผ่านบนที่ดินของจันทร์เพื่อเข้า ไปทำนาในที่นาของอาทิตย์ โดยจันทร์ไม่ทราบมาก่อนว่าอาทิตย์มาเดินผ่านที่ดินของตน อาทิตย์ใช้ ทางผ่านบนที่ดินของจันทร์มาได้กว่า 10 ปี โดยมิได้ไปจดทะเบียน ต่อมาจันทร์ทราบจึงทำรั้วกั้นที่ดินเพื่อ ไม่ให้อาทิตย์เดินผ่าน\n\nดังนี้ อาทิตย์จะมีสิทธิอ้างหลักกฎหมายเรื่องใดมาต่อสู้จันทร์เพื่อมิให้จันทร์ทำรั้วกั้นมิให้อาทิตย์ เดินผ่านหรือไม่ จงอธิบาย","rule":"มาตรา 1382 บุคคลใดครอบครองทรัพย์สินของผู้อื่นไว้โดยความสงบและโดยเปิดเผยด้วยเจตนา เป็นเจ้าของ ถ้าเป็นอสังหาริมทรัพย์ได้ครอบครองติดต่อกันเป็นเวลาสิบปี ถ้าเป็นสังหาริมทรัพย์ได้ ครอบครองติดต่อกันเป็นเวลาห้าปีไซร้ ท่านว่าบุคคลนั้นได้กรรมสิทธิ์\n\nมาตรา 1390 ท่านมิให้เจ้าของภารยทรัพย์ประกอบกรรมใด ๆ อันจะเป็นเหตุให้ประโยชน์แห่งภาระ จำยอมลดไป หรือเสื่อมความสะดวก\n\nมาตรา 1401 ภาระจำยอมอาจได้มาโดยอายุความ ท่านให้นำบทบัญญัติว่าด้วยอายุความได้สิทธิอัน กล่าวไว้ในลักษณะ 3 แห่งบรรพนี้มาใช้บังคับโดยอนุโลม","application":"การได้ภาระจำยอมโดยอายุความครอบครองปรปักษ์ตามมาตรา 1401 นั้น บัญญัติให้นำอายุความได้ สิทธิตามมาตรา 1382 มาบังคับใช้โดยอนุโลม กล่าวคือ ต้องเป็นกรณีที่เจ้าของสามยทรัพย์ได้ใช้ประโยชน์ ในภารยทรัพย์ โดยความสงบ เปิดเผย และมีเจตนาจะได้สิทธิภาระจำยอมในภารยทรัพย์ โดยต้องใช้ ประโยชน์ติดต่อกันเป็นเวลา 10 ปี กรณีตามอุทาหรณ์ การที่อาทิตย์ใช้ทางผ่านบนที่ดินของจันทร์เพื่อเข้าไปทำนาบนที่ดินของอาทิตย์เอง โดย จันทร์ไม่ทราบมาก่อนนั้น ถือเป็นกรณีที่อาทิตย์เจ้าของสามยทรัพย์ได้ใช้ประโยชน์ในภารยทรัพย์โดยความ สงบ เปิดเผย และมีเจตนาจะได้สิทธิภาระจำยอมในภารยทรัพย์แล้ว เมื่ออาทิตย์ใช้ทางผ่านบนที่ดินของ\n\nจันทร์มาได้กว่า 10 ปี ย่อมทำให้อาทิตย์ได้ภาระจำยอมโดยอายุความปรปักษ์ตามมาตรา 1401 ประกอบ มาตรา 1382 และเมื่ออาทิตย์ได้ภาระจำยอมบนที่ดินของจันทร์โดยอายุความปรปักษ์ ซึ่งถือเป็นการได้ทรัพยสิทธิใน อสังหาริมทรัพย์ตามมาตรา 1299 วรรคสองแล้ว (แม้ยังไม่ได้จดทะเบียนสิทธิก็เป็นทรัพยสิทธิ) การที่จันทร์ ทำรั้วกั้นที่ดินเพื่อไม่ให้อาทิตย์เดินผ่าน จึงเป็นการทำให้ประโยชน์แห่งภาระจำยอมลดลง หรือเสื่อมความ สะดวกตามมาตรา 1390\n\nดังนั้น อาทิตย์จึงมีสิทธิอ้างหลักกฎหมายตามมาตรา 1390 ขึ้นต่อสู้กับจันทร์เพื่อมิให้จันทร์ทำรั้ว กั้นระหว่างภารยทรัพย์กับสามยทรัพย์ได้","conclusion":"สรุป อาทิตย์มีสิทธิอ้างหลักกฎหมายตามมาตรา 1390 ขึ้นต่อสู้กับจันทร์เพื่อมิให้จันทร์ทำรั้วกั้นมิให้ อาทิตย์เดินผ่านได้","otherSections":["1390"]},{"id":"archive-2553-2-1-32","year":"2553","semester":"ภาค 2","number":1,"page":32,"course":"LAW2001 (LA 201 / LW 204)","title":"ปี 2553 ภาค 2 · ข้อ 1","sections":["1299"],"kind":"old-exam-source","source":"แนวข้อสอบเก่าวิชาทรัพย์สิน.pdf","question":"ข้อ 1. นายสอนกับนายอิ่มทำสัญญากันเอง โดยนายสอนอนุญาตให้นายอิ่มทำถนนผ่านที่ดินมีโฉนดของตน เพื่อออกสู่ถนนพหลโยธิน ทั้งที่ที่ดินของนายอิ่มมีทางออกสู่ทางสาธารณะอยู่แล้ว หลังจากนายอิ่มทำถนน ผ่านที่ดินของนายสอนได้ 4 ปี นายสอนถึงแก่ความตาย นายสินบุตรของนายสอนได้จดทะเบียนรับมรดก ที่ดินดังกล่าว\n\nดังนี้ ให้วินิจฉัยว่า\n\n(ก) นายสินจะล้อมรั้วไม่ยอมให้นายอิ่มใช้ถนนผ่านที่ดินของตนอีกต่อไปได้หรือไม่ เพราะเหตุใด\n\n(ข) ถ้าหลังจากนายสินจดทะเบียนรับมรดกได้ 1 ปี นายสินทำสัญญาและจดทะเบียนโอน กรรมสิทธิ์ที่ดินแปลงนั้นให้นางฟ้าภริยานอกสมรสของตนโดยเสน่หา นางฟ้าจะล้อมรั้วไม่ยอมให้นายอิ่ม ใช้ถนนผ่านที่ดินของตนอีกต่อไปได้หรือไม่ เพราะเหตุใด","rule":"มาตรา 1299 วรรคแรก ภายในบังคับแห่งบทบัญญัติในประมวลกฎหมายนี้หรือกฎหมายอื่น ท่าน ว่า การได้มาโดยนิติกรรมซึ่งอสังหาริมทรัพย์หรือทรัพยสิทธิอันเกี่ยวกับอสังหาริมทรัพย์นั้นไม่ บริบูรณ์ เว้นแต่นิติกรรมจะได้ทำเป็นหนังสือและได้จดทะเบียนการได้มากับพนักงานเจ้าหน้าที่","application":"ตามกฎหมาย การได้มาซึ่งอสังหาริมทรัพย์หรือทรัพยสิทธิอันเกี่ยวกับอสังหาริมทรัพย์โดยทางนิติ กรรมนั้น จะบริบูรณ์เป็นทรัพยสิทธิได้ จะต้องทำเป็นหนังสือและจดทะเบียนการได้มากับพนักงาน เจ้าหน้าที่ ซึ่งถ้าฝ่าฝืนจะมีผลเป็นเพียงบุคคลสิทธิ ใช้กล่าวอ้างได้เฉพาะคู่สัญญาเท่านั้น ไม่สามารถยกขึ้น กล่าวอ้างต่อบุคคลภายนอกได้ (มาตรา 1299 วรรคแรก) กรณีตามอุทาหรณ์ การที่นายสอนทำสัญญาอนุญาตให้นายอิ่มทำถนนผ่านที่ดินของตน ทั้งที่ที่ดินของนาย อิ่มมีทางออกสู่ทางสาธารณะอยู่แล้วนั้น ถือเป็นกรณีที่นายอิ่มได้ทางภาระจำยอมผ่านที่ดินของนาย สอน อันเป็นการได้มาซึ่งทรัพยสิทธิอันเกี่ยวกับอสังหาริมทรัพย์โดยทางนิติกรรม เมื่อปรากฏข้อเท็จจริงว่า นิติกรรมการได้ภาระจำยอมดังกล่าวไม่ได้ทำเป็นหนังสือและจดทะเบียนการได้มา กับพนักงานเจ้าหน้าที่ นิติกรรมนั้นจึงไม่บริบูรณ์ในฐานะทรัพยสิทธิ ไม่สามารถยกขึ้นกล่าวอ้างต่อ บุคคลภายนอกได้ แต่ยังคงมีผลบังคับระหว่างนายสอนกับนายอิ่มซึ่งเป็นคู่สัญญาในฐานะบุคคลสิทธิตาม มาตรา 1299 วรรคแรก\n\nดังนั้น (ก) นายสินผู้จดทะเบียนรับมรดกที่ดินภารยทรัพย์ดังกล่าวจากนายสอนบิดาของตนจะล้อม รั้วไม่ยอมให้นายอิ่มใช้ถนนผ่านที่ดินของตนอีกต่อไปไม่ได้ เพราะแม้การได้ภาระจำยอมดังกล่าวจะไม่ได้\n\nทำเป็นหนังสือและจดทะเบียนการได้มากับพนักงานเจ้าหน้าที่ แต่ภาระจำยอมนั้นยังคงมีผลผูกพันนายสอน ในฐานะบุคคลสิทธิ ดังนั้นเมื่อนายสอนตาย นายสินผู้รับมรดกจึงต้องรัยไปทั้งสิทธิและหน้าที่ของนายสอน เจ้ามรดกดังกล่าวด้วย\n\n(ข) การที่ต่อมานายสินจดทะเบียนโอนกรรมสิทธิ์ที่ดินแปลงนั้นให้แก่นางฟ้าภริยานอกสมรสของ ตนโดยเสน่หา นางฟ้าจึงเป็นเจ้าของกรรมสิทธิ์ในที่ดินแปลงนั้น และถือเป็นบุคคลภายนอก ดังนั้น เมื่อ ภาระจำยอมดังกล่าวไม่บริบูรณ์ในฐานะทรัพยสิทธิ จึงไม่สามารถบังคับใช้กับนางฟ้าซึ่งเป็นบุคคลภายนอก ได้ นางฟ้าในฐานะเจ้าของกรรมสิทธิ์จึงมีสิทธิล้อมรั้วไม่ให้นายอิ่มใช้ถนนผ่านที่ดินของตนอีกต่อไปได้","conclusion":"สรุป (ก) นายสินจะล้อมรั้วไม่ยอมให้นายอิ่มใช้ถนนผ่านที่ดินของตนอีกต่อไปไม่ได้ (ข) นางฟ้าสามารถล้อมรั้วไม่ยอมให้นายอิ่มใช้ถนนผ่านที่ดินของตนอีกต่อไปได้","otherSections":[]},{"id":"archive-2553-2-3-34","year":"2553","semester":"ภาค 2","number":3,"page":34,"course":"LAW2001 (LA 201 / LW 204)","title":"ปี 2553 ภาค 2 · ข้อ 3","sections":["1382"],"kind":"old-exam-source","source":"แนวข้อสอบเก่าวิชาทรัพย์สิน.pdf","question":"ข้อ 3. แพงมีกรรมสิทธิ์บนที่ดินแปลงหนึ่ง แต่เนื่องจากแพงไปประกอบอาชีพอยู่ที่ต่างประเทศ จึงให้พัน ดูแลที่ดินแปลงนั้นแทน พุธได้เข้าไปครอบครองปรปักษ์ทำไร่บนที่ดินแปลงนั้นบางส่วน พันซึ่งเป็นผู้ดูแล ที่ดินแปลงนั้นก็ไม่ทราบ จึงยังไม่ได้ขับไล่ ส่วนแพงซึ่งอยู่ต่างประเทศก็ไม่ทราบเช่นเดียวกัน พุธ ครอบครองทำไร่บนที่ดินส่วนนั้นของแพงมาได้แปดปี แพงกลับมาเมืองไทยกลับมาได้สามปี แพงได้ไป รังวัดที่ดินจึงเพิ่งทราบว่าพุธทำการครอบครองทำไร่บุกรุกเข้ามาบนที่ดินของตน แพงจึงฟ้องขับไล่พุธให้ ออกจากที่ดินแปลงนั้นโดยแพงอ้างว่า ตนเพิ่งทราบถึงการครอบครองของพุธเพียงสามปี ตนจึงยังไม่เสีย สิทธิในที่ดินแปลงนั้นไป ถ้าท่านเป็นศาล ท่านจะพิพากษาอย่างไร เพราะเหตุใด","rule":"มาตรา 1382 บุคคลใดครอบครองทรัพย์สินของผู้อื่นไว้โดยความสงบและโดยเปิดเผยด้วยเจตนา เป็นเจ้าของ ถ้าเป็นอสังหาริมทรัพย์ได้ครอบครองติดต่อกันเป็นเวลาสิบปี ถ้าเป็นสังหาริมทรัพย์ได้ ครอบครองติดต่อกันเป็นเวลาห้าปีไซร้ ท่านว่าบุคคลนั้นได้กรรมสิทธิ์\n\nมาตรา 1386 บทบัญญัติว่าด้วยอายุความในประมวลกฎหมายนี้ ท่านให้ใช้บังคับในเรื่องอายุความ ได้สิทธิ อันกล่าวไว้ในลักษณะนี้โดยอนุโลม","application":"โดยหลักแล้วการได้กรรมสิทธิ์ในอสังหาริมทรัพย์โดยการครอบครองปรปักษ์ตาม มาตรา 1382 จะต้องประกอบด้วยหลักเกณฑ์ดังนี้ คือ\n\n1 เป็นทรัพย์สินของผู้อื่นโดยผู้อื่นมีกรรมสิทธิ์\n\n2 ได้ครอบครองโดยความสงบ\n\n3 ครอบครองโดยเปิดเผย\n\n4 ครอบครองโดยเจตนาเป็นเจ้าของ\n\n5 ครอบครองติดต่อกันมาเป็นเวลา 10 ปี\n\nกรณีตามอุทาหรณ์ การที่พุธได้เข้าไปครอบครองปรปักษ์ทำไร่บนที่ดินบางส่วน ซึ่งเป็นกรรมสิทธิ์ของแพง นั้น เมื่อพุธได้ครอบครองโดยความสงบ เปิดเผย และเจตนาเป็นเจ้าของติดต่อกันถึง 11 ปี ซึ่งเกิน 10 ปี แล้ว พุธย่อมได้กรรมสิทธิ์ในที่ดินส่วนนั้นโดยการครอบครองปรปักษ์ตามมาตรา 1382 ดังนั้น แพงจะฟ้องขับไล่พุธให้ออกจากที่ดินแปลงนั้น โดยอ้างว่าตนเพิ่งทราบถึงการครอบครองของพุธ เพียง 3 ปี ตนจึงยังไม่เสียสิทธิในที่ดินแปลงนั้นไปไม่ได้ เพราะการครอบครองปรปักษ์เป็นการได้ กรรมสิทธิ์โดยอายุความได้สิทธิตามมาตรา 1386 และเป็นอายุความโดยผลของกฎหมายซึ่งศาลสามารถ ยกขึ้นเองได้","conclusion":"สรุป ถ้าข้าพเจ้าเป็นศาลจะพิพากษาให้พุธได้กรรมสิทธิ์ในที่ดินส่วนนั้นโดยการครอบครอง ปรปักษ์ตามมาตรา 1382 ตามเหตุผลดังกล่าวข้างต้น","otherSections":["1386"]},{"id":"archive-2553-2-4-35","year":"2553","semester":"ภาค 2","number":4,"page":35,"course":"LAW2001 (LA 201 / LW 204)","title":"ปี 2553 ภาค 2 · ข้อ 4","sections":["1377","1382","1387","1401"],"kind":"old-exam-source","source":"แนวข้อสอบเก่าวิชาทรัพย์สิน.pdf","question":"ข้อ 4. ดวงเป็นเจ้าของกิจการร้านขายเครื่องมือทางการเกษตรทั้งขาย ให้เช่า และรับจ้างไถ หว่าน เกี่ยว ข้าว พืชไร่ ฯลฯ ร้านของดวงตั้งอยู่ที่นอกเขตเทศบาล ที่ดินที่ตั้งร้านของดวงมีทางออกสู่ทางสาธารณะอยู่ แล้ว แต่เมื่อมีเกษตรกรหรือมีใครเช่าเครื่องมือทางการเกษตร ดวงจะใช้ที่ดินของเด่นเป็นทางลัดขน เครื่องมือต่างๆผ่านที่ดินของเด่นเข้า – ออกสู่ถนนสาธารณะเสมอเป็นประจำ โดยดวงไม่ทราบว่าที่ดินแปลง นั้นใครเป็นเจ้าของ จึงไม่ได้ขออนุญาตใช้ทาง และบางครั้งลูกค้าของดวงยังใช้เส้นทางบนที่ดินของเด่นเข้า มาติดต่อซื้อขาย เช่า ว่าจ้างดวงด้วย เมื่อดวงใช้ที่ดินของเด่นเป็นทางเข้า - ออก มาได้สิบห้าปี เด่นทราบจึงมา ตกลงกับดวงว่า ถ้าดวงยังต้องการใช้ถนนบนที่ดินของตนต่อไป ดวงต้องเช่าที่ดินแปลงนี้ มิฉะนั้นก็ ต้องห้ามบุกรุกเข้ามาใช้ทางผ่านที่ดินแปลงนี้อีก ดวงจึงตกลงขอเช่าโดยจ่ายค่าผ่านทางให้กับเด่นปีละห้าพัน บาท\n\nในความเห็นของท่านให้ท่านอธิบายว่า ดวงได้สิทธิอะไรก่อนที่จะตกลงเช่าที่ดินเด่น และหลังจาก ตกลงเช่าที่ดินเด่นเพื่อผ่านทางบนที่ดินของเด่น วิธีใดและส่งผลอย่างไรบ้าง","rule":"มาตรา 1377 วรรคแรก ถ้าผู้ครอบครองสละเจตนาครอบครอง หรือไม่ยุดถือทรัพย์สินต่อไป ไซร้ การครอบครองย่อมสุดสิ้นลง\n\nมาตรา 1382 บุคคลใดครอบครองทรัพย์สินของผู้อื่นไว้โดยความสงบและโดยเปิดเผยด้วยเจตนา เป็นเจ้าของ ถ้าเป็นอสังหาริมทรัพย์ได้ครอบครองติดต่อกันเป็นเวลาสิบปี ถ้าเป็นสังหาริมทรัพย์ได้ ครอบครองติดต่อกันเป็นเวลาห้าปีไซร้ ท่านว่าบุคคลนั้นได้กรรมสิทธิ์\n\nมาตรา 1387 อสังหาริมทรัพย์อาจต้องตกอยู่ในภาระจำยอมอันเป็นเหตุให้เจ้าของต้องยอมรับกรรม บางอย่างซึ่งกระทบถึงทรัพย์สินของตน หรือต้องงดเว้นการใช้สิทธิบางอย่างอันมีอยู่ในกรรมสิทธิ์ทรัพย์สิน นั้นเพื่อประโยชน์แก่อสังหาริมทรัพย์อื่น\n\nมาตรา 1401 ภาระจำยอมอาจได้มาโดยอายุความ ท่านให้นำบทบัญญัติว่าด้วยอายุความได้สิทธิอัน กล่าวไว้ในลักษณะ 3 แห่งบรรพนี้มาใช้บังคับโดยอนุโลม","application":"การได้ภาระจำยอมตามมาตรา 1387 โดยอายุความครอบครองปรปักษ์นั้น ถือเป็นการได้ทรัพยสิทธิ เกี่ยวกับอสังหาริมทรัพย์โดยทางอื่นนอกจากนิติกรรม ซึ่งตามมาตรา 1401 นั้น บัญญัติให้นำอายุความได้ สิทธิตามมาตรา 1382 มาบังคับใช้โอยอนุโลม กล่าวคือ ต้องเป็นกรณีที่เจ้าของสามยทรัพย์ได้ใช้ประโยชน์ ในภารยทรัพย์ โดยความสงบ เปิดเผย และมีเจตนาจะได้สิทธิภาระจำยอมในภารยทรัพย์ โดยต้องใช้ ประโยชน์ติดต่อกันเป็นเวลา 10 ปี กรณีตามอุทาหรณ์ การที่ดวงเป็นเจ้าของกิจการร้านขายเครื่องมือทางการเกษตร และรับจ้าง ไถ หว่าน เกี่ยวข้าว พืชไร่ ฯลฯ และเมื่อมีเกษตรกรหรือคนมาเช่าเครื่องมือทางการเกษตร ดวงก็จะใช้ที่ดิน ของเด่นเป็นทางลัดขนเครื่องมือต่างๆผ่านที่ดินของเด่นเข้าออกสู่ถนนสาธารณะเสมอเป็นประจำนั้น ถือเป็น กรณีที่ดวงเจ้าของสามยทรัพย์ได้ใช้ประโยชน์ในภารยทรัพย์ คือที่ดินของเด่น โดยสงบ เปิดเผย และเจตนา จะได้มาซึ่งภาระจำยอมแล้ว เมื่อดวงใช้ที่ดินของเด่นเป็นทางเข้าออกมาได้ 15 ปี ที่ตั้งร้านของดวงจึงได้ ภาระจำยอมโดยการครอบครองปรปักษ์แล้วตามมาตรา 1387 และมาตรา 1382 ประกอบมาตรา 1401 แต่อย่างไรก็ตาม การที่ดวงทำสัญญาเช่าที่ดินกับเด่นเพื่อใช้เป็นทางผ่านเข้าออกนั้น ถือเป็นกรณีที่ดวงผู้ ครอบครองได้สละเจตนาครอบครองในภารยทรัพย์ดังกล่าวแล้ว กล่าวคือ เป็นการที่ดวงยอมรับว่าดวง ไม่ได้มีสิทธิในภาระจำยอมบนที่ดินของเด่นแต่อย่างใด ดังนั้น ภาระจำยอมที่ได้มาโดยการครอบครอง ปรปักษ์ดังกล่าวจึงสิ้นสุดลงตามมาตรา 1377 วรรคแรก","conclusion":"สรุป ดวงได้สิทธิ คือภาระจำยอมในที่ดินของเด่นโดยการครอบครองปรปักษ์ก่อนที่จะตกลงเช่า ที่ดินเด่น และหลังจากดวงตกลงเช่าที่ดินเด่นแล้ว ส่งผลให้ภาระจำยอมดังกล่าวสิ้นสุดลง","otherSections":[]},{"id":"archive-2553-1-1-37","year":"2553","semester":"ภาค 1","number":1,"page":37,"course":"LAW2001 (LA 201 / LW 204)","title":"ปี 2553 ภาค 1 · ข้อ 1","sections":["144","1299"],"kind":"old-exam-source","source":"แนวข้อสอบเก่าวิชาทรัพย์สิน.pdf","question":"ข้อ 1. ป่านทำสัญญาและจดทะเบียนยกบ้านและที่ดินมีโฉนดแปลงหนึ่งให้ปอโดยเสน่หา โดยปออนุญาต ด้วยวาจาให้ป่านอาศัยอยู่ในบ้านหลังนั้นได้ตลอดไป ลังจากนั้น 3 ปี ปอทำสัญญาและจดทะเบียนขายที่ดิน ดังกล่าวให้แก้ว หลังจากที่แก้วรับโอนที่ดินดังกล่าวแล้ว แก้วแจ้งให้ป่านออกไปจากบ้านหลังนั้น แต่ป่านไม่ยอมย้ายออกไปโดยอ้างว่าบ้านหลังดังกล่าวยังเป็นกรรมสิทธิ์ขอปอเพราะสัญญาซื้อขายที่ดิน ไม่ได้ระบุเรื่องบ้านไว้ ดังนั้น ป่านจึงมีสิทธิอยู่อาศัยในบ้านหลังนี้ต่อไปตามที่ป่านได้รับอนุญาตจากปอ\n\nดังนี้ ให้วินิจฉัยว่า แก้วจะฟ้องขับไล่ป่านออกไปจากบ้านหลังนี้ได้หรือไม่ และข้ออ้างของป่านรับ ฟังได้หรือไม่ เพราะเหตุใด จงอธิบาย","rule":"มาตรา 144 ส่วนควบของทรัพย์ หมายความว่า ส่วนซึ่งโดยสภาพแห่งทรัพย์หรือโดยจารีตประเพณี แห่งท้องถิ่นเป็นสาระสำคัญในความเป็นอยู่ของทรัพย์นั้น และไม่อาจแยกจากกันได้นอกจากจะทำลาย ทำ ให้บุบสลาย หรือทำให้ทรัพย์นั้นเปลี่ยนแปลงรูปทรงหรือสภาพไป เจ้าของทรัพย์ย่อมมีกรรมสิทธิ์ในส่วนควบของทรัพย์นั้น\n\nมาตรา 1299 วรรคแรก ภายในบังคับแห่งบทบัญญัติในประมวลกฎหมายนี้หรือกฎหมายอื่น ท่าน ว่า การได้มาโดยนิติกรรมซึ่งอสังหาริมทรัพย์หรือทรัพยสิทธิอันเกี่ยวกับอสังหาริมทรัพย์นั้นไม่ บริบูรณ์ เว้นแต่นิติกรรมจะได้ทำเป็นหนังสือและได้จดทะเบียนการได้มากับพนักงานเจ้าหน้าที่","application":"ตามกฎหมาย การได้มาซึ่งอสังหาริมทรัพย์หรือทรัพยสิทธิอันเกี่ยวกับอสังหาริมทรัพย์โดยทางนิติ กรรมนั้น จะบริบูรณ์เป็นทรัพย์สิทธิได้ จะต้องทำเป็นหนังสือและจดทะเบียนการได้มากับพนักงาน เจ้าหน้าที่ ซึ่งถ้าฝ่าฝืนจะมีผลเป็นเพียงบุคคลสิทธิ ใช้กล่าวอ้างได้เฉพาะคู่สัญญาเท่านั้น ไม่สามารถยกขึ้น กล่าวอ้างต่อบุคคลภายนอกได้ มาตรา 1299 วรรคแรก กรณีตามอุทาหรณ์ การที่ป่านทำสัญญายกบ้านและที่ดินมีโฉนดให้ปอโดยเสน่หา ปอจึงเป็นผู้ได้มาซึ่ง อสังหาริมทรัพย์โดยทางนิติกรรม เมื่อได้มีการทำเป็นหนังสือและจดทะเบียนกับพนักงานเจ้าหน้าที่ การ ได้มาดังกล่าวจึงมีผลบริบูรณ์เป็นทรัพย์สิทธิตามมาตรา 1299 วรรคแรก และจากข้อเท็จจริงดังกล่าว เมื่อปอ ได้อนุญาตให้ป่านอาศัยอยู่ในบ้านหลังนั้นได้ตลอดไป ป่านจึงเป็นผู้ได้มาซึ่งทรัพยสิทธิอันเกี่ยวกับ อสังหาริมทรัพย์โดยทางนิติกรรม แต่เมื่อการได้มาซึ่งสิทธิอาศัยของป่านเป็นการอนุญาตด้วยวาจาไม่ได้ทำ เป็นหนังสือและจดทะเบียนกับพนักงานเจ้าหน้าที่ สิทธิอาศัยดังกล่าวจึงไม่บริบูรณ์เป็นทรัพยสิทธิ ทำให้\n\nป่านไม่สามารถยกขึ้นกล่าวอ้างต่อบุคคลภายนอกได้ แต่นิติกรรมนี้คงมีผลเป็นบุคคลสิทธิ ซึ่งใช้กล่าวอ้าง ได้เฉพาะคู่สัญญาคือปอเท่านั้นตามมาตรา 1299 วรรคแรก และเมื่อข้อเท็จจริงปรากฏว่า ต่อมาปอได้ทำสัญญาและจดทะเบียนขายที่ดินดังกล่าวให้แก้ว แก้วจึงเป็นผู้มี กรรมสิทธิ์ในที่ดินและบ้านซึ่งปลูกอยู่บนที่ดินนั้นด้วย ในฐานะที่บ้านเป็นส่วนควบของที่ดิน เพราะบ้านถือ ว่าเป็นสาระสำคัญในความเป็นอยู่ของที่ดินโดยจารีตประเพณีแห่งท้องถิ่นและไม่อาจแยกออกจากกันได้ นอกจากจะทำลาย ทำให้บุบสลายหรือทำให้ทรัพย์นั้นเปลี่ยนแปลงรูปทรงหรือสภาพไปตามมาตรา 144 ดังนั้น แก้วในฐานะที่เป็นเจ้าของที่ดินและบ้านจึงมีสิทธิฟ้องขับไล่ให้ป่านออกไปจากบ้านหลังนี้ได้ และ ข้ออ้างของป่านที่ว่าบ้านหลังดังกล่าวยังเป็นกรรมสิทธิ์ของปอ เพราะสัญญาซื้อขายที่ดินไม่ได้ระบุเรื่องบ้าน ไว้และป่านยังมีสิทธิอาศัยในบ้านหลังนี้ต่อไปนั้นจึงรับฟังไม่ได้ เพราะเมื่อการได้สิทธิอาศัยในบ้านของปอ ไม่บริบูรณ์เป็นทรัพย์สิทธิ ป่านจึงไม่สามารถยกขึ้นกล่าวอ้างต่อแก้วซึ่งเป็นบุคคลภายนอกได้","conclusion":"สรุป แก้วฟ้องขับไล่ให้ป่านออกไปจากบ้านดังกล่าวได้ และข้ออ้างของป่านรับฟังไม่ได้","otherSections":[]},{"id":"archive-2553-1-3-39","year":"2553","semester":"ภาค 1","number":3,"page":39,"course":"LAW2001 (LA 201 / LW 204)","title":"ปี 2553 ภาค 1 · ข้อ 3","sections":["1367","1377","1382"],"kind":"old-exam-source","source":"แนวข้อสอบเก่าวิชาทรัพย์สิน.pdf","question":"ข้อ 3. อ่างเข้าไปครอบครองที่ดิน น.ส.3 ของโอ่งแปลงหนึ่ง ครอบครองทำประโยชน์มาได้ห้าปี เมื่อมีการ เดินสำรวจเพื่ออกโฉนดที่ดิน โอ่งเพิ่งรู้ว่าอ่างเข้าไปทำประโยชน์ครอบครองที่ดินแปลงนั้นอยู่ โอ่งจึงได้มา แจ้งความต่อพนักงานเจ้าหน้าที่ และมาบอกอ่างให้อ่างออกไปจากที่ดินแปลงนั้น อ่างจึงเลิกทำนาและรื้อ บ้านของอ่างออกไปจากที่ดินแปลงนั้น เมื่อผ่านไปได้สองปี อ่างก็กลับเข้าไปปลูกบ้านทำนาอยู่บนที่ดินแปลงนั้นใหม่ ปรากฏว่าที่ดินแปลงนั้นโอ่งได้เปลี่ยนจากหนังสือ รับรองการทำประโยชน์มาเป็นโฉนดที่ดินเรียบร้อยแล้ว อ่างครอบครองต่อมาได้ห้าปี โอ่งจึงฟ้องศาลขับไล่ อ่างให้ออกไปจากที่ดินแปลงนั้น\n\nให้ท่านวินิจฉัยว่าระหว่างโอ่งและอ่างใครมีสิทธิในที่ดินแปลงนั้นดีกว่ากัน เพราะเหตุใด","rule":"มาตรา 1367 บุคคลใดยึดถือทรัพย์สินโดยเจตนาจะยึดถือเพื่อตน ท่านว่าบุคคลนั้นได้ซึ่งสิทธิ ครอบครอง\n\nมาตรา 1377 วรรคแรก ถ้าผู้ครอบครองสละเจตนาครอบครอง หรือไม่ยุดถือทรัพย์สินต่อไป ไซร้ การครอบครองย่อมสุดสิ้นลง\n\nมาตรา 1382 บุคคลใดครอบครองทรัพย์สินของผู้อื่นไว้โดยความสงบและโดยเปิดเผยด้วยเจตนา เป็นเจ้าของ ถ้าเป็นอสังหาริมทรัพย์ได้ครอบครองติดต่อกันเป็นเวลาสิบปี ถ้าเป็นสังหาริมทรัพย์ได้ ครอบครองติดต่อกันเป็นเวลาห้าปีไซร้ ท่านว่าบุคคลนั้นได้กรรมสิทธิ์","application":"โดยหลัก การได้กรรมสิทธิ์ในอสังหาริมทรัพย์โดยการครอบครองปรปักษ์ตามมาตรา 1382 จะต้อง เป็นการครอบครองทรัพย์สินของผู้อื่นด้วยความสงบ เปิดเผย และมีเจตนาเป็นเจ้าของ โดยต้องครอบครอง ติดต่อกันเป็นเวลา 10 ปี และในกรณีที่เป็นที่ดินนั้นจะต้องเป็นที่ดินที่มีกรรมสิทธิ์ด้วยจึงจะสามารถ ครอบครองปรปักษ์ได้\n\nตามอุทาหรณ์ การที่อ่างเข้าไปครอบครองทำประโยชน์ในที่ดิน น.ส.3 ของโอ่งได้ 5 ปีนั้น ถือเป็นการเข้า ยึดถือทรัพย์สินโดยเจตนายึดถือเพื่อตน อ่างจึงได้สิทธิครอบครองในที่ดินแปลงนั้นตามมาตรา 1367 โดยถือ เป็นการแย่งสิทธิครอบครองในที่ดินของโอ่ง แต่ไม่ใช่กรณีการครอบครองปรปักษ์ เพราะที่ดินดังกล่าวมี เพียงสิทธิครอบครองเท่านั้น และเมื่อโอ่งได้มาบอกให้อ่างออกไปจากที่ดินแปลงนั้น อ่างก็ได้เลิกทำนาและ รื้อบ้านของตนออกไปจากที่ดินแปลงนั้นแล้ว จึงเป็นกรณีที่อ่างสละเจตนาครอบครองในที่ดินแปลง ดังกล่าวตามมาตรา 1377 วรรคแรก การครอบครองจึงสิ้นสุดลง เมื่อผ่านไป 2 ปี อ่างก็กลับเข้าไปปลูกบ้านทำนาอยู่บนที่ดินแปลงนั้นใหม่ เมื่ออ่างเจตนายึดถือเพื่อตนจึงได้ สิทธิครอบครองในที่ดินแปลงดังกล่าวอีกครั้งตามมาตรา 1367 แต่เมื่อที่ดินแปลงนั้นเปลี่ยนเป็นที่ดินที่มี โฉนด คือ มีกรรมสิทธิ์แล้ว การที่อ่างจะได้กรรมสิทธิ์โดยการครอบครองปรปักษ์ได้นั้นจะต้องครอบครอง ที่ดินของโอ่งด้วยความสงบ เปิดเผย และมีเจตนาเป็นเจ้าของติดต่อกันเป็นเวลา 10 ปี ตามมาตรา 1382 แต่เมื่อข้อเท็จจริงปรากฏว่า อ่างครอบครองที่ดินที่มีโฉนดของโอ่งในครั้งหลังนี้ได้เพียง 5 ปี อ่างจึงยังไม่ได้ กรรมสิทธิ์ ดังนั้นโอ่งย่อมมีสิทธิในที่ดินแปลงนั้นดีกว่าอ่าง และเมื่อโอ่งฟ้องศาลขับไล่อ่างให้ออกจาก ที่ดินแปลงนั้น อ่างก็จะต้องออกจากที่ดินแปลงนั้น","conclusion":"สรุป โอ่งมีสิทธิในที่ดินแปลงนั้นดีกว่าอ่าง","otherSections":[]},{"id":"archive-2553-1-4-40","year":"2553","semester":"ภาค 1","number":4,"page":40,"course":"LAW2001 (LA 201 / LW 204)","title":"ปี 2553 ภาค 1 · ข้อ 4","sections":["1382","1401"],"kind":"old-exam-source","source":"แนวข้อสอบเก่าวิชาทรัพย์สิน.pdf","question":"ข้อ 4. นายหนึ่ง นายสอง และนายสาม มีที่ดินอยู่ข้างเคียงกัน นายหนึ่งได้สูบน้ำผ่านลำรางที่อยู่ในที่ดินของ นายดำเข้ามาใช้ทำนาในที่ดินของนายหนึ่ง นายสอง และนายสาม ก็ยังได้อาศัยวิดน้ำจากลำรางที่นายหนึ่งสูบ น้ำผ่านที่ดินของนายดำเข้ามาใช้ในที่ดินของนายหนึ่งไปใช้ทำนาในที่ดินของนายสองและนายสามด้วย เช่นเดียวกัน โดยทั้งนายสองและนายสามไม่เคยขออนุญาตนายดำเลย และนายดำก็ไม่เคยรู้มาก่อนว่านาย หนึ่งชักน้ำผ่านที่ดินของตน และนายสองและนายสามยังวิดน้ำที่ผ่านจากที่ดินของนายดำไปยังที่ดินของนาย หนึ่งเข้าไปใช้ในที่ดินของทั้งสองด้วย โดยทั้งนายหนึ่งนายสอง และนายสาม ได้สูบน้ำวิดน้ำเข้าไปใช้ใน ที่ดินของแต่ละคนมาได้เกินสิบปีแล้ว นายดำคิดว่าการที่นายสองและนายสามใช้น้ำที่ไหลผ่านลำรางบน ที่ดินของตนด้วยนั้นเป็นการก่อให้เกิดภาระเพิ่มขึ้นกับที่ดินของตน นายดำจะห้ามไม่ให้นายสองและนาย สามวิดน้ำจากลำรางที่ไหลผ่านที่ดินของนายดำเข้าไปในที่ดินของนายหนึ่งไปใช้ในที่ดินของทั้งนายสอง และนายสามได้หรือไม่ และข้ออ้างของนายดำรับฟังได้เพียงใด เพราะเหตุใด","rule":"มาตรา 1382 บุคคลใดครอบครองทรัพย์สินของผู้อื่นไว้โดยความสงบและโดยเปิดเผยด้วยเจตนา เป็นเจ้าของ ถ้าเป็นอสังหาริมทรัพย์ได้ครอบครองติดต่อกันเป็นเวลาสิบปี ถ้าเป็นสังหาริมทรัพย์ได้ ครอบครองติดต่อกันเป็นเวลาห้าปีไซร้ ท่านว่าบุคคลนั้นได้กรรมสิทธิ์\n\nมาตรา 1401 ภาระจำยอมอาจได้มาโดยอายุความ ท่านให้นำบทบัญญัติว่าด้วยอายุความได้สิทธิอัน กล่าวไว้ในลักษณะ 3 แห่งบรรพนี้มาใช้บังคับโดยอนุโลม","application":"การได้ภาระจำยอมโดยอายุความครอบครองปรปักษ์ตามมาตรา 1401 นั้น บัญญัติให้นำอายุความได้ สิทธิตามมาตรา 1382 มาบังคับใช้โอยอนุโลม กล่าวคือ ต้องเป็นกรณีที่เจ้าของสามยทรัพย์ได้ใช้ประโยชน์ ในภารยทรัพย์ โดยความสงบ เปิดเผย และมีเจตนาจะได้สิทธิภาระจำยอมในภารยทรัพย์ โดยต้องใช้ ประโยชน์ติดต่อกันเป็นเวลา 10 ปี ตามอุทาหรณ์ การที่นายหนึ่งได้สูบน้ำผ่านลำรางที่อยู่ในที่ดินของนายดำเข้ามาใช้ทำนาในที่ดินของตน โดย นายสองและนายสามก็ยังได้อาศัยวิดน้ำจำลำรางที่นายหนึ่งสูบน้ำผ่านที่ดินของนายดำเข้ามาใช้ในที่ดินของ นายหนึ่งไปใช้ทำนาในที่ดินของนายสองและนายสามด้วยนั้น เมื่อการกระทำดังกล่าวของนายหนึ่ง นาย สองและนายสามนั้น นายดำไม่เคยรู้มาก่อน และทั้งสามคนก็ไม่เคยขออนุญาตนายดำ อีกทั้งก็ไปปรากฏ ข้อเท็จจริงว่า การกระทำของทั้งสามคนนั้นเป็นการกระทำโดยถือวิสาสะ ดังนั้นกรณีดังกล่าวถือว่านาย หนึ่ง นายสอง และนายสาม ซึ่งเป็นเจ้าของสามยทรัพย์ได้ใช้ประโยชน์ในภารยทรัพย์ คือที่ดินของนาย ดำ โดยความสงบสุข เปิดเผย และเจตนาจะให้ได้มาซึ่งภาระจำยอมแล้ว และเมื่อข้อเท็จจริงปรากฏว่าทั้งสามคนได้สูบน้ำวิดน้ำเข้าไปใช้ในที่ดินของแต่ละคนมาได้เกินสิบปีแล้ว ทั้ง สามคนย่อมได้ภาระจำยอมในที่ดินของนายดำตามมาตรา 1401 ประกอบมาตรา 1382 กล่าวคือ นายดำต้อง ยอมให้ทั้งสามคนได้ใช้ประโยชน์ในที่ดินของนายดำในการสูบน้ำวิดน้ำเข้าไปใช้ในที่ดินของแต่ละคนได้ ต่อไป นายดำจะอ้างว่าการกระทำของนายสองและนายสามเป็นการก่อให้เกิดภาระเพิ่มขึ้นกับที่ดินของตน ไม่ได้ และจะห้ามไม่ให้นายสองและนายสามวิดน้ำจากลำรางที่ไหลผ่านที่ดินของนายดำ เข้าไปในที่ดิน ของนายหนึ่งไปใช้ในที่ดินของทั้งนายสองและนายสามไม่ได้","conclusion":"สรุป ที่ดินของนายดำอยู่ในภาระจำยอม นายดำจะห้ามไม่ให้นายสองและนายสามวิดน้ำจากลำราง ที่ผ่านที่ดินของนายดำดังกล่าวนั้นไม่ได้ และจะอ้างว่าเป็นการก่อให้เกิดภาระเพิ่มขึ้นกับที่ดินของตนก็ไม่ได้ เช่นเดียวกัน","otherSections":[]},{"id":"archive-2552-s-1-42","year":"2552","semester":"ภาคฤดูร้อน","number":1,"page":42,"course":"LAW2001 (LA 201 / LW 204)","title":"ปี 2552 ภาคฤดูร้อน · ข้อ 1","sections":["1304"],"kind":"old-exam-source","source":"แนวข้อสอบเก่าวิชาทรัพย์สิน.pdf","question":"ข้อ 1. สมัครเป็นเจ้าของที่ดินแปลงหนึ่งซึ่งอยู่ติดกับทางสาธารณะที่เป็นทางดินลูกรัง แต่สมัครได้ทำถนน ผ่านที่ดินรกร้างว่างเปล่าซึ่งทางราชการยังไม่เคยออกเอกสารสิทธิให้แก่ราษฎรผู้ใด สมัครใช้รถยนต์ผ่านเข้า ออกที่ดินดังกล่าวติดต่อกันเป็นเวลากว่า 12 ปีแล้ว เพราะเห็นว่าสะดวกกว่าการใช้ทางดินลูกรัง ต่อมาทางราชการได้ล้อมรั้วเพื่อก่อสร้างสถานที่ราชการตรงที่ดินแปลงนั้น ทำให้สมัครไม่สามารถใช้ถนน ดังกล่าวได้ สมัครจึงยื่นคำร้องต่อศาลเพื่อให้มีคำสั่งให้ทางราชการเปิดเส้นทางให้สมัครสามารถใช้ถนน ผ่านเข้าออกได้เช่นเดิม เพราะตกเป็นภาระจำยอมแล้ว\n\nดังนี้ให้ท่านวินิจฉัยว่า ข้ออ้างของสมัครรับฟังได้หรือไม่ เพราะเหตุใด","rule":"มาตรา 1304 สาธารณะสมบัติของแผ่นดินนั้นรวมทรัพย์สินทุกชนิดของแผ่นดิน ซึ่งใช้เพื่อ สาธารณะประโยชน์ หรือสงวนไว้เพื่อประโยชน์ร่วมกัน เช่น (1) ที่ดินรกร้างว่างเปล่า และที่ดินซึ่งมีผู้เวนคืนหรือทอดทิ้ง หรือกลับมาเป็นของแผ่นดินโดยประการอื่นตาม กฎหมายที่ดิน\n\nมาตรา 1306 ท่านห้ามมิให้ยกอายุความขึ้นเป็นข้อต่อสู้กับแผ่นดินในเรื่องทรัพย์สินอันเป็นสา ธารณสมบัติของแผ่นดิน","application":"โดยหลักแล้ว ทรัพย์สินที่เป็นสาธารณสมบัติของแผ่นดินนั้น กฎหมายห้ามมิให้บุคคลใดยกอายุ ความขึ้นเป็นข้อต่อสู้กับแผ่นดินเพื่อให้ได้มาซึ่งกรรมสิทธิ์หรือทรัพยสิทธิเหนือทรัพย์สินนั้นตาม มาตรา 1306 กรณีตามอุทาหรณ์ ถึงแม้สมัครจะทำถนนผ่านที่ดินรกร้างว่างเปล่าซึ่งทางราชการยังไม่เคยออกเอกสารสิทธิ ให้แก่ราษฎรผู้ใด และใช้รถยนต์ผ่านเข้าออกที่ดินดังกล่าวติดต่อกันเป็นเวลากว่า 12 ปีแล้วก็ตาม สมัครก็ ไม่ได้ภาระจำยอมซึ่งถือเป็นทรัพยสิทธิโดยอายุความปรปักษ์ เพราะที่ดินดังกล่าวเป็นสาธารณสมบัติของ แผ่นดินตามมาตรา 1304(1) ซึ่งห้ามมิให้บุคคลใดยกอายุความขึ้นเป็นข้อต่อสู้กับแผ่นดิน ตามมาตรา 1306\n\nดังนั้น เมื่อทางราชการได้ล้อมรั้วเพื่อก่อสร้างสถานที่ราชการตรงที่ดินแปลงนั้น สมัครจะยื่นคำ ร้องต่อศาลเพื่อให้มีคำสั่งให้ทางราชการเปิดเส้นทางให้สมัครสามารถใช้ถนนผ่านเข้าออกได้เช่นเดิมโดยอ้าง ว่าที่ดินดังกล่าวตกเป็นภาระจำยอมแล้วไม่ได้","conclusion":"สรุป ข้ออ้างของสมัครรับฟังไม่ได้","otherSections":["1306"]},{"id":"archive-2552-s-3-44","year":"2552","semester":"ภาคฤดูร้อน","number":3,"page":44,"course":"LAW2001 (LA 201 / LW 204)","title":"ปี 2552 ภาคฤดูร้อน · ข้อ 3","sections":["1367","1375"],"kind":"old-exam-source","source":"แนวข้อสอบเก่าวิชาทรัพย์สิน.pdf","question":"ข้อ 3. เมื่อวันที่ 5 มกราคม 2540 คำปันได้นำพนักงานที่ดินรังวัดเพื่ออกโฉนดโดยผนวกที่ดิน น.ส.3 ของคำ ม่วนซึ่งอยู่ติดกับที่ดินของคำปัน เพราะเห็นว่าคำม่วนไม่ได้ดูแลหรือทำประโยชน์ในที่ดินนั้นอย่างจริงจัง โดยคำปันเริ่มเข้าครอบครองทำประโยชน์ในที่ดินของคำม่วนนับแต่วันที่นำเจ้าพนักงานที่ดินไปรังวัด ทาง ราชการออกโฉนดให้คำปันวันที่ 1 ตุลาคม 2540 ต่อมาวันที่ 10 มกราคม 2541 คำม่วนได้ไปขอรังวัดเพื่อ ออกโฉนดบ้าง คำม่วนจึงรู้ว่าคำปันออกโฉนดทับที่ดินของตน คำม่วนจึงเจรจาขอที่ดินคืนจากคำปัน แต่คำ ปันปฏิเสธไม่ยอมคืนโดยอ้างว่าที่ดินพิพาทเป็นของตนแล้ว หลังจากนั้นวันที่ 1 มิถุนายน 2542 คำม่วนจึง ฟ้องศาลเพื่อเรียกคืนที่ดินพิพาทจากคำปัน\n\nดังนี้ให้วินิจฉัยว่า คำม่วนจะฟ้องเรียกคืนที่ดินพิพาทได้หรือไม่ เพราะเหตุใด","rule":"มาตรา 1367 บุคคลใดยึดถือทรัพย์สินโดยเจตนาจะยึดถือเพื่อตน ท่านว่าบุคคลนั้นได้ซึ่งสิทธิ ครอบครอง\n\nมาตรา 1375 ถ้าผู้ครอบครองถูกแย่งการครอบครองโดยมิชอบด้วยกฎหมายไซร้ ท่านว่าผู้ ครอบครองมีสิทธิจะได้คืนซึ่งการครอบครอง เว้นแต่อีกฝ่ายหนึ่งมีสิทธิเหนือทรัพย์สินดีกว่า ซึ่งจะเป็นเหตุ ให้เรียกคืนจากผู้ครอบครองได้ การฟ้องคดีเพื่อเอาคืนซึ่งการครอบครองนั้น ท่านว่าต้องฟ้องภายในปีหนึ่งนับแต่เวลาถูกแย่งการครอบครอง","application":"โดยหลัก ถ้าผู้ถูกครอบครองถูกแย่งการครอบครองโดยมิชอบด้วยกฎหมาย กฎหมายให้สิทธิผู้ ครอบครองฟ้องเรียกคืนซึ่งการครอบครองได้ภายใน 1 ปี นับแต่เวลาถูกแย่งการครอบครอง โดยไม่คำนึงว่า ผู้ครอบครองจะทราบว่าถูกแย่งการครอบครองหรือไม่ และไม่คำนึงว่าผู้ครอบครองได้โต้แย้งการ ครอบครองหรือไม่ตามมาตรา 1375 กรณีตามอุทาหรณ์ การที่คำปันนำเจ้าพนักงานที่ดินรังวัดที่ดินเพื่อออกโฉนดโดยผนวกที่ดิน น.ส.3 ของคำ ม่วนซึ่งมีเพียงสิทธิครอบครองไปด้วย ซึ่งคำปันได้เริ่มเข้าครอบครองทำประโยชน์ในที่ดินของคำม่วน นับ แต่วันที่นำเจ้าพนักงานที่ดินไปรังวัดคือวันที่ 5 มกราคม 2540 นั้น กรณีเช่นนี้ถือว่าคำปันได้เข้ายึดถือ ทรัพย์สินโดยเจตนาจะยึดถือเพื่อตนแล้ว คำปันจึงได้สิทธิครอบครองในที่ดิน น.ส.3 ของคำม่วนตาม มาตรา 1367 และกรณีนี้ยังถือว่าคำปันได้แย่งการครอบครองที่ดิน น.ส.3 ของคำม่วนด้วยตาม มาตรา 1375 วรรคแรก โดยทางราชการได้ออกโฉนดให้คำปันในวันที่ 1 ตุลาคม 2540\n\nต่อมาวันที่ 10 มกราคม 2541 คำม่วนได้ไปขอรังวัดที่ดินเพื่อออกโฉนด จึงรู้ว่าคำปันแย่งสิทธิ ครอบครองที่ดินของตน คำม่วนจึงเจรจาขอที่ดินคืนจากคำปัน ซึ่งกรณีนี้เป็นเพียงการโต้แย้งผู้แย่งการ\n\nครอบครองเท่านั้น ดังนั้น เมื่อปรากฏข้อเท็จจริงว่า คำม่วนได้ฟ้องศาลเพื่อเรียกที่ดินพิพาทคืนจากคำปันใน วันที่ 1 มิถุนายน 2542 ซึ่งเกิน 1 ปีนับแต่ถูกแย่งการครอบครอง คำม่วนจึงไม่มีอำนาจฟ้องเรียกคืนการ ครอบครองที่พิพาทจากคำปันตามมาตรา 1375 วรรคสอง","conclusion":"สรุป คำม่วนจะฟ้องเรียกคืนที่ดินพิพาทจากคำปันไม่ได้","otherSections":[]},{"id":"archive-2552-s-4-45","year":"2552","semester":"ภาคฤดูร้อน","number":4,"page":45,"course":"LAW2001 (LA 201 / LW 204)","title":"ปี 2552 ภาคฤดูร้อน · ข้อ 4","sections":["1382","1387","1401"],"kind":"old-exam-source","source":"แนวข้อสอบเก่าวิชาทรัพย์สิน.pdf","question":"ข้อ 4. ป้อมตั้งแผงขายผลไม้อยู่ในที่ดินของแก่นโดยไม่ได้รับอนุญาตจากแก่น และต้องการเพียงใช้เป็นที่ ขายผลไม้โดยไม่มีเจตนาจะยึดเป็นเจ้าของแต่อย่างใด ป้อมใช้พื้นที่ดังกล่าวขายผลไม้ติดต่อกันได้ 10 กว่าปี แล้ว แก่นจึงแจ้งให้ป้อมย้ายออกไปจากที่ดินของตน แต่ป้อมอ้างว่าตนใช้ที่ดินดังกล่าวเป็นเวลากว่า 10 ปี แล้ว จึงได้ภาระจำยอมเหนือที่ดินของแก่น และเรียกให้แก่นไปจดทะเบียนภาระจำยอมให้ป้อม ให้ท่าน วินิจฉัยว่า ข้ออ้างของป้อมที่ว่าได้ภาระจำยอมแล้วรับฟังได้หรือไม่ และป้อมจะเรียกให้แก่นจดทะเบียน ภาระจำยอมให้กับตนได้หรือไม่ เพราะเหตุใด","rule":"มาตรา 1382 บุคคลใดครอบครองทรัพย์สินของผู้อื่นไว้โดยความสงบและโดยเปิดเผยด้วยเจตนา เป็นเจ้าของ ถ้าเป็นอสังหาริมทรัพย์ได้ครอบครองติดต่อกันเป็นเวลาสิบปี ถ้าเป็นสังหาริมทรัพย์ได้ ครอบครองติดต่อกันเป็นเวลาห้าปีไซร้ ท่านว่าบุคคลนั้นได้กรรมสิทธิ์\n\nมาตรา 1387 อสังหาริมทรัพย์อาจต้องตกอยู่ในภาระจำยอมอันเป็นเหตุให้เจ้าของต้องยอมรับกรรม บางอย่างซึ่งกระทบถึงทรัพย์สินของตน หรือต้องงดเว้นการใช้สิทธิบางอย่างอันมีอยู่ในกรรมสิทธิ์ทรัพย์สิน นั้นเพื่อประโยชน์แก่อสังหาริมทรัพย์อื่น\n\nมาตรา 1401 ภาระจำยอมอาจได้มาโดยอายุความ ท่านให้นำบทบัญญัติว่าด้วยอายุความได้สิทธิอัน กล่าวไว้ในลักษณะ 3 แห่งบรรพนี้มาใช้บังคับโดยอนุโลม","application":"โดยหลัก การได้ภาระจำยอมโดยอายุความ เป็นการได้ทรัพยสิทธิเกี่ยวกับอสังหาริมทรัพย์โดยทาง อื่นนอกจากนิติกรรม ซึ่งตามมาตรา 1401 บัญญัติให้นำบทบัญญัติว่าด้วยอายุความได้สิทธิตาม มาตรา 1382 มาใช้บังคับโดยอนุโลม กล่าวคือ ต้องเป็นการครอบครองทรัพย์สินของผู้อื่นโดยความ สงบ เปิดเผย และเจตนาเป็นเจ้าของและครอบครองติดต่อกันเป็นเวลา 10 ปี แต่อย่างไรก็ตาม ภาระจำยอมจะเกิดมีขึ้นได้ก็เพื่อประโยชน์แก่อสังหาริมทรัพย์อื่นซึ่งเรียกว่าสามยทรัพย์ เท่านั้น ตามมาตรา 1387 ดังนั้น ถ้าเป็นการใช้อสังหาริมทรัพย์เพื่อประโยชน์ส่วนตัวแม้จะใช้ติดต่อกันนาน เกินกว่า 10 ปี ก็ไม่ทำให้เกิดภาระจำยอมโดยอายุความขึ้นได้ กรณีตามอุทาหรณ์ การที่ป้อมตั้งแผงขายผลไม้อยู่ในที่ดินของแก่นโดยไม่ได้รับอนุญาตจากแก่นและ ต้องการเพียงใช้เป็นที่ขายผลไม้โดยไม่มีเจตนาจะยึดถือเป็นเจ้าของแต่อย่างใด จึงไม่ใช่เป็นการครอบครอง ปรปักษ์ตามมาตรา 1382 เพราะป้อมไม่มีเจตนาเป็นเจ้าของ\n\nและการที่ป้อมใช้ที่ดินของแก่นเพื่อตั้งแผงขายผลไม้ก็ไม่ใช่เป็นการใช้ที่ดินเพื่อประโยชน์แก่ อสังหาริมทรัพย์อื่น แม้จะมีการใช้ที่ดินเพื่อขายผลไม้ติดต่อกันนานเกินกว่า 10 ปีแล้ว ที่ดินของป้อมก็ ไม่ได้ภาระจำยอมเหนือที่ดินของแก่นโดยอายุความปรปักษ์ตามมาตรา 1401 ประกอบมาตรา 1382 และ มาตรา 1387","conclusion":"สรุป ข้ออ้างของป้องที่ว่าได้ภาระจำยอมเหนือที่ดินของแก่นแล้วรับฟังไม่ได้ และป้อมจะเรียกให้ แก่นจดทะเบียนภาระจำยอมให้กับตนไม่ได้เช่นกัน","otherSections":[]},{"id":"archive-2552-2-1-47","year":"2552","semester":"ภาค 2","number":1,"page":47,"course":"LAW2001 (LA 201 / LW 204)","title":"ปี 2552 ภาค 2 · ข้อ 1","sections":["1299","1382"],"kind":"old-exam-source","source":"แนวข้อสอบเก่าวิชาทรัพย์สิน.pdf","question":"ข้อ 1. เชิดทำสัญญาขายที่ดินมีโฉนดแปลงหนึ่งให้กับชัย โดยชำระราคากันครบถ้วนและส่งมอบที่ดินกัน แล้ว แต่สัญญาดังกล่าวมิได้จดทะเบียนกับพนักงานเจ้าหน้าที่ หลังจากชัยเข้าครอบครองทำประโยชน์ใน ที่ดินแปลงนี้ได้ 9 ปี เชิดได้ทำสัญญาและจดทะเบียนกับพนักงานเจ้าหน้าที่ขายฝากที่ดินแปลงนี้ให้แก่โตมี กำหนด 2 ปี โดยโตไม่รู้ข้อเท็จจริงเรื่องการซื้อขายที่ดินระหว่างเชิดกับชัย หลังจากครบกำหนด 2 ปี ตามสัญญาขายฝากแล้ว เชิดไม่ใช้สิทธิไถ่คืนที่ดิน โตจะเข้าไปครอบครองที่ดิน แปลงนี้แต่พบชัยครอบครองทำประโยชน์ในที่ดินอยู่ โตจึงแจ้งให้ชัยย้ายออกไปจากที่ดินแปลงนี้ แต่ชัยอ้าง ว่าที่ดินเป็นกรรมสิทธิ์ของตน เชิดไม่มีสิทธินำที่ดินแปลงนี้ไปขายให้กับผู้ใด และชัยก็ครอบครองโดยสงบ เปิดเผยและมีเจตนาเป็น เจ้าของติดต่อกันมาเกินกว่า 10 ปีแล้ว\n\nดังนี้ให้วินิจฉัยว่า ระหว่างชัยกับโต ผู้ใดมีกรรมสิทธิ์ในที่ดินแปลงนี้ดีกว่ากัน และชัยจะขอให้ศาล เพิกถอนการจดทะเบียนขายฝากระหว่างเชิดกับโตได้หรือไม่ เพราะเหตุใด","rule":"มาตรา 1299 วรรคสอง ถ้ามีผู้ได้มาซึ่งอสังหาริมทรัพย์ หรือทรัพยสิทธิอันเกี่ยวกับอสังหาริมทรัพย์ โดยทางอื่นนอกจากนิติกรรม สิทธิของผู้ได้มานั้น ถ้ายังมิได้จดทะเบียนไซร้ ท่านว่าจะมีการเปลี่ยนแปลง ทางทะเบียนไม่ได้ และสิทธิอันยังมิได้จดทะเบียนนั้น มิให้ยกเป็นข้อต่อสู้บุคคลภายนอกผู้ได้สิทธิมาโดย เสียค่าตอบแทนและโดยสุจริตและได้จดทะเบียนสิทธิโดยสุจริตแล้ว\n\nมาตรา 1300 ถ้าได้จดทะเบียนการโอนอสังหาริมทรัพย์ หรือทรัพยสิทธิอันเกี่ยวกับ อสังหาริมทรัพย์ เป็นทางเสียเปรียบแก่บุคคลผู้อยู่ในฐานะอันจะให้จดทะเบียนสิทธิของตนได้อยู่ก่อน ไซร้ ท่านว่าบุคคลนั้นอาจเรียกให้เพิกถอนการจดทะเบียนนั้นได้ แต่การโอนอันมีค่าตอบแทน ซึ่งผู้รับโอนกระทำการโดยสุจริตนั้น ไม่ว่ากรณีจะเป็นประการใด ท่านว่าจะ เรียกให้เพิกถอนทะเบียนไม่ได้","application":"กรณีตามอุทาหรณ์ เมื่อได้ความว่าสัญญาซื้อขายที่ดินมีโฉนดซึ่งเป็นอสังหาริมทรัพย์ระหว่างเชิด กับชัยแม้จะได้ชำระราคากันครอบถ้วนและส่งมอบที่ดินกันแล้ว แต่เมื่อไม่ได้จดทะเบียนกับพนักงาน เจ้าหน้าที่สัญญาซื้อขายดังกล่าวจึงตกเป็นโมฆะตามมาตรา 456 วรรคแรก\n\nและตามข้อเท็จจริง เมื่อชัยผู้ซื้อเข้าไปครอบครองทำประโยชน์ในที่ดินแปลงนี้ติดต่อกันได้ 9 ปี เชิดได้ทำ สัญญาและได้จดทะเบียนกับพนักงานเจ้าหน้าที่ขายฝากที่ดินแปลงนี้ให้แก่โตมีกำหนด 2 ปี โดยโตไม่รู้เรื่อง การซื้อขายที่ดินระหว่างเชิดกับชัย และหลังจากครบกำหนด 2 ปี ตามสัญญาขายฝากแล้ว เชิดไม่ใช้สิทธิไถ่คืนที่ดิน และในขณะเดียวกันชัยก็ยังคงครอบครองที่ดินแปลง นี้โดยสงบ เปิดเผย และเจตนาเป็นเจ้าของติดต่อกันเป็นเวลา 11 ปี กรณีเช่นนี้ จึงถือว่าชัยได้กรรมสิทธิ์ใน ที่ดินแปลงนี้โดยการครอบครองปรปักษ์ตามมาตรา 1382 อันเป็นการได้มาวึ่งอสังหาริมทรัพย์โดยทางอื่น นอกจากนิติกรรม แต่เมื่อชัยยังไม่ได้จดทะเบียนเปลี่ยนชื่อในโฉนดเป็นชื่อของตน ชัยจึงไม่สามารถยกการ ได้มานั้นขึ้นเป็นข้อต่อสู้บุคคลภายนอกผู้ได้สิทธิในอสังหาริมทรัพย์นั้นมาโดยมีค่าตอบแทนและโดย สุจริต และจดทะเบียนสิทธิโดยสุจริตแล้วตามมาตรา 1299 วรรคสอง (ฎ. 884/2523) ดังนั้น เมื่อโตซึ่งเป็นบุคคลภายนอกเป็นผู้ได้สิทธิในที่ดินแปลงนี้ไปโดยมีค่าตอบแทนและโดยสุจริต และ ได้จดทะเบียนโดยสุจริตแล้ว จึงมีกรรมสิทธิ์ในที่ดินแปลงนี้ดีกว่าชัย และถึงแม้ชัยจะเป็นผู้อยู่ในฐานะอัน จะจดทะเบียนสิทธิได้ก่อน และการจดทะเบียนขายฝากระหว่างเชิดกับโตจะทำให้ชัยเสียเปรียบก็ตาม แต่ ชัยก็ไม่สามารถขอให้เพิกถอนการจดทะเบียนการขายฝากระหว่างเชิดกับโตได้ ทั้งนี้เพราะโตจดทะเบียน โดยมีค่าตอบแทนและโดยสุจริตตามมาตรา 1300","conclusion":"สรุป ระหว่างชัยกับโต โตมีกรรมสิทธิ์ในที่ดินแปลงนี้ดีกว่าชัย และชัยจะขอให้ศาลเพิกถอนการ จดทะเบียนการขายฝากระหว่างเชิดกับโตไม่ได้","otherSections":["1300","456"]},{"id":"archive-2552-2-3-49","year":"2552","semester":"ภาค 2","number":3,"page":49,"course":"LAW2001 (LA 201 / LW 204)","title":"ปี 2552 ภาค 2 · ข้อ 3","sections":["1367","1375"],"kind":"old-exam-source","source":"แนวข้อสอบเก่าวิชาทรัพย์สิน.pdf","question":"ข้อ 3. สมดีขายฝากที่ดินมือเปล่าของสมดีแปลงหนึ่งให้แสงสี กำหนดเวลาไถ่คืน 5 ปี โดยทำสัญญาเป็น หนังสือลงลายมือชื่อคู่สัญญาทั้งสองและส่งมอบที่ดินให้แสงสี เมื่อขายฝากไปได้ 4 ปีกับ 8 เดือ สมดีจะมา ขอไถ่ที่ดินแปลงนี้คืน แต่แสงสีไม่ยอมให้ไถ่อ้างว่า ภริยาของสมดีได้มาตกลงขายขาดที่ดินแปลงนี้กับตน แล้ว และตนได้จ่ายเงินให้ภริยาสมดีไป 200,000 บาท สมดีหมดสิทธิไถ่คืนแล้ว ที่ดินแปลงนี้เป็นของตนอย่าง เด็ดขาด หลังจากแสงสีบอกกับสมดีว่าที่ดินแปลงนั้นเป็นของตนมาได้ 1 ปี กับ 3 เดือน สมดีจึงได้อพยพ ครอบครัวเข้าไปครอบครองปลูกบ้านอยู่อาศัยทำประโยชน์บนที่ดินแปลงนั้น สมดีเข้าครอบครองทำ ประโยชน์บนที่ดินแปลงนั้นมาได้ 4 เดือน แสงดีได้มาฟ้องขับไล่ให้สมดีออกไปจากที่ดินแปลงนั้น\n\nให้ท่านวินิจฉัยว่า แสงสีจะฟ้องขับไล่สมดีให้ออกไปจากที่ดินแปลงนั้นได้หรือไม่ เพราะเหตุใด","rule":"มาตรา 1367 บุคคลใดยึดถือทรัพย์สินโดยเจตนาจะยึดถือเพื่อตน ท่านว่าบุคคลนั้นได้ซึ่งสิทธิ ครอบครอง\n\nมาตรา 1375 ถ้าผู้ครอบครองถูกแย่งการครอบครองโดยมิชอบด้วยกฎหมายไซร้ ท่านว่าผู้ ครอบครองมีสิทธิจะได้คืนซึ่งการครอบครอง เว้นแต่อีกฝ่ายหนึ่งมีสิทธิเหนือทรัพย์สินดีกว่า ซึ่งจะเป็นเหตุ ให้เรียกคืนจากผู้ครอบครองได้ การฟ้องคดีเพื่อเอาคืนซึ่งการครอบครองนั้น ท่านว่าต้องฟ้องภายในปีหนึ่งนับแต่เวลาถูกแย่งการ ครอบครอง\n\nมาตรา 1381 บุคคลใดยึดถือทรัพย์สินอยู่ในฐานะเป็นผู้แทนผู้ครอบครอง บุคคลนั้นจะเปลี่ยน ลักษณะแห่งการยึดถือได้ ก็แต่โดยบอกกล่าวไปยังผู้ครอบครองว่า ไม่เจตนาจะยึดถือทรัพย์สินแทนผู้ ครอบครองต่อไป หรือตนเองเป็นผู้ครอบครองโดยสุจริต อาศัยอำนาจใหม่อันได้จากบุคคลภายนอก","application":"โดยหลักแล้ว ถ้าผู้ครอบครองถูกแย่งการครอบครองโดยมิชอบด้วยกฎหมาย ผู้ครอบครองมีสิทธิ ฟ้องเรียกคืนซึ่งการครอบครองภายใน 1 ปี นับแต่เวลาถูกแย่งการครอบครอง เว้นแต่อีกฝ่ายหนึ่งมีสิทธิ เหนือทรัพย์สินดีกว่าซึ่งจะเป็นเหตุให้เรียกคืนจากผู้ครอบครองได้ (มาตรา 1375) กรณีตามอุทาหรณ์ สมดีขายฝากที่ดินมือเปล่าของสมดีแปลงหนึ่งให้แสงสี กำหนดเวลาไถ่คืน 5 ปี โดยทำ สัญญาเป็นหนังสือลงลายมือชื่อคู่สัญญาทั้งสองและส่งมอบที่ดินให้แสงสี เมื่อขายฝากไป ได้ 4 ปี 8 เดือน สมดีจะมาขอไถ่ที่ดินคืน แต่แสงสีไม่ยอมให้ไถ่โดยอ้างว่าภริยาของสมดีได้มาตกลงขาย ที่ดินแปลงนี้ให้กับตนแล้ว และตนได้จ่ายเงินให้ภริยาสมดีไป 2 แสนบาท สมดีหมดสิทธิไถ่คืนแล้ว ที่ดิน เป็นของตนอย่างเด็ดขาดแล้ว กรณีจึงถือว่าแสงสีได้เปลี่ยนเจตนาการยึดถือตามมาตรา 1381 แสงสีจึงได้ไป ซึ่งสิทธิครอบครองตามมาตรา 1367 เมื่อได้ความว่า ภายหลังจากแสงสีแย่งการครอบครองมาได้ 1 ปี 3 เดือน ซึ่งเลยระยะเวลาการฟ้องเรียกคืน การครอบครองตามมาตรา 1375 แล้ว สมดีได้อพยพเข้าไปครอบครองปลูกบ้านอยู่อาศัยทำประโยชน์ใน ที่ดินแปลงนั้น จึงเป็นกรณีที่สมดีเอาคืนซึ่งการครอบครองด้วยตนเอง แต่เมื่อสมดีเข้าครอบครองทำ ประโยชน์ในที่ดินแปลงนั้นมาได้เพียง 4 เดือน (ยังไม่เกิน 1 ปี) ยังไม่หมดระยะการฟ้องเรียกคืนตาม มาตรา 1375 แสงสีจึงฟ้องขับไล่ให้สมดีออกไปจากที่ดินแปลงนั้นได้","conclusion":"สรุป แสงสีฟ้องขับไล่ให้สมดีออกไปจากที่ดินแปลงนั้นได้","otherSections":["1381"]},{"id":"archive-2552-1-1-52","year":"2552","semester":"ภาค 1","number":1,"page":52,"course":"LAW2001 (LA 201 / LW 204)","title":"ปี 2552 ภาค 1 · ข้อ 1","sections":["1299","1382"],"kind":"old-exam-source","source":"แนวข้อสอบเก่าวิชาทรัพย์สิน.pdf","question":"ข้อ 1. เพลิงครอบครองปรปักษ์ที่ดินมีโฉนดของน้ำฝนเกินกว่า 10 ปีแล้ว แต่เพลิงยังไม่ได้ดำเนินการจด ทะเบียนเปลี่ยนชื่อในโฉนดที่ดินเป็นของตน หลังจากนั้นน้ำฝนถึงแก่ความตาย น้ำผึ้งบุตรของน้ำฝนได้จด ทะเบียนรับมรดกที่ดินแปลงนั้น ต่อมาอีก 1 ปี น้ำผึ้งทำสัญญาและจดทะเบียนขายที่ดินแปลงนั้นให้ เปลว โดยก่อนจดทะเบียนโอนกรรมสิทธิ์ เปลวได้ไปดูที่ดินแต่ไม่เห็นผู้ใดครอบครองที่ดินดังกล่าว แต่ หลังจากน้ำผึ้งจดทะเบียนโอนกรรมสิทธิ์ที่ดินให้เปลวแล้ว เปลวจึงรู้ว่าเพลิงครอบครองปรปักษ์ที่ดินแปลง นั้น จึงห้ามไม่ให้เพลิงเข้าไปยุ่งเกี่ยวกับที่ดินแปลงนั้นอีก\n\nดังนี้ให้วินิจฉัยว่า ระหว่างเปลวกับเพลิงผู้ใดมีกรรมสิทธิ์ในที่ดินแปลงนั้นดีกว่ากัน และเพลิงจะ ยื่นคำร้องขอให้ศาลมีคำสั่งเพิกถอนการจดทะเบียนโอนกรรมสิทธิ์ที่ดินระหว่างน้ำผึ้งกับเปลวได้ หรือไม่ เพราะเหตุใด","rule":"มาตรา 1299 วรรคสอ ถ้ามีผู้ได้มาซึ่งอสังหาริมทรัพย์ หรือทรัพยสิทธิอันเกี่ยวกับอสังหาริมทรัพย์ โดยทางอื่นนอกจากนิติกรรม สิทธิของผู้ได้มานั้น ถ้ายังมิได้จดทะเบียนไซร้ ท่านว่าจะมีการเปลี่ยนแปลง ทางทะเบียนไม่ได้ และสิทธิอันยังมิได้จดทะเบียนนั้น มิให้ยกเป็นข้อต่อสู้บุคคลภายนอกผู้ได้สิทธิมาโดย เสียค่าตอบแทนและโดยสุจริตและได้จดทะเบียนสิทธิโดยสุจริตแล้ว\n\nมาตรา 1300 ถ้าได้จดทะเบียนการโอนอสังหาริมทรัพย์ หรือทรัพยสิทธิอันเกี่ยวกับ อสังหาริมทรัพย์ เป็นทางเสียเปรียบแก่บุคคลผู้อยู่ในฐานะอันจะให้จดทะเบียนสิทธิของตนได้อยู่ก่อน ไซร้ ท่านว่าบุคคลนั้นอาจเรียกให้เพิกถอนการจดทะเบียนนั้นได้ แต่การโอนอันมีค่าตอบแทน ซึ่งผู้รับโอนกระทำการโดยสุจริตนั้น ไม่ว่ากรณีจะเป็นประการใด ท่านว่าจะ เรียกให้เพิกถอนทะเบียนไม่ได้","application":"กรณีตามอุทาหรณ์ เพลิงครอบครองปรปักษ์ที่ดินมีโฉนดของน้ำฝนเกินกว่า 10 ปี จึงได้กรรมสิทธิ์ ในที่ดินดังกล่าวโดยการครอบครองปรปักษ์ตามมาตรา 1382 และถือเป็นการได้มาซึ่งอสังหาริมทรัพย์โดย ทางอื่นนอกจากนิติกรรมตามมาตรา 1299 วรรคสอง ดังนั้นเมื่อไม่ได้จดทะเบียนการได้มาต่อพนักงาน เจ้าหน้าที่ เพลิงก็จะเปลี่ยนแปลงทางทะเบียนไม่ได้ และสิทธิอันยังไม่ได้จดทะเบียนนั้น มิให้ยกขึ้นต่อสู้ บุคคลภายนอกผู้ได้สิทธิมาโดยเสียค่าตอบแทนและโดยสุจริต และได้จดทะเบียนสิทธิโดยสุจริตแล้ว สำหรับกรณีที่น้ำฝนเจ้าของที่ดินถึงแก่ความตาย และน้ำผึ้งบุตรของน้ำฝนจดทะเบียนรับมรดกที่ดินแปลง ดังกล่าวมานั้น กรณีเช่นนี้ถือว่าน้ำผึ้งรับโอนที่ดินดังกล่าวในฐานะทายาทโดยธรรมของน้ำฝน อันเป็นการ\n\nรับทรัพย์มรดกตามกฎหมายว่าด้วยมรดก ซึ่งทายาทต้องรับไปทั้งสิทธิและตลอดจนความรับผิดต่างๆของ เจ้ามรดก ทั้งถือไม่ได้ว่าน้ำผึ้งเป็นบุคคลภายนอกที่ได้กรรมสิทธิ์ที่ดินโดยมีค่าตอบแทน ดังนั้น ระหว่าง เพลิงกับน้ำผึ้ง เพลิงจึงมีกรรมสิทธิ์ในที่ดินดังกล่าวดีกว่าน้ำผึ้ง (ฎ. 1886/2536 ฎ. 1069 – 1070/2522) ประเด็นที่ต้องวินิจฉัยประการแรกมีว่า ระหว่างเปลวและเพลิง ใครมีกรรมสิทธิ์ในที่ดินแปลงนี้ดีกว่า กัน เห็นว่า ขณะที่เพลิงยังไม่ได้ดำเนินการเปลี่ยนชื่อในโฉนดเป็นชื่อของตน น้ำผึ้งซึ่งไม่มีสิทธิดีกว่าเพลิง ได้จดทะเบียนขายที่ดินแปลงที่ตกเป็นกรรมสิทธิ์แก่เพลิงแล้วให้เปลว โดยก่อนจดทะเบียนโอน กรรมสิทธิ์ เปลวได้ไปดูที่ดินแต่ไม่เห็นผู้ใดครอบครองที่ดินดังกล่าว แต่หลังจากน้ำผึ้งจดทะเบียนโอน กรรมสิทธิ์ที่ดินให้เปลวแล้ว เปลวจึงรู้ว่าเพลิงครอบครองปรปักษ์ที่ดินแปลงนั้น กรณีเช่นนี้ถือว่าเปลวเป็น บุคคลภายนอกซื้อที่ดินมาโดยสุจริต เสียค่าตอบแทนและจดทะเบียนสิทธิโดยสุจริต จึงได้รับความคุ้มครอง ตามมาตรา 1299 วรรคสอง ซึ่งเป็นบทยกเว้นหลักทั่วไปที่ว่า ผู้รับโอนไม่มีสิทธิดีกว่าผู้โอน ดังนั้นแม้ เปลวจะรับโอนมาจากน้ำผึ้งผู้ที่ไม่มีสิทธิในที่ดินดีกว่าเพลิง เปลวก็ยังมีสิทธิดีกว่าเพลิง เพลิงจะอ้างหลัก ผู้รับโอนไม่มีสิทธิดีกว่าผู้โอนมาใช้ยันเปลวไม่ได้ ประเด็นที่ต้องวินิจฉัยประการต่อมามีว่า เพลิงจะยื่นคำร้องขอให้ศาลมีคำสั่งเพิกถอนการจดทะเบียนโอน กรรมสิทธิ์ที่ดินระหว่างน้ำผึ้งกับเปลวได้หรือไม่ เห็นว่า แม้เพลิงจะเป็นผู้อยู่ในฐานะอันจะให้จดทะเบียน สิทธิของตนได้อยู่ก่อนตามมาตรา 1300 และการจดทะเบียนโอนกรรมสิทธิ์ระหว่างน้ำผึ้งกับเปลวจะทำให้ เพลิงเสียเปรียบก็ตาม เพลิงก็ไม่สามารถยื่นคำร้องขอให้ศาลมีคำสั่งเพิกถอนการจดทะเบียนดังกล่าว เพราะ การจดทะเบียนรับโอนกรรมสิทธิ์ของเปลวนั้นมีค่าตอบแทนและเป็นการจดทะเบียนโดยสุจริต (ฎ. 32/2490)","conclusion":"สรุป เปลวเป็นผู้มีกรรมสิทธิ์ในที่ดินดีกว่าเพลิง และเพลิงจะยื่นคำร้องขอให้ศาลมีคำสั่งเพิกถอน การจดทะเบียนโอนกรรมสิทธิ์ระหว่างน้ำผึ้งกับเปลวไม่ได้","otherSections":["1300"]},{"id":"archive-2552-1-3-54","year":"2552","semester":"ภาค 1","number":3,"page":54,"course":"LAW2001 (LA 201 / LW 204)","title":"ปี 2552 ภาค 1 · ข้อ 3","sections":["1367","1375"],"kind":"old-exam-source","source":"แนวข้อสอบเก่าวิชาทรัพย์สิน.pdf","question":"ข้อ 3. ใสได้ตกลงขอทำถนนผ่านที่ดินของแสงซึ่งเป็นที่ดินมือเปล่า แต่ก็ยังไม่ถึงทางสาธารณะ ใสจะต้อง ทำถนนผ่านที่ดินของเสียงอีกแปลงหนึ่งซึ่งเป็นที่ดินเปล่าจึงจะถึงทางสาธารณะได้ แต่ใสไม่สามารถติดต่อ\n\nเสียงได้จึงได้ทำถนนผ่านที่ดินของเสียงไปโดยพลการ และนอกจากนั้นเมื่อเห็นที่ดินของเสียงทิ้งร้างไว้ ใส จึงยังใช้ที่ดินของเสียงทั้งแปลงทำไร่ข้าวโพด ใสใช้ทางผ่านที่ดินของทั้งแสงและเสียงและทำไร่ข้าวโพดบน ที่ดินของเสียงผ่านมาได้ห้าปี\n\nถ้าเสียงฟ้องเรียกคืนและห้ามไม่ให้ใสเข้ามายุ่งเกี่ยวในที่ดินของตน ใสจะมีข้อต่อสู้เสียงได้อย่างไร บ้าง เพราะเหตุใด","rule":"มาตรา 1367 บุคคลใดยึดถือทรัพย์สินโดยเจตนาจะยึดถือเพื่อตน ท่านว่าบุคคลนั้นได้ซึ่งสิทธิ ครอบครอง\n\nมาตรา 1375 ถ้าผู้ครอบครองถูกแย่งการครอบครองโดยมิชอบด้วยกฎหมายไซร้ ท่านว่าผู้ ครอบครองมีสิทธิจะได้คืนซึ่งการครอบครอง เว้นแต่อีกฝ่ายหนึ่งมีสิทธิเหนือทรัพย์สินดีกว่า ซึ่งจะเป็นเหตุ ให้เรียกคืนจากผู้ครอบครองได้ การฟ้องคดีเพื่อเอาคืนซึ่งการครอบครองนั้น ท่านว่าต้องฟ้องภายในปีหนึ่งนับแต่เวลาถูกแย่งการ ครอบครอง","application":"กรณีตามอุทาหรณ์ ประเด็นที่ต้องวินิจฉัยมีว่า ถ้าเสียงฟ้องเรียกคืนและห้ามไม่ให้ใสเข้ามายุ่งเกี่ยว ในที่ดินของตน ใสจะมีข้อต่อสู้เสียงได้อย่างไรบ้าง เห็นว่า การที่ใสได้ตกลงขอทำถนนผ่านที่ดินของ แสง ซึ่งเป็นที่ดินมือเปล่า แต่ก็ยังไม่ถึงทางสาธารณะ ใสจะต้องทำถนนผ่านที่ดินของเสียงอีกแปลงหนึ่งซึ่ง เป็นที่ดินมือเปล่าจึงจะถึงทางสาธารณะได้ แต่ใสไม่สามารถติดต่อเสียงได้จึงได้ทำถนนผ่านที่ดินของเสียง ไปโดยพลการ นอกจากนั้นเมื่อเห็นที่ดินของเสียงทิ้งร้างไว้ ใสจึงยังใช้ที่ดินของเสียงทั้งแปลงทำไร่ ข้าวโพด อันเป็นการยึดถือทำประโยชน์ในทรัพย์สิน กรณีเช่นนี้ถือว่าใสได้เข้ายึดถือทรัพย์สินโดยเจตนาจะ ยึดถือเพื่อตนแล้ว ใสจึงได้สิทธิครอบครองในที่ดินมือเปล่าของเสียงทั้งแปลงตามมาตรา 1367 และกรณีนี้ ยังถือว่าใสได้แย่งการครอบครองมือเปล่าของเสียงด้วยตามมาตรา 1375 วรรคแรก เมื่อเสียงผู้ครอบครองถูกใสแย่งการครอบครองโดยมิชอบด้วยกฎหมาย กฎหมายให้สิทธิเสียงฟ้องเรียกคืน ซึ่งการครอบครองได้ภายใน 1 ปี นับแต่เวลาถูกแย่งการครอบครอง โดยไม่คำนึงว่าผู้ครอบครองจะทราบว่า ถูกแย่งการครอบครองหรือไม่ และไม่คำนึงถึงว่าผู้ครอบครองได้โต้แย้งผู้แย่งหารครอบครองหรือได้ ร้องเรียนต่อพนักงานฝ่ายปกครองว่าถูกแย่งการครอบครองหรือไม่ (ฎ. 6412/2550 ฎ.108/2517) เมื่อ ข้อเท็จจริงคดีนี้ปรากฏว่าใสได้ใช้ทางผ่านที่ดินมือเปล่าทั้งของแสงและเสียงและทำไร่ข้าวโพดบนที่ดินของ เสียงผ่านมาได้ 5 ปี เสียงจึงหมดสิทธิฟ้องเรียกคืนการครอบครองแล้วตามมาตรา 1375 วรรคสอง ถ้าเสียง ฟ้องเรียกคืนซึ่งการครอบครองและห้ามมิให้ใสเข้ามายุ่งเกี่ยวในที่ดินของตน ใสย่อมสามารถยกข้อต่อสู้ได้ ว่าเสียงหมดสิทธิเรียกคืนซึ่งการครอบครองแล้ว และตนได้สิทธิครอบครองในที่ดินของเสียงแล้ว","conclusion":"สรุป ใสสามารถยกข้อต่อสู้ได้ว่าเสียงหมดสิทธิเรียกคืนซึ่งการครอบครองตามมาตรา 1375 และตน ได้สิทธิครอบครองในที่ดินของเสียงแล้ว","otherSections":[]},{"id":"archive-2552-1-4-56","year":"2552","semester":"ภาค 1","number":4,"page":56,"course":"LAW2001 (LA 201 / LW 204)","title":"ปี 2552 ภาค 1 · ข้อ 4","sections":["1368","1382"],"kind":"old-exam-source","source":"แนวข้อสอบเก่าวิชาทรัพย์สิน.pdf","question":"ข้อ 4. นายฟ้าครอบครองปรปักษ์ทำนาบนที่ดินมีโฉนดแปลงหนึ่งของเหลืองมาเข้าปีที่แปด นายฟ้าประสบ อุบัติเหตุ ต้องรักษาตัวอยู่ที่โรงพยาบาล นายฟ้าทราบว่าแม้ออกจากโรงพยาบาลแล้วร่างกายตนคงทำนา ไม่ได้อีกแล้ว ขณะรักษาตัวอยู่ในโรงพยาบาลได้ 6 เดือน ได้ยกที่ดินแปลงนั้นให้บุตรชายทำนาต่อจาก ตน บุตรชายนายฟ้าจึงเข้าไปครอบครองที่ดินแปลงนั้น และเอาที่ดินแปลงนั้นไปให้นายแดงเช่าแทน นาย แดงนำที่ดินแปลงนั้นไปปลูกยางพารา แดงเช่าที่ดินแปลงนั้นมาได้สามปี เหลืองได้ฟ้องคดีต่อศาลขับไล่ให้ แดงและบุตรชายนายฟ้าออกจากที่ดินแปลงนั้น\n\nตามหลักกฎหมายแพ่งและพาณิชย์ บุตรชายนายฟ้าได้กรรมสิทธิ์โดยการครอบครองปรปักษ์ใน ที่ดินแปลงนั้นแล้วหรือยัง เพราะเหตุใด","rule":"มาตรา 1368 บุคคลอาจได้มาซึ่งสิทธิครอบครองโดยผู้อื่นยึดถือไว้ให้\n\nมาตรา 1382 บุคคลใดครอบครองทรัพย์สินของผู้อื่นไว้โดยความสงบและโดยเปิดเผยด้วยเจตนา เป็นเจ้าของ ถ้าเป็นอสังหาริมทรัพย์ได้ครอบครองติดต่อกันเป็นเวลาสิบปี ถ้าเป็นสังหาริมทรัพย์ได้ ครอบครองติดต่อกันเป็นเวลาห้าปีไซร้ ท่านว่าบุคคลนั้นได้กรรมสิทธิ์\n\nมาตรา 1384 “ถ้าผู้ครอบครองขาดยึดถือทรัพย์สินโดยไม่สมัคร และได้คืนภายในเวลาปีหนึ่ง นับตั้งแต่วันขาดยึดถือ หรือได้คืนโดยฟ้องคดีภายในกำหนดนั้นไซร้ ท่านมิให้ถือว่าการครอบครองสะดุด หยุดลง”\n\nมาตรา 1385 ถ้าโอนการครอบครองแก่กัน ผู้รับโอนจะนับเวลาซึ่งผู้โอนครอบครองอยู่ก่อนนั้น รวมเข้ากับเวลาครอบครองของตนก็ได้ ถ้าผู้รับโอนนับรวมเช่นนั้น และถ้ามีข้อบกพร่องในระหว่าง ครอบครองของผู้โอนไซร้ ท่านว่าข้อบกพร่องนั้นอาจยกขึ้นเป็นข้อต่อสู้ผู้รับโอนได้","application":"โดยหลักแล้ว การได้กรรมสิทธิ์ในอสังหาริมทรัพย์โดยการครอบครองปรปักษ์ตาม มาตรา 1382 จะต้องประกอบด้วยหลักเกณฑ์ดังนี้ คือ\n\n1 เป็นทรัพย์สินของผู้อื่นโดยผู้อื่นมีกรรมสิทธิ์\n\n2 ได้ครอบครองโดยความสงบ\n\n3 ครอบครองโดยเปิดเผย\n\n4 ครอบครองโดยเจตนาเป็นเจ้าของ\n\n5 ครอบครองติดต่อกันมาเป็นเวลา 10 ปี\n\nสำหรับการครอบครองติดต่อกันนั้น จะต้องเป็นกรณีที่ผู้ครอบครอง ไม่มีเจตนาสละการครอบครอง หรือ ขาดการยึดถือโดยสมัครใจ และนับระยะเวลาครอบครองติดต่อกันได้ หากเป็นเพียงการขาดการยึดถือโดย ไม่สมัคร เพราะมีเหตุมาขัดขวางโดยไม่สมัครใจ กฎหมายถือว่าการขาดการยึดถือนั้นไม่ทำให้ขาดอายุ ความ การครอบครองสะดุดหยุดลง หากได้ทรัพย์สินคืนภายใน 1 ปี นับแต่วันที่ขาดการยึดถือ ทั้งนี้ตาม มาตรา 1384 กรณีตามอุทาหรณ์ ประเด็นที่ต้องวินิจฉัยมีว่า บุตรชายนายฟ้าได้กรรมสิทธิ์โดยการครอบครองปรปักษ์ใน ที่ดินแปลงนั้นหรือยัง เห็นว่า นายฟ้าได้ครอบครองปรปักษ์ทำนาบนที่ดินมีโฉนดแปลงหนึ่งของเหลืองมา เข้าปีที่ 8 นายฟ้าประสบอุบัติเหตุต้องรักษาตัวอยู่โรงพยาบาล กรณีนี้ถือว่านายฟ้าขาดการยึดถือโดยไม่สมัคร ใจเนื่องจากมีเหตุมาขัดขวางหรือไม่มีเจตนาสละการครอบครอง เมื่อนายฟ้าเห็นว่าทำนาต่อไปอีกไม่ได้ จึง ยกที่ดินแปลงนั้นให้บุตรชายทำนาต่อจากตนในขณะที่รักษาตัวอยู่ในโรงพยาบาลได้ 6 เดือน ดังนี้ถือว่าการ ขาดการยึดถือนั้นไม่ทำให้อายุความสะดุดหยุดลง เนื่องจากได้ทรัพย์สินคืนมาภายใน 1 ปี นับแต่วันที่ขาด การยึดถือ โดยมีบุตรชายนายฟ้าเข้ายึดถือแทนตามมาตรา 1384 และในกรณีเช่นนี้บุตรชายนายฟ้าผู้รับโอน การครอบครองโดยนิติกรรมสามารถนับเวลาซึ่งนายฟ้าผู้โอนครอบครองอยู่ก่อนนั้นรวมเข้ากับเวลา ครอบครองของตนก็ได้ ตามมาตรา 1385 อนึ่ง การที่บุตรชายของนายฟ้ากลับเอาที่ดินแปลงนั้นไปให้นายแดงเช่าแทน นายแดงย่อมอยู่ในฐานะเป็นผู้ ยึดถือที่ดินแปลงนั้นแทนบุตรชายนายฟ้าตลอดมาตามมาตรา 1368 (ฎ. 1054/2519 ฎ.1623/2522) เมื่อแดง เช่าที่ดินแปลงนั้นมาได้ 3 ปี รวมกับเวลาที่นายฟ้าครอบครองมาแต่ก่อนและที่กฎหมายถือว่าไม่สะดุดหยุด ลงอีก 8 ปี 6 เดือน รวมเป็น 11 ปี 6 เดือน ตามหลักกฎหมายแพ่งและพาณิชย์ บุตรชายนายฟ้าย่อมได้ กรรมสิทธิ์ในที่ดินแปลงนั้นโดยการครอบครองปรปักษ์ตามมาตรา 1382 แล้ว","conclusion":"สรุป บุตรชายนายฟ้าได้กรรมสิทธิ์โดยการครอบครองปรปักษ์แล้ว","otherSections":["1384","1385"]},{"id":"archive-2552-1-1-58","year":"2552","semester":"ภาค 1","number":1,"page":58,"course":"LAW2001 (LA 201 / LW 204)","title":"ปี 2552 ภาค 1 · ข้อ 1","sections":["1299","1382"],"kind":"old-exam-source","source":"แนวข้อสอบเก่าวิชาทรัพย์สิน.pdf","question":"ข้อ 1 เพลิงครอบครองปรปักษ์ที่ดินมีโฉนดของน้ำฝนเกินกว่า 10 ปีแล้ว แต่เพลิงยังไม่ได้ดำเนินการจด ทะเบียนเปลี่ยนชื่อในโฉนดที่ดินเป็นของตน หลังจากนั้นน้ำฝนถึงแก่ความตาย น้ำผึ้งบุตรของน้ำฝนได้จด ทะเบียนรับมรดกที่ดินแปลงนั้น ต่อมาอีก 1 ปี น้ำผึ้งทำสัญญาและจดทะเบียนขายที่ดินแปลงนั้นให้ เปลว โดยก่อนจดทะเบียนโอนกรรมสิทธิ์ เปลวได้ไปดูที่ดินแต่ไม่เห็นผู้ใดครอบครองที่ดินดังกล่าว แต่ หลังจากน้ำผึ้งจดทะเบียนโอนกรรมสิทธิ์ที่ดินให้เปลวแล้ว เปลวจึงรู้ว่าเพลิงครอบครองปรปักษ์ที่ดินแปลง นั้น จึงห้ามไม่ให้เพลิงเข้าไปยุ่งเกี่ยวกับที่ดินแปลงนั้นอีก\n\nดังนี้ให้วินิจฉัยว่า ระหว่างเปลวกับเพลิงผู้ใดมีกรรมสิทธิ์ในที่ดินแปลงนั้นดีกว่ากัน และเพลิงจะ ยื่นคำร้องขอให้ศาลมีคำสั่งเพิกถอนการจดทะเบียนโอนกรรมสิทธิ์ที่ดินระหว่างน้ำผึ้งกับเปลวได้ หรือไม่ เพราะเหตุใด","rule":"มาตรา 1299 วรรคสอง ถ้ามีผู้ได้มาซึ่งอสังหาริมทรัพย์ หรือทรัพยสิทธิอันเกี่ยวกับ อสังหาริมทรัพย์โดยทางอื่นนอกจากนิติกรรม สิทธิของผู้ได้มานั้น ถ้ายังมิได้จดทะเบียนไซร้ ท่านว่าจะมี การเปลี่ยนแปลงทางทะเบียนไม่ได้ และสิทธิอันยังมิได้จดทะเบียนนั้น มิให้ยกเป็นข้อต่อสู้บุคคลภายนอกผู้ ได้สิทธิมาโดยเสียค่าตอบแทนและโดยสุจริตและได้จดทะเบียนสิทธิโดยสุจริตแล้ว\n\nมาตรา 1300 ถ้าได้จดทะเบียนการโอนอสังหาริมทรัพย์ หรือทรัพยสิทธิอันเกี่ยวกับ อสังหาริมทรัพย์ เป็นทางเสียเปรียบแก่บุคคลผู้อยู่ในฐานะอันจะให้จดทะเบียนสิทธิของตนได้อยู่ก่อน ไซร้ ท่านว่าบุคคลนั้นอาจเรียกให้เพิกถอนการจดทะเบียนนั้นได้ แต่การโอนอันมีค่าตอบแทน ซึ่งผู้รับโอนกระทำการโดยสุจริตนั้น ไม่ว่ากรณีจะเป็นประการใด ท่านว่าจะ เรียกให้เพิกถอนทะเบียนไม่ได้","application":"กรณีตามอุทาหรณ์ เพลิงครอบครองปรปักษ์ที่ดินมีโฉนดของน้ำฝนเกินกว่า 10 ปี จึงได้กรรมสิทธิ์ในที่ดิน ดังกล่าวโดยการครอบครองปรปักษ์ตามมาตรา 1382 และถือเป็นการได้มาซึ่งอสังหาริมทรัพย์โดยทางอื่น นอกจากนิติกรรมตามมาตรา 1299 วรรคสอง ดังนั้นเมื่อไม่ได้จดทะเบียนการได้มาต่อพนักงาน เจ้าหน้าที่ เพลิงก็จะเปลี่ยนแปลงทางทะเบียนไม่ได้ และสิทธิอันยังไม่ได้จดทะเบียนนั้น มิให้ยกขึ้นต่อสู้ บุคคลภายนอกผู้ได้สิทธิมาโดยเสียค่าตอบแทนและโดยสุจริต และได้จดทะเบียนสิทธิโดยสุจริตแล้ว สำหรับกรณีที่น้ำฝนเจ้าของที่ดินถึงแก่ความตาย และน้ำผึ้งบุตรของน้ำฝนจดทะเบียนรับมรดกที่ดินแปลง ดังกล่าวมานั้น กรณีเช่นนี้ถือว่าน้ำผึ้งรับโอนที่ดินดังกล่าวในฐานะทายาทโดยธรรมของน้ำฝน อันเป็นการ\n\nรับทรัพย์มรดกตามกฎหมายว่าด้วยมรดก ซึ่งทายาทต้องรับไปทั้งสิทธิและตลอดจนความรับผิดต่างๆของ เจ้ามรดก ทั้งถือไม่ได้ว่าน้ำผึ้งเป็นบุคคลภายนอกที่ได้กรรมสิทธิ์ที่ดินโดยมีค่าตอบแทน ดังนั้น ระหว่าง เพลิงกับน้ำผึ้ง เพลิงจึงมีกรรมสิทธิ์ในที่ดินดังกล่าวดีกว่าน้ำผึ้ง (ฎ. 1886/2536 ฎ. 1069 – 1070/2522) ประเด็นที่ต้องวินิจฉัยประการแรกมีว่า ระหว่างเปลวและเพลิง ใครมีกรรมสิทธิ์ในที่ดินแปลงนี้ดีกว่า กัน เห็นว่า ขณะที่เพลิงยังไม่ได้ดำเนินการเปลี่ยนชื่อในโฉนดเป็นชื่อของตน น้ำผึ้งซึ่งไม่มีสิทธิดีกว่าเพลิง ได้จดทะเบียนขายที่ดินแปลงที่ตกเป็นกรรมสิทธิ์แก่เพลิงแล้วให้เปลว โดยก่อนจดทะเบียนโอน กรรมสิทธิ์ เปลวได้ไปดูที่ดินแต่ไม่เห็นผู้ใดครอบครองที่ดินดังกล่าว แต่หลังจากน้ำผึ้งจดทะเบียนโอน กรรมสิทธิ์ที่ดินให้เปลวแล้ว เปลวจึงรู้ว่าเพลิงครอบครองปรปักษ์ที่ดินแปลงนั้น กรณีเช่นนี้ถือว่าเปลวเป็น บุคคลภายนอกซื้อที่ดินมาโดยสุจริต เสียค่าตอบแทนและจดทะเบียนสิทธิโดยสุจริต จึงได้รับความคุ้มครอง ตามมาตรา 1299 วรรคสอง ซึ่งเป็นบทยกเว้นหลักทั่วไปที่ว่า ผู้รับโอนไม่มีสิทธิดีกว่าผู้โอน ดังนั้นแม้ เปลวจะรับโอนมาจากน้ำผึ้งผู้ที่ไม่มีสิทธิในที่ดินดีกว่าเพลิง เปลวก็ยังมีสิทธิดีกว่าเพลิง เพลิงจะอ้างหลัก ผู้รับโอนไม่มีสิทธิดีกว่าผู้โอนมาใช้ยันเปลวไม่ได้ ประเด็นที่ต้องวินิจฉัยประการต่อมามีว่า เพลิงจะยื่นคำร้องขอให้ศาลมีคำสั่งเพิกถอนการจดทะเบียนโอน กรรมสิทธิ์ที่ดินระหว่างน้ำผึ้งกับเปลวได้หรือไม่ เห็นว่า แม้เพลิงจะเป็นผู้อยู่ในฐานะอันจะให้จดทะเบียน สิทธิของตนได้อยู่ก่อนตามมาตรา 1300 และการจดทะเบียนโอนกรรมสิทธิ์ระหว่างน้ำผึ้งกับเปลวจะทำให้ เพลิงเสียเปรียบก็ตาม เพลิงก็ไม่สามารถยื่นคำร้องขอให้ศาลมีคำสั่งเพิกถอนการจดทะเบียนดังกล่าว เพราะ การจดทะเบียนรับโอนกรรมสิทธิ์ของเปลวนั้นมีค่าตอบแทนและเป็นการจดทะเบียนโดย สุจริต (ฎ. 32/2490)","conclusion":"สรุป เปลวเป็นผู้มีกรรมสิทธิ์ในที่ดินดีกว่าเพลิง และเพลิงจะยื่นคำร้องขอให้ศาลมีคำสั่งเพิกถอน การจดทะเบียนโอนกรรมสิทธิ์ระหว่างน้ำผึ้งกับเปลวไม่ได้","otherSections":["1300"]},{"id":"archive-2552-1-3-61","year":"2552","semester":"ภาค 1","number":3,"page":61,"course":"LAW2001 (LA 201 / LW 204)","title":"ปี 2552 ภาค 1 · ข้อ 3","sections":["1367","1375"],"kind":"old-exam-source","source":"แนวข้อสอบเก่าวิชาทรัพย์สิน.pdf","question":"ข้อ 3 ใสได้ตกลงขอทำถนนผ่านที่ดินของแสงซึ่งเป็นที่ดินมือเปล่า แต่ก็ยังไม่ถึงทางสาธารณะ ใสจะต้อง ทำถนนผ่านที่ดินของเสียงอีกแปลงหนึ่งซึ่งเป็นที่ดินเปล่าจึงจะถึงทางสาธารณะได้ แต่ใสไม่สามารถติดต่อ เสียงได้จึงได้ทำถนนผ่านที่ดินของเสียงไปโดยพลการ และนอกจากนั้นเมื่อเห็นที่ดินของเสียงทิ้งร้างไว้ ใส จึงยังใช้ที่ดินของเสียงทั้งแปลงทำไร่ข้าวโพด ใสใช้ทางผ่านที่ดินของทั้งแสงและเสียงและทำไร่ข้าวโพดบน ที่ดินของเสียงผ่านมาได้ห้าปี\n\nถ้าเสียงฟ้องเรียกคืนและห้ามไม่ให้ใสเข้ามายุ่งเกี่ยวในที่ดินของตน ใสจะมีข้อต่อสู้เสียงได้อย่างไร บ้าง เพราะเหตุใด","rule":"มาตรา 1367 บุคคลใดยึดถือทรัพย์สินโดยเจตนาจะยึดถือเพื่อตน ท่านว่าบุคคลนั้นได้ซึ่งสิทธิ ครอบครอง\n\nมาตรา 1375 ถ้าผู้ครอบครองถูกแย่งการครอบครองโดยมิชอบด้วยกฎหมายไซร้ ท่านว่าผู้ ครอบครองมีสิทธิจะได้คืนซึ่งการครอบครอง เว้นแต่อีกฝ่ายหนึ่งมีสิทธิเหนือทรัพย์สินดีกว่า ซึ่งจะเป็นเหตุ ให้เรียกคืนจากผู้ครอบครองได้ การฟ้องคดีเพื่อเอาคืนซึ่งการครอบครองนั้น ท่านว่าต้องฟ้องภายในปีหนึ่งนับแต่เวลาถูกแย่งการ ครอบครอง","application":"กรณีตามอุทาหรณ์ ประเด็นที่ต้องวินิจฉัยมีว่า ถ้าเสียงฟ้องเรียกคืนและห้ามไม่ให้ใสเข้ามายุ่งเกี่ยวในที่ดิน ของตน ใสจะมีข้อต่อสู้เสียงได้อย่างไรบ้าง เห็นว่า การที่ใสได้ตกลงขอทำถนนผ่านที่ดินของแสง ซึ่งเป็น ที่ดินมือเปล่า แต่ก็ยังไม่ถึงทางสาธารณะ ใสจะต้องทำถนนผ่านที่ดินของเสียงอีกแปลงหนึ่งซึ่งเป็นที่ดินมือ เปล่าจึงจะถึงทางสาธารณะได้ แต่ใสไม่สามารถติดต่อเสียงได้จึงได้ทำถนนผ่านที่ดินของเสียงไปโดย พลการ นอกจากนั้นเมื่อเห็นที่ดินของเสียงทิ้งร้างไว้ ใสจึงยังใช้ที่ดินของเสียงทั้งแปลงทำไร่ข้าวโพด อัน เป็นการยึดถือทำประโยชน์ในทรัพย์สิน กรณีเช่นนี้ถือว่าใสได้เข้ายึดถือทรัพย์สินโดยเจตนาจะยึดถือเพื่อตน แล้ว ใสจึงได้สิทธิครอบครองในที่ดินมือเปล่าของเสียงทั้งแปลงตามมาตรา 1367 และกรณีนี้ยังถือว่าใสได้ แย่งการครอบครองมือเปล่าของเสียงด้วยตามมาตรา 1375 วรรคแรก เมื่อเสียงผู้ครอบครองถูกใสแย่งการครอบครองโดยมิชอบด้วยกฎหมาย กฎหมายให้สิทธิเสียงฟ้องเรียกคืน ซึ่งการครอบครองได้ภายใน 1 ปี นับแต่เวลาถูกแย่งการครอบครอง โดยไม่คำนึงว่าผู้ครอบครองจะทราบ ว่าถูกแย่งการครอบครองหรือไม่ และไม่คำนึงถึงว่าผู้ครอบครองได้โต้แย้งผู้แย่งหารครอบครองหรือได้ ร้องเรียนต่อพนักงานฝ่ายปกครองว่าถูกแย่งการครอบครองหรือไม่ (ฎ. 6412/2550 ฎ. 108/2517) เมื่อ ข้อเท็จจริงคดีนี้ปรากฏว่าใสได้ใช้ทางผ่านที่ดินมือเปล่าทั้งของแสงและเสียงและทำไร่ข้าวโพดบนที่ดินของ เสียงผ่านมาได้ 5 ปี เสียงจึงหมดสิทธิฟ้องเรียกคืนการครอบครองแล้วตามมาตรา 1375 วรรคสอง ถ้า\n\nเสียงฟ้องเรียกคืนซึ่งการครอบครองและห้ามมิให้ใสเข้ามายุ่งเกี่ยวในที่ดินของตน ใสย่อมสามารถยกข้อ ต่อสู้ได้ว่าเสียงหมดสิทธิเรียกคืนซึ่งการครอบครองแล้ว และตนได้สิทธิครอบครองในที่ดินของเสียงแล้ว","conclusion":"สรุป ใสสามารถยกข้อต่อสู้ได้ว่าเสียงหมดสิทธิเรียกคืนซึ่งการครอบครองตามมาตรา 1375 และ ตนได้สิทธิครอบครองในที่ดินของเสียงแล้ว","otherSections":[]},{"id":"archive-2552-1-4-62","year":"2552","semester":"ภาค 1","number":4,"page":62,"course":"LAW2001 (LA 201 / LW 204)","title":"ปี 2552 ภาค 1 · ข้อ 4","sections":["1368","1382"],"kind":"old-exam-source","source":"แนวข้อสอบเก่าวิชาทรัพย์สิน.pdf","question":"ข้อ 4 นายฟ้าครอบครองปรปักษ์ทำนาบนที่ดินมีโฉนดแปลงหนึ่งของเหลืองมาเข้าปีที่แปด นายฟ้าประสบ อุบัติเหตุ ต้องรักษาตัวอยู่ที่โรงพยาบาล นายฟ้าทราบว่าแม้ออกจากโรงพยาบาลแล้วร่างกายตนคงทำนา ไม่ได้อีกแล้ว ขณะรักษาตัวอยู่ในโรงพยาบาลได้ 6 เดือน ได้ยกที่ดินแปลงนั้นให้บุตรชายทำนาต่อจาก ตน บุตรชายนายฟ้าจึงเข้าไปครอบครองที่ดินแปลงนั้น และเอาที่ดินแปลงนั้นไปให้นายแดงเช่าแทน นาย แดงนำที่ดินแปลงนั้นไปปลูกยางพารา แดงเช่าที่ดินแปลงนั้นมาได้สามปี เหลืองได้ฟ้องคดีต่อศาลขับไล่ให้ แดงและบุตรชายนายฟ้าออกจากที่ดินแปลงนั้น\n\nตามหลักกฎหมายแพ่งและพาณิชย์ บุตรชายนายฟ้าได้กรรมสิทธิ์โดยการครอบครองปรปักษ์ใน ที่ดินแปลงนั้นแล้วหรือยัง เพราะเหตุใด","rule":"มาตรา 1368 บุคคลอาจได้มาซึ่งสิทธิครอบครองโดยผู้อื่นยึดถือไว้ให้\n\nมาตรา 1382 บุคคลใดครอบครองทรัพย์สินของผู้อื่นไว้โดยความสงบและโดยเปิดเผยด้วยเจตนา เป็นเจ้าของ ถ้าเป็นอสังหาริมทรัพย์ได้ครอบครองติดต่อกันเป็นเวลาสิบปี ถ้าเป็นสังหาริมทรัพย์ได้ ครอบครองติดต่อกันเป็นเวลาห้าปีไซร้ ท่านว่าบุคคลนั้นได้กรรมสิทธิ์\n\nมาตรา 1384 “ถ้าผู้ครอบครองขาดยึดถือทรัพย์สินโดยไม่สมัคร และได้คืนภายในเวลาปีหนึ่ง นับตั้งแต่วันขาดยึดถือ หรือได้คืนโดยฟ้องคดีภายในกำหนดนั้นไซร้ ท่านมิให้ถือว่าการครอบครองสะดุด หยุดลง”\n\nมาตรา 1385 ถ้าโอนการครอบครองแก่กัน ผู้รับโอนจะนับเวลาซึ่งผู้โอนครอบครองอยู่ก่อนนั้น รวมเข้ากับเวลาครอบครองของตนก็ได้ ถ้าผู้รับโอนนับรวมเช่นนั้น และถ้ามีข้อบกพร่องในระหว่าง ครอบครองของผู้โอนไซร้ ท่านว่าข้อบกพร่องนั้นอาจยกขึ้นเป็นข้อต่อสู้ผู้รับโอนได้","application":"โดยหลักแล้ว การได้กรรมสิทธิ์ในอสังหาริมทรัพย์โดยการครอบครองปรปักษ์ตามมาตรา 1382 จะต้อง ประกอบด้วยหลักเกณฑ์ดังนี้ คือ 1 เป็นทรัพย์สินของผู้อื่นโดยผู้อื่นมีกรรมสิทธิ์ 2 ได้ครอบครองโดยความสงบ 3 ครอบครองโดยเปิดเผย 4 ครอบครองโดยเจตนาเป็นเจ้าของ\n\n5 ครอบครองติดต่อกันมาเป็นเวลา 10 ปี สำหรับการครอบครองติดต่อกันนั้น จะต้องเป็นกรณีที่ผู้ครอบครอง ไม่มีเจตนาสละการครอบครอง หรือ ขาดการยึดถือโดยสมัครใจ และนับระยะเวลาครอบครองติดต่อกันได้ หากเป็นเพียงการขาดการยึดถือโดย ไม่สมัคร เพราะมีเหตุมาขัดขวางโดยไม่สมัครใจ กฎหมายถือว่าการขาดการยึดถือนั้นไม่ทำให้ขาดอายุ ความ การครอบครองสะดุดหยุดลง หากได้ทรัพย์สินคืนภายใน 1 ปี นับแต่วันที่ขาดการยึดถือ ทั้งนี้ตาม มาตรา 1384 กรณีตามอุทาหรณ์ ประเด็นที่ต้องวินิจฉัยมีว่า บุตรชายนายฟ้าได้กรรมสิทธิ์โดยการครอบครองปรปักษ์ใน ที่ดินแปลงนั้นหรือยัง เห็นว่า นายฟ้าได้ครอบครองปรปักษ์ทำนาบนที่ดินมีโฉนดแปลงหนึ่งของเหลืองมา เข้าปีที่ 8 นายฟ้าประสบอุบัติเหตุต้องรักษาตัวอยู่โรงพยาบาล กรณีนี้ถือว่านายฟ้าขาดการยึดถือโดยไม่ สมัครใจเนื่องจากมีเหตุมาขัดขวางหรือไม่มีเจตนาสละการครอบครอง เมื่อนายฟ้าเห็นว่าทำนาต่อไปอีก ไม่ได้ จึงยกที่ดินแปลงนั้นให้บุตรชายทำนาต่อจากตนในขณะที่รักษาตัวอยู่ในโรงพยาบาล ได้ 6 เดือน ดังนี้ถือว่าการขาดการยึดถือนั้นไม่ทำให้อายุความสะดุดหยุดลง เนื่องจากได้ทรัพย์สินคืนมา ภายใน 1 ปี นับแต่วันที่ขาดการยึดถือ โดยมีบุตรชายนายฟ้าเข้ายึดถือแทนตามมาตรา 1384 และในกรณี เช่นนี้บุตรชายนายฟ้าผู้รับโอนการครอบครองโดยนิติกรรมสามารถนับเวลาซึ่งนายฟ้าผู้โอนครอบครองอยู่ ก่อนนั้นรวมเข้ากับเวลาครอบครองของตนก็ได้ ตามมาตรา 1385 อนึ่ง การที่บุตรชายของนายฟ้ากลับเอาที่ดินแปลงนั้นไปให้นายแดงเช่าแทน นายแดงย่อมอยู่ในฐานะเป็นผู้ ยึดถือที่ดินแปลงนั้นแทนบุตรชายนายฟ้าตลอดมาตามมาตรา 1368 (ฎ. 1054/2519 ฎ. 1623/2522) เมื่อแดง เช่าที่ดินแปลงนั้นมาได้ 3 ปี รวมกับเวลาที่นายฟ้าครอบครองมาแต่ก่อนและที่กฎหมายถือว่าไม่สะดุดหยุด ลงอีก 8 ปี 6 เดือน รวมเป็น 11 ปี 6 เดือน ตามหลักกฎหมายแพ่งและพาณิชย์ บุตรชายนายฟ้าย่อมได้ กรรมสิทธิ์ในที่ดินแปลงนั้นโดยการครอบครองปรปักษ์ตามมาตรา 1382 แล้ว","conclusion":"สรุป บุตรชายนายฟ้าได้กรรมสิทธิ์โดยการครอบครองปรปักษ์แล้ว","otherSections":["1384","1385"]},{"id":"archive-2551-s-1-64","year":"2551","semester":"ภาคฤดูร้อน","number":1,"page":64,"course":"LAW2001 (LA 201 / LW 204)","title":"ปี 2551 ภาคฤดูร้อน · ข้อ 1","sections":["144"],"kind":"old-exam-source","source":"แนวข้อสอบเก่าวิชาทรัพย์สิน.pdf","question":"ข้อ 1 แห้วอนุญาตด้วยวาจาให้หอมอาศัยอยู่ในบ้านของตนไม่ได้กำหนดระยะเวลาไว้ หลังจากที่หอมเข้า ไปอยู่ในบ้านหลังนั้นได้ 1 ปี เกิดพายุพัดหลังคาบ้านเสียหาย หอมจึงซ่อมแซมหลังคาบ้านใหม่และติดตั้ง จานรับสัญญาณดาวเทียมบนระเบียงบ้านด้วย ต่อมาแห้วได้ทำสัญญาและจดทะเบียนขายบ้านและที่ดินให้ แป้ง แป้งจึงแจ้งให้หอมย้ายออกไปจากบ้านหลังดังกล่าว\n\nดังนี้ หอมจะรื้อจานรับสัญญาณดาวเทียมออกไปและเรียกให้แป้งจ่ายเงินค่าซ่อมแซมหลังคาบ้าน ให้กับตนได้หรือไม่ เพราะเหตุใด","rule":"มาตรา 144 ส่วนควบของทรัพย์ หมายความว่า ส่วนซึ่งโดยสภาพแห่งทรัพย์หรือโดยจารีต ประเพณีแห่งท้องถิ่นเป็นสาระสำคัญในความเป็นอยู่ของทรัพย์นั้น และไม่อาจแยกจากกันได้นอกจากจะ ทำลาย ทำให้บุบสลาย หรือทำให้ทรัพย์นั้นเปลี่ยนแปลงรูปทรงหรือสภาพไป เจ้าของทรัพย์ย่อมมีกรรมสิทธิ์ในส่วนควบของทรัพย์นั้น","application":"ส่วนควบ คือ ส่วนซึ่งโดยสภาพของทรัพย์สินหรือจารีตประเพณีแห่งท้องถิ่นย่อมเป็นสาระสำคัญในความ เป็นอยู่ของทรัพย์นั้น และไม่อาจแบ่งแยกจากกันได้ นอกจากจะทำลาย ทำให้บุบสลายหรือทำให้ทรัพย์นั้น เปลี่ยนแปลงรูปทรง ซึ่งผู้เป็นเจ้าของตัวทรัพย์ย่อมเป็นเจ้าของส่วนควบนั้นด้วย ในทางกลับกันถ้าทรัพย์ ดังกล่าวไม่เป็นสาระสำคัญในความเป็นอยู่ของตัวทรัพย์ และสามารถแยกออกจากกันได้โดยไม่ทำให้ทรัพย์ นั้นถูกทำลายหรือบุบสลายหรือเปลี่ยนแปลงรูปทรง กรณีเช่นนี้ ย่อมไม่เป็นส่วนควบและผู้เป็นเจ้าของ ทรัพย์ก็ไม่เป็นเจ้าของทรัพย์นั้น กรณีตามอุทาหรณ์ การที่หอมซ่อมแซมหลังคาบ้านซึ่งเกิดพายุพัดหลังคาเสียหาย ซึ่งโดยหลักแล้วหลังคา บ้านย่อมถือว่าเป็นสาระสำคัญในความเป็นอยู่ของตัวบ้าน และไม่สามารถแยกออกจากตัวบ้านได้นอกจาก จะทำลาย ทำให้บุบสลายหรือทำให้ทรัพย์นั้นเปลี่ยนแปลงรูปทรงไป เมื่อได้ความว่า หอมซ่อมแซมหลังคา บ้านไปโดยมิได้รับความยินยอมจากแห้วเจ้าของบ้าน กรณีเช่นนี้ หลังคาบ้านจึงตกเป็นส่วนควบของบ้าน ตามมาตรา 144 วรรคแรก ดังนั้น หลังคาบ้านจึงตกเป็นกรรมสิทธิ์ของแห้วเจ้าของบ้านตาม มาตรา 144 วรรคสอง และเมื่อแห้วได้ทำสัญญาและจดทะเบียนขายบ้านและที่ดินให้แป้ง กรรมสิทธิ์ใน บ้านพร้อมทั้งส่วนควบของบ้านจึงตกเป็นของแป้งผู้รับโอน\n\nสำหรับค่าใช้จ่ายในการซ่อมแซมบ้านนั้น เมื่อหอมซ่อมแซมบ้านดังกล่าวโดยมิได้รับความยินยอมจากแห้ว เจ้าของบ้านทั้งหลังคาบ้านที่ซ่อมก็ได้ตกเป็นส่วนควบของตัวบ้าน อันเป็นกรรมสิทธิ์ของแป้งเจ้าของบ้าน ผู้รับโอน นายหอมจึงไม่สามารถเรียกให้แป้งจ่ายค่าซ่อมแซมหลังคาบ้านได้แต่ประการใด ส่วนจานรับ สัญญาณดาวเทียมที่หอมนำมาติดตั้งที่ระเบียงบ้าน หอมจะรื้อออกไปได้หรือไม่นั้น เห็นว่า จานรับ สัญญาณดาวเทียมโดยหลักแล้วย่อมไม่เป็นสาระสำคัญในความเป็นอยู่ของตัวบ้าน และหากหอมจะรื้อไปก็ ไม่ทำให้บ้านถูกทำลายหรือบุบสลายหรือเปลี่ยนแปลงรูปทรงแต่ประการใด ดังนั้น จานรับสัญญาณ ดาวเทียมจึงไม่ถือเป็นส่วนควบของบ้านยังคงเป็นกรรมสิทธิ์ของนายหอมอยู่ หอมจึงสามารถรื้อออกไปได้","conclusion":"สรุป หอมสามารถรื้อจานรับสัญญาณดาวเทียมออกไปได้ แต่หอมไม่สามารถเรียกให้แป้งจ่ายเงิน ค่าซ่อมแซมหลังคาบ้านให้กับตนได้","otherSections":[]},{"id":"archive-2551-s-2-65","year":"2551","semester":"ภาคฤดูร้อน","number":2,"page":65,"course":"LAW2001 (LA 201 / LW 204)","title":"ปี 2551 ภาคฤดูร้อน · ข้อ 2","sections":["1299"],"kind":"old-exam-source","source":"แนวข้อสอบเก่าวิชาทรัพย์สิน.pdf","question":"ข้อ 2 สำราญกับสำรวยทำสัญญาประนีประนอมยอมความกัน โดยสำราญตกลงยกบ้านและที่ดินมีโฉนด ให้สำรวยแทนการชำระหนี้และศาลได้มีคำสั่งพิพากษาตามยอมแล้ว แต่ทั้งสองยังไม่ได้จดทะเบียนโอน กรรมสิทธิ์ให้แก่กัน หลังจากนั้น 1 ปี สำราญถึงแก่ความตาย สำเริงบุตรชายของสำราญได้จดทะเบียนรับ มรดกบ้านและที่ดินดังกล่าว ทั้งที่รู้ข้อเท็จจริงเรื่องทำสัญญาประนีประนอมระหว่างสำราญกับสำรวย\n\nดังนี้ ให้วินิจฉัยว่า สำรวยจะขอให้เพิกถอนการจดทะเบียนรับมรดกของสำเริงได้หรือไม่ เพราะ เหตุใด","rule":"มาตรา 1299 วรรคแรก ภายในบังคับแห่งบทบัญญัติในประมวลกฎหมายนี้หรือกฎหมายอื่น ท่าน ว่า การได้มาโดยนิติกรรมซึ่งอสังหาริมทรัพย์หรือทรัพยสิทธิอันเกี่ยวกับอสังหาริมทรัพย์นั้นไม่ บริบูรณ์ เว้นแต่นิติกรรมจะได้ทำเป็นหนังสือและได้จดทะเบียนการได้มากับพนักงานเจ้าหน้าที่\n\nมาตรา 1300 ถ้าได้จดทะเบียนการโอนอสังหาริมทรัพย์ หรือทรัพยสิทธิอันเกี่ยวกับ อสังหาริมทรัพย์ เป็นทางเสียเปรียบแก่บุคคลผู้อยู่ในฐานะอันจะให้จดทะเบียนสิทธิของตนได้อยู่ก่อน ไซร้ ท่านว่าบุคคลนั้นอาจเรียกให้เพิกถอนการจดทะเบียนนั้นได้ แต่การโอนอันมีค่าตอบแทน ซึ่งผู้รับโอนกระทำการโดยสุจริตนั้น ไม่ว่ากรณีจะเป็นประการใด ท่านว่าจะ เรียกให้เพิกถอนทะเบียนไม่ได้","application":"การได้อสังหาริมทรัพย์หรือทรัพยสิทธิเกี่ยวกับอสังหาริมทรัพย์โดยนิติกรรมไม่บริบูรณ์ เว้นแต่นิติกรรมนั้น จะได้ทำเป็นหนังสือและจดทะเบียนการได้มากับพนักงานเจ้าหน้าที่ ซึ่งคำว่า “ไม่บริบูรณ์” ตาม มาตรา 1299 วรรคแรกนี้ หมายถึงไม่บริบูรณ์ในฐานะทรัพยสิทธิ กล่าวคือ ไม่อาจใช้ยันต่อบุคคลทั่วไป ได้ แต่ยังคงมีผลบังคับกันได้ในระหว่างคู่กรณีในฐานะบุคคลสิทธิ\n\nกรณีตามอุทาหรณ์ การที่สำราญทำสัญญาประนีประนอมยอมความยกบ้านและที่ดินที่มีโฉนดให้สำรวย แทนการชำระหนี้และศาลมีคำพิพากษาตามยอม กรณีเช่นนี้ ถือว่าสำรวยเป็นผู้ได้มาซึ่งอสังหาริมทรัพย์โดย ทางนิติกรรม (คือการทำสัญญาประนีประนอมยอมความ) แต่เนื่องจากบุคคลทั้งสองยังไม่ได้จดทะเบียน โอนกรรมสิทธิ์ให้แก่กัน นิติกรรมดังกล่าวจึงไม่บริบูรณ์ในฐานะทรัพยสิทธิ แต่ยังคงมีผลใช้ได้ระหว่าง คู่สัญญาคือ สำราญกับสำรวยในฐานะบุคคลสิทธิตามมาตรา 1299 วรรคแรก (ฎ.9936/2539) หลังจากนั้น 1 ปี สำราญได้ถึงแก่ความตาย สำเริงบุตรของสำราญได้จดทะเบียนรับมรดกบ้านและที่ดิน ดังกล่าว ทั้งที่รู้ข้อเท็จจริงเรื่องสัญญาประนีประนอมยอมความระหว่างสำรวยกับสำราญ ปัญหาที่ต้อง วินิจฉัยจึงมีว่า สำรวจจะขอให้เพิกถอนการจดทะเบียนรับมรดกของสำเริงได้หรือไม่ เห็นว่า สำเริง นอกจากมิใช่บุคคลภายนอกที่ได้กรรมสิทธิ์ในอสังหาริมทรัพย์โดยมีค่าตอบแทนแล้ว สำเริงยังเป็นผู้ได้ กรรมสิทธิ์โดยไม่สุจริตอีกด้วย ดังนั้นสำรวยจึงมีกรรมสิทธิ์ในบ้านและที่ดินดีกว่าสำเริง เมื่อสำรวยเป็นผู้ อยู่ในฐานะอันจะให้จดทะเบียนสิทธิของตนได้ก่อน และการจดทะเบียนรับมรดกของสำเริงทำให้สำรวย เสียเปรียบ สำรวยจึงขอให้เพิกถอนการจดทะเบียนรับมรดกของสำเริงได้ตามมาตรา 1300 (ฎ. 6655/2542)","conclusion":"สรุป สำรวยขอให้เพิกถอนการจดทะเบียนรับมรดกของสำเริงได้ หมายเหตุ ผลของการทำสัญญาประนีประนอมยอมความในศาลนั้นเป็นเรื่องเจตนาของคู่กรณี ซึ่งศาล พิพากษาไปตามนั้น ยังไม่ถือว่าเป็นการได้ทรัพยสิทธิมาโดยคำพิพากษา ศาลเพียงแต่ถือว่าผู้นั้นอยู่ในฐานะ ที่จะจดทะเบียนสิทธิของตนดีกว่าผู้อื่นตามมาตรา 1300 จึงไม่เป็นการได้มาโดยทางอื่นนอกจากนิติกรรม ตามมาตรา 1299 วรรคสอง","otherSections":["1300"]},{"id":"archive-2551-s-3-66","year":"2551","semester":"ภาคฤดูร้อน","number":3,"page":66,"course":"LAW2001 (LA 201 / LW 204)","title":"ปี 2551 ภาคฤดูร้อน · ข้อ 3","sections":["1375"],"kind":"old-exam-source","source":"แนวข้อสอบเก่าวิชาทรัพย์สิน.pdf","question":"ข้อ 3 ต้นทำสัญญาขายฝากบ้านและที่ดิน มี น.ส.3 ของตนให้กับตั้มมีกำหนดเวลา 1 ปี เมื่อครบ กำหนดเวลาตามสัญญาขายฝากแล้ว ต้นไม่นำเงินไปไถ่ถอน แต่ต้นไม่มีที่อยู่อาศัย ตั้มจึงอนุญาตให้ต้นอยู่ อาศัยต่อไปโดยไม่คิดค่าเช่า หลังจากนั้นอีก 1 ปี ต้นถึงแก่ความตาย ตาลบุตรของต้นได้อาศัยอยู่ในบ้าน และที่ดินนั้นต่อจากต้น ต่อมาอีก 6 เดือน ตั้มได้บอกให้ตาลย้ายออกไปจากบ้านและที่ดินของตน มิฉะนั้น ให้ตาลทำสัญญาเช่ากับตน แต่ตาลไม่ยอมทำสัญญาเช่าโดยอ้างว่าตนเป็นผู้รับมรดกบ้านและที่ดินมาจากต้น บิดาของตน และตาลยังคงอาศัยอยู่ในบ้านและที่ดินพิพาท ต่อมาอีก 7 เดือนตั้งจึงมาปรึกษาท่านว่า ต้องการจะฟ้องขับไล่และเรียกที่ดินคืนจากตาล\n\nดังนี้ ให้ท่านวินิจฉัยว่าตั้งจะฟ้องขับไล่ตาลและเรียกที่ดินคืนได้หรือไม่ เพราะเหตุใด","rule":"มาตรา 1375 ถ้าผู้ครอบครองถูกแย่งการครอบครองโดยมิชอบด้วยกฎหมายไซร้ ท่านว่าผู้ ครอบครองมีสิทธิจะได้คืนซึ่งการครอบครอง เว้นแต่อีกฝ่ายหนึ่งมีสิทธิเหนือทรัพย์สินดีกว่า ซึ่งจะเป็นเหตุ ให้เรียกคืนจากผู้ครอบครองได้\n\nการฟ้องคดีเพื่อเอาคืนซึ่งการครอบครองนั้น ท่านว่าต้องฟ้องภายในหนึ่งปีนับแต่เวลาถูกแย่งการ ครอบครอง\n\nมาตรา 1381 บุคคลใดยึดถือทรัพย์สินอยู่ในฐานะเป็นผู้แทนผู้ครอบครอง บุคคลนั้นจะเปลี่ยน ลักษณะแห่งการยึดถือได้ ก็แต่โดยบอกกล่าวไปยังผู้ครอบครองว่า ไม่เจตนาจะยึดถือทรัพย์สินแทนผู้ ครอบครองต่อไป หรือตนเองเป็นผู้ครอบครองโดยสุจริต อาศัยอำนาจใหม่อันได้จากบุคคลภายนอก","application":"โดยหลักแล้ว ถ้าผู้ครอบครองถูกแย่งการครอบครองโดยมิชอบด้วยกฎหมาย ย่อมมีสิทธิฟ้องเรียกคืนซึ่งการ ครอบครองได้ภายในเวลา 1 ปี นับแต่เวลาถูกแย่งการครอบครอง กรณีตามอุทาหรณ์ ประเด็นที่ต้องวินิจฉัยมีว่า ตั้มจะฟ้องขับไล่ตาลและเรียกที่ดินคืนได้หรือไม่ เห็นว่า ต้น ทำสัญญาขายฝากบ้านและที่ดินมี น.ส.3 ของตนให้กับตั้มมีกำหนดเวลา 1 ปี เมื่อครบกำหนดเวลาตาม สัญญาขายฝากแล้วต้นไม่นำเงินไปไถ่ถอน กรณีเช่นนี้ตั้มจึงเป็นผู้มีสิทธิครอบครองเหนือบ้านและ ที่ดิน น.ส.3 ดังกล่าว ส่วนการที่ตั้มอนุญาตให้ต้นอยู่อาศัยต่อไปโดยไม่คิดค่าเช่า ก็ไม่ทำให้ต้นเป็นผู้มีสิทธิ ครอบครองเหนือบ้านและที่ดินแต่อย่างใด ต้นจึงเป็นเพียงผู้ครอบครองแทนตั้มเท่านั้น และหลังจากที่ต้น ถึงแก่ความตาย ตาลบุตรของต้นอาศัยอยู่ในบ้านและที่ดินต่อจากบิดา ซึ่งเป็นเพียงการครอบครองแทนตั้ม เช่นกัน ต่อมาอีก 6 เดือน ตั้มให้ตาลย้ายออกไปจากบ้านและที่ดินของตน มิฉะนั้นให้ตาลทำสัญญากับตน แต่ตาลไม่ยอมทำสัญญาเช่าโอยอ้างว่าตาลรับมรดกมาจากต้นบิดาของตน กรณีเช่นนี้จึงถือว่าตาลได้เปลี่ยน เจตนาการครอบครองแทนตั้มมาเป็นการครอบครองเพื่อตน ในฐานะเป็นเจ้าของบ้านและที่ดินตาม มาตรา 1381 และถือว่าเป็นการแย่งการครอบครองโดยมิชอบด้วยกฎหมายตามมาตรา 1375 วรรคแรก (ฎ. 2065/2533) หลังจากการแย่งการครอบครองโดยการเปลี่ยนเจตนาตามมาตรา 1375 ประกอบมาตรา 1381 ได้ เพียง 7 เดือน ตั้งจึงสามารถฟ้องขับไล่และเรียกที่ดินคืนจากตาลได้ เพราะเมื่อผู้ครอบครองถูกแย่งการ ครอบครองโดยมิชอบด้วยกฎหมายแล้ว ก็ย่อมมีสิทธิฟ้องเรียกคืนซึ่งการครอบครองได้ภายใน เวลา 1 ปี นับแต่เวลาถูกแย่งการครอบครองตามมาตรา 1375 วรรคสอง","conclusion":"สรุป ตั้มสามารถฟ้องขับไล่และเรียกที่ดินคืนจากตาลได้","otherSections":["1381"]},{"id":"archive-2551-s-4-67","year":"2551","semester":"ภาคฤดูร้อน","number":4,"page":67,"course":"LAW2001 (LA 201 / LW 204)","title":"ปี 2551 ภาคฤดูร้อน · ข้อ 4","sections":["1382","1387","1401"],"kind":"old-exam-source","source":"แนวข้อสอบเก่าวิชาทรัพย์สิน.pdf","question":"ข้อ 4 นายวันเป็นเจ้าของบ้านและที่ดินมีโฉนดแปลงหนึ่ง ต่อมานายวันถึงแก่ความตาย นายเช้ากับนายเย็น เป็นผู้รับมรดกบ้านและที่ดินร่วมกันในฐานะทายาทโดยธรรม แต่นายเช้าเป็นผู้ครอบครองบ้านและที่ดินนั้น ต่อจากนายวันเพียงผู้เดียว หลังจากนั้นอีก 3 ปี นายเช้ากับนายเย็นแบ่งมรดกกันโดยจดทะเบียนแบ่งแยก โฉนดที่ดินเป็นสองแปลง นายเช้าเป็นเจ้าของกรรมสิทธิ์แปลงที่มีบ้านสร้างอยู่ ส่วนนายเย็นเป็นเจ้าของ ที่ดินแปลงที่สองซึ่งมีถนนที่นายเช้าใช้สัญจรไปมาตั้งแต่สมัยที่นายวันยังมีชีวิตอยู่ หลังจากจดทะเบียน แบ่งแยกกรรมสิทธิ์ที่ดินกันได้ 8 ปี นายเย็นถึงแก่ความตาย นางราตรีบุตรของเย็นได้จดทะเบียนรับมรดก ที่ดินของนายเย็น และล้อมรั้วห้ามไม่ให้ นายเช้าใช้ถนนผ่านที่ดินของตนอีกต่อไป เพราะที่ดินของนายเช้ามี\n\nทางออกสู่ทางสาธารณะอยู่แล้ว แต่นายเช้าเห็นว่าเส้นทางนั้นไม่สะดวก และต้องการใช้ถนนผ่านที่ดินของ นางราตรีต่อไป\n\nดังนี้ ให้วินิจฉัยว่า นายเช้าจะเรียกให้นางราตรีรื้อถอนรั้วออกไปเพื่อให้ตนสามารถใช้ถนน ดังกล่าวต่อไปได้หรือไม่ เพราะเหตุใด","rule":"มาตรา 1382 บุคคลใดครอบครองทรัพย์สินของผู้อื่นไว้โดยความสงบและโดยเปิดเผยด้วยเจตนา เป็นเจ้าของ ถ้าเป็นอสังหาริมทรัพย์ได้ครอบครองติดต่อกันเป็นเวลาสิบปี ถ้าเป็นสังหาริมทรัพย์ได้ ครอบครองติดต่อกันเป็นเวลาห้าปีไซร้ ท่านว่าบุคคลนั้นได้กรรมสิทธิ์\n\nมาตรา 1387 อสังหาริมทรัพย์อาจต้องตกอยู่ในภาระจำยอมอันเป็นเหตุให้เจ้าของต้องยอมรับกรรม บางอย่างซึ่งกระทบถึงทรัพย์สินของตน หรือต้องงดเว้นการใช้สิทธิบางอย่างอันมีอยู่ในกรรมสิทธิ์ทรัพย์สิน นั้นเพื่อประโยชน์แก่อสังหาริมทรัพย์อื่น\n\nมาตรา 1401 ภาระจำยอมอาจได้มาโดยอายุความ ท่านให้นำบทบัญญัติว่าด้วยอายุความได้สิทธิอัน กล่าวไว้ในลักษณะ 3 แห่งบรรพนี้มาใช้บังคับโดยอนุโลม","application":"โดยหลักแล้ว การได้ภาระจำยอมเหนือที่ดินแปลงหนึ่ง ตามมาตรา 1387 จะเกิดขึ้นได้ก็เพื่อประโยชน์แก่ ที่ดินแปลงอื่นหรืออสังหาริมทรัพย์อื่นเท่านั้น กล่าวคือ จะต้องมีที่ดิน 2 แปลง โดยที่ดินแปลงหนึ่งตกอยู่ ในภาระจำยอมของที่ดินอีกแปลงหนึ่ง กรณีตามอุทาหรณ์ ประเด็นที่ต้องวินิจฉัยมีว่า นายเช้าจะเรียกให้นางราตรีรื้อถอนรั้วออกไปเพื่อให้ตน สามารถใช้ถนนดังกล่าวต่อไปได้หรือไม่ เห็นว่า นายเช้ากับนายเย็นรับมรดกบ้านและที่ดินมีโฉนดร่วมกัน ในฐานะทายาทโดยธรรมของนายวัน เมื่อยังไม่มีการจดทะเบียนแบ่งแยกกรรมสิทธิ์กัน ทั้งนายเช้ากับนาย เย็นจึงเป็นเจ้าของรวมในบ้านและที่ดินดังกล่าว แม้นายเช้าจะครอบครองบ้านและที่ดินเพียงผู้เดียวเป็นเวลา ถึง 3 ปี ก็ถือเป็นการครอบครองแทนนายเย็นเจ้าของรวมอีกคนหนึ่งเท่านั้น ต่อมาเมื่อทั้งสองจดทะเบียนแบ่งแยกโฉนดที่ดินเป็นสัดส่วนกัน โดยนายเช้าเป็นเจ้าของกรรมสิทธิ์ที่ดิน แปลงที่บ้านนั้นปลูกสร้างอยู่ ส่วนนายเย็นเป็นเจ้าของที่ดินอีกแปลงหนึ่งซึ่งมีถนนที่นายเช้าใช้สัญจรไปมา ตั้งแต่สมัยที่นายวันยังมีชีวิตอยู่ ในกรณีนี้การได้ภาระจำยอมโดยอายุความในถนนภายในที่ดินที่แบ่งแยกไว้ นี้ต้องเริ่มนับแต่เมื่อได้แบ่งแยกที่ดินและโอนกรรมสิทธิ์กันแล้ว เพราะก่อนการแบ่งแยกคงมีที่ดินแปลง เดียว จึงไม่อาจจะนับรยะเวลาก่อนการแบ่งแยกโฉนดเป็นการเริ่มต้นอายุความการได้มาซึ่งภาระจำยอมเพื่อ ประโยชน์แก่ที่ดินได้ (ฎ. 1049/2513) สำหรับการได้ภาระจำยอมโดยอายุความนั้น มาตรา 1401 ให้นำบทบัญญัติว่าด้วยอายุความได้สิทธิดังกล่าว ในลักษณะ 3 แห่งบรรพนี้มาใช้บังคับโดยอนุโลม กล่าวคือ จะต้องเป็นกรณีที่เจ้าของสามยทรัพย์ได้ใช้ ประโยชน์ในที่ดินภารยทรัพย์นั้นโดยความสงบ และโดยเปิดเผย และด้วยเจตนาจะได้สิทธิภาระจำยอมใน\n\nที่ดินดังกล่าว ติดต่อกันเป็นเวลา 10 ปี ตามมาตรา 1382 ประกอบมาตรา 1401 เมื่อข้อเท็จจริงปรากฏว่า หลังจากจดทะเบียนแบ่งแยกกรรมสิทธิ์กันแล้ว นายเช้ายังคงใช้ถนนนั้นอยู่ต่อมาได้เพียง 8 ปี ซึ่งยังไม่ ถึง 10 ปี ตามมาตรา 1401 ประกอบมาตรา 1382 ถนนนั้นจึงยังไม่เป็นภาระจำยอมโดยอายุความ (ฎ. 1754/2505) เมื่อถนนไม่เป็นภาระจำยอม การที่นางราตรีบุตรของเย็นซึ่งรับมรดกที่ดินแปลงนั้นได้ล้อมรั้วห้ามไม่ให้นาย เช้าใช้ถนนผ่านที่ดินของตนต่อไป เพราะเห็นว่าที่ดินของนายเช้ามีทางออกสู่ทางสาธารณะอยู่แล้ว จึง สามารถกระทำได้ในฐานะเจ้าของอสังหาริมทรัพย์ ดังนั้นนายเช้าจะเรียกให้นางราตรีรื้อถอนรั้วออกไปโดย อ้างว่าทางสาธารณะนั้นไม่สะดวกเพื่อให้ตนสามารถใช้ถนนดังกล่าวต่อไปไม่ได้","conclusion":"สรุป นายเช้าเรียกให้นางราตรีรื้อถอนรั้วออกไปไม่ได้ เพราะถนนไม่เป็นภาระจำยอมโดยอายุ ความ","otherSections":[]},{"id":"archive-2551-2-1-70","year":"2551","semester":"ภาค 2","number":1,"page":70,"course":"LAW2001 (LA 201 / LW 204)","title":"ปี 2551 ภาค 2 · ข้อ 1","sections":["144","146","1299"],"kind":"old-exam-source","source":"แนวข้อสอบเก่าวิชาทรัพย์สิน.pdf","question":"ข้อ 1 เพชรทำสัญญาอนุญาตให้พลอยอาศัยอยู่ในบ้านของตนได้ตลอดชีวิตของพลอย แต่สัญญาดังกล่าว ไม่ได้จดทะเบียนกับพนักงานเจ้าหน้าที่ หลังจากที่พลอยอาศัยอยู่ในบ้านหลังนั้นได้ 15 ปี พลอยเห็นว่า บ้านชำรุดทรุดโทรมมาก จึงรื้อถอนบ้านเก่าและสร้างบ้านหลังใหม่ขึ้นแทนหลังเก่า โดยไม่ได้บอกกล่าว เพชรแต่อย่างใด ต่อมาอีก 5 ปี เพชรทำสัญญาและจดทะเบียนขายที่ดินแปลงนั้นพร้อมสิ่งปลูกสร้างบน ที่ดินให้กับมรกต และมรกตแจ้งให้พลอยย้ายออกไปจากที่ดินและบ้านหลังนั้น แต่พลอยอ้างว่าตนมีสิทธิ อาศัยในบ้านหลังนั้นตลอดชีวิตตามสัญญาที่เพชรทำไว้กับตน ส่วนบ้านตนเป็นผู้ออกเงินก่อสร้างจึงเป็น กรรมสิทธิ์ของตน เพชรไม่มีสิทธินำบ้านไปขายแต่อย่างใด\n\nดังนี้ ให้วินิจฉัยว่าพลอยจะอ้างสัญญาระหว่างเพชรกับพลอยขึ้นต่อสู้มรกตเพื่อไม่ต้องย้ายออกไป ได้หรือไม่ และระหว่างพลอยกับมรกตผู้ใดมีกรรมสิทธิ์ในบ้านพิพาทดีกว่ากัน เพราะเหตุใด","rule":"มาตรา 144 วรรคสอง เจ้าของทรัพย์ย่อมมีกรรมสิทธิ์ในส่วนควบของทรัพย์นั้น\n\nมาตรา 146 ทรัพย์ซึ่งติดกับที่ดินหรือติดกับโรงเรือนเพียงชั่วคราวไม่ถือว่าเป็นส่วนควบกับที่ดิน หรือโรงเรือนนั้น ความข้อนี้ให้ใช้บังคับแก่โรงเรือนหรือสิ่งปลูกสร้างอย่างอื่น ซึ่งผู้มีสิทธิในที่ดินของผู้อื่น ใช้สิทธินั้นปลูกสร้างไว้ในที่ดินนั้นด้วย\n\nมาตรา 1299 วรรคแรก ภายในบังคับแห่งบทบัญญัติในประมวลกฎหมายนี้หรือกฎหมายอื่น ท่าน ว่า การได้มาโดยนิติกรรมซึ่งอสังหาริมทรัพย์หรือทรัพยสิทธิอันเกี่ยวกับอสังหาริมทรัพย์นั้นไม่ บริบูรณ์ เว้นแต่นิติกรรมจะได้ทำเป็นหนังสือและได้จดทะเบียนการได้มากับพนักงานเจ้าหน้าที่","application":"กรณีตามอุทาหรณ์ ประเด็นที่ต้องวินิจฉัยประการแรกมีว่า พลอยจะอ้างสัญญาระหว่างเพชรกับพลอยขึ้น ต่อสู้มรกตเพื่อไม่ต้องย้ายออกได้หรือไม่ เห็นว่า โดยหลักแล้ว การได้อสังหาริมทรัพย์หรือทรัพยสิทธิอัน เกี่ยวกับอสังหาริมทรัพย์มาโดยนิติกรรม หากไม่มีกฎหมายบัญญัติถึงความสมบูรณ์ของการได้มาไว้ ก็ต้อง เป็นไปตามมาตรา 1299 วรรคแรก กล่าวคือ หากมิได้ทำนิติกรรมเป็นหนังสือและจดทะเบียนการได้มากับ พนักงานเจ้าหน้าที่ การได้มาซึ่งอสังหาริมทรัพย์หรือทรัพยสิทธิอันเกี่ยวกับอสังหาริมทรัพย์ ย่อมไม่ บริบูรณ์เป็นทรัพยสิทธิ ไม่อาจใช้ยันต่อบุคคลภายนอกได้\n\nคงบังคับกันได้ในระหว่างคู่กรณีในฐานะบุคคลสิทธิเท่านั้น กรณีนี้เมื่อพลอยเป็นผู้มีสิทธิอาศัยในบ้านของ เพชรตามสัญญาที่เพชรทำกับพลอย พลอยจึงเป็นผู้ที่ได้มาซึ่งทรัพย์อันเกี่ยวกับอสังหาริมทรัพย์โดยทางนิติ กรรม แต่เนื่องจากนิติกรรมดังกล่าว ไม่ได้จดทะเบียนกับพนักงานเจ้าหน้าที่ การได้มาซึ่งสิทธิอาศัยจึงไม่ บริบูรณ์ในฐานะทรัพยสิทธิ ทำให้ไม่สามารถยกขึ้นต่อสู้บุคคลภายนอกได้ตามมาตรา 1299 วรรค แรก กรณีเช่นนี้ พลอยจะอ้างสัญญาระหว่างเพชรกับพลอยซึ่งเป็นบุคคลสิทธิขึ้นต่อสู้มรกตบุคคลภายนอก ไม่ได้ (ฎ. 1752/2523) ประเด็นที่ต้องวินิจฉัยประการต่อมามีว่า ระหว่างพลอยกับมรกตผู้ใดมีกรรมสิทธิ์ในบ้านพิพาทดีกว่า กัน เห็นว่า การที่พลอยเห็นบ้านชำรุดทรุดโทรมมากจึงรื้อถอนบ้านเก่าและสร้างบ้านหลังใหม่ขึ้นแทนหลัง เก่าโดยไม่ได้บอกกล่าวเพชรแต่อย่างใด ซึ่งข้อเท็จจริงปรากฏบ้านที่สร้างขึ้นใหม่นี้มีลักษณะติดที่ดินเป็น การถาวร เพราะไม่ปรากฏว่าเป็นการปลูกสร้างเพียงชั่วคราวและจะรื้อถอนไป ทั้งพลอยก็ไม่มีสิทธิหรือ ได้รับอำนาจจากเพชรที่จะปลูกบ้านลงในที่ดินของเพชรแต่อย่างใด กรณีไม่เข้าข้อยกเว้นตาม มาตรา 146 ดังนั้น บ้านจึงเป็นส่วนควบของที่ดิน โดยที่ดินเป็นทรัพย์ประธาน เพชรเจ้าของที่ดินทรัพย์ ประธานจึงเป็นเจ้าของส่วนควบคือบ้านด้วยตามมาตรา 144 วรรคสอง (ฎ. 1516 – 1517/2529) หลังจากที่พลอยสร้างบ้านได้ 5 ปี เพชรได้ทำสัญญาและจดทะเบียนขายที่ดินแปลงนั้นพร้อมสิ่งปลูก สร้าง คือบ้านพิพาทให้กับมรกต เมื่อได้ความว่า เพชรเป็นเจ้าของส่วนควบคือบ้านด้วยย่อมมีสิทธิที่จะจด ทะเบียนขายบ้านพิพาทได้ ส่งผลทำให้มรกตผู้สืบสิทธิของเพชรเป็นผู้ที่มีกรรมสิทธิ์ในที่ดินและบ้านพิพาท ดีกว่าพลอย","conclusion":"สรุป พลอยจะอ้างสัญญาระหว่างเพชรกับพลอยขึ้นต่อสู้มรกตเพื่อไม่ต้องย้ายออกไม่ได้ และ ระหว่างพลอยกับมรกต มรกตเป็นผู้มีสิทธิในบ้านดีกว่า","otherSections":[]},{"id":"archive-2551-2-3-72","year":"2551","semester":"ภาค 2","number":3,"page":72,"course":"LAW2001 (LA 201 / LW 204)","title":"ปี 2551 ภาค 2 · ข้อ 3","sections":["1377","1382","1387","1401","1368"],"kind":"old-exam-source","source":"แนวข้อสอบเก่าวิชาทรัพย์สิน.pdf","question":"ข้อ 3 นายจิตเช่าที่ดินของนายแจ่มปลูกบ้านอยู่และได้เดินผ่านที่ดินของใจมาได้หกปีเพื่อเข้าออกใน หมู่บ้าน ตอลดมาโดยไม่เคยขออนุญาตใจเลย สัญญาเช่าที่ดินแจ่มหมดอายุ นายจิตจึงได้รื้อบ้านออกไป และไปเช่าที่ดินในตัวเมืองเพื่อปลูกบ้านอยู่ แต่ก็ยังคงประกอบอาชีพค้าขาย จึงยังต้องใช้ทางเดินผ่านที่ดิน ของใจเข้าออกในหมู่บ้านเพื่อเข้าไปค้าขายเหมือนเดิม จิตใช้ทางผ่านที่ดินของใจมาช่วงหลังนี้ได้ห้า ปี ทางผ่านที่เป็นดินเริ่มเป็นหลุมเป็นบ่อเข้าออกไม่สะดวก จิตจึงได้จ้างผู้รับเหมาทำถนนและตั้งใจจะเท คอนกรีต แต่เมื่อใจทราบจึงได้ห้ามไม่ให้จิตเข้ามาในที่ดินของตนและให้ผู้รับเหมารื้อย้ายข้าวของที่จะทำ ถนนผ่านออกไปและทำที่ดินให้ดีเหมือนเดิม\n\nระหว่างจิตและใจ จิตจะรักษาทางทำถนนและเทคอนกรีตบนทางเข้าออกบนที่ดินของใจได้ หรือไม่ เพราะเหตุใด","rule":"มาตรา 1377 วรรคแรก ถ้าผู้ครอบครองสละเจตนาครอบครอง หรือไม่ยุดถือทรัพย์สินต่อไป ไซร้ การครอบครองย่อมสุดสิ้นลง\n\nมาตรา 1382 บุคคลใดครอบครองทรัพย์สินของผู้อื่นไว้โดยความสงบและโดยเปิดเผยด้วยเจตนา เป็นเจ้าของ ถ้าเป็นอสังหาริมทรัพย์ได้ครอบครองติดต่อกันเป็นเวลาสิบปี ถ้าเป็นสังหาริมทรัพย์ได้ ครอบครองติดต่อกันเป็นเวลาห้าปีไซร้ ท่านว่าบุคคลนั้นได้กรรมสิทธิ์\n\nมาตรา 1387 อสังหาริมทรัพย์อาจต้องตกอยู่ในภาระจำยอมอันเป็นเหตุให้เจ้าของต้องยอมรับกรรม บางอย่างซึ่งกระทบถึงทรัพย์สินของตน หรือต้องงดเว้นการใช้สิทธิบางอย่างอันมีอยู่ในกรรมสิทธิ์ทรัพย์สิน นั้นเพื่อประโยชน์แก่อสังหาริมทรัพย์อื่น\n\nมาตรา 1391 เจ้าของสามยทรัพย์มีสิทธิทำการทุกอย่างอันจำเป็นเพื่อรักษาและใช้ภาระจำยอมแต่ ต้องเสียค่าใช้จ่ายของตนเอง ในการนี้เจ้าของสามยทรัพย์จะก่อให้เกิดความเสียหายแก่ภารยทรัพย์ได้ก็แต่ น้อยที่สุดตามพฤติการณ์\n\nมาตรา 1401 ภาระจำยอมอาจได้มาโดยอายุความ ท่านให้นำบทบัญญัติว่าด้วยอายุความได้สิทธิอัน กล่าวไว้ในลักษณะ 3 แห่งบรรพนี้มาใช้บังคับโดยอนุโลม","application":"กรณีตามอุทาหรณ์ โดยหลักแล้ว การใช้ภารยทรัพย์เพื่อให้ได้ภาระจำยอมนั้น ไม่จำเป็นที่เจ้าของ สามยทรัพย์จะต้องเป็นผู้ใช้เองเท่านั้น การที่นายจิตผู้เช่าที่ดินของนายแจ่มได้เดินผ่านที่ดินของนายใจโดย เจตนาใช้เป็นทางเข้าออกในหมู่บ้าน โดยไม่เคยขออนุญาตนายใจเลยเป็นระยะเวลา 6 ปี ถือว่านายแจ่ม เจ้าของที่ดินใช้ทางโดยปรปักษ์โดยมีนายจิตเป็นผู้ใช้ทางแทน (ตามมาตรา 1368 ประกอบมาตรา 1401) การที่ต่อมา สัญญาเช่าที่ดินระหว่างนายจิตและนายแจ่มสิ้นสุดลง นายจิตผู้เช่าได้รื้อถอนบ้านออกไปและ ไปเช่าที่ดินในเมืองปลูกบ้านอยู่ โดยไม่ปรากฏว่านายแจ่มได้ใช้ทางผ่านที่ดินของนายใจต่อจากนายจิตแต่ อย่างใด กรณีเช่นนี้ถือว่านายจิตสละเจตนาครอบครองเพื่อให้ได้ซึ่งสิทธิภาระจำยอมในทางผ่านที่ดินของ นายใจตามมาตรา 1377 วรรคแรกแล้ว การครอบครองโดยปรปักษ์เพื่อให้ได้ภาระจำยอมที่มีก่อน ตลอด 6 ปีที่ผ่านมาจึงสิ้นสุดลง ดังนั้น อายุความครอบครองปรปักษ์เพื่อให้ได้ภาระจำยอมของนายจิตจึง สิ้นสุดลงด้วย และแม้ต่อมาจะได้ความว่าในขณะที่สัญญาเช่าที่ดินระงับไปแล้ว นายจิตจะยังใช้ทางเดินผ่านที่ดินของนาย ใจเข้าออกในหมู่บ้านอยู่ก็ตาม แต่การเข้าออกดังกล่าวเป็นการเข้าไปเพื่อค้าขายอันเป็นไปเพื่อประโยชน์ ส่วนตัวของนายจิตโดยเฉพาะ มิใช่เพื่อประโยชน์ของอสังหาริมทรัพย์ การใช้ทางผ่านในช่วงหลัง ตลอดเวลา 5 ปี จึงนับอายุความครอบครองปรปักษ์ตามมาตรา 1401 ประกอบมาตรา 1382 เพื่อให้ได้ ภาระจำยอมไม่ได้ เพราะไม่เข้าลักษณะและสาระสำคัญของภาระจำยอมตามมาตรา 1387 ดังนั้น ภาระจำ ยอมจึงไม่อาจเกิดมีขึ้นได้ (ฎ. 11 – 13/2503) ประเด็นที่ต้องวินิจฉัยมีว่า นายจิตจะทำถนนและเทคอนกรีตบนทางเข้าออกบนที่ดินของนายใจได้ หรือไม่ เห็นว่า การที่นายจิตจ้างผู้รับเหมาทำถนนและตั้งใจจะเทคอนกรีต แม้จะเป็นการกระทำเพื่อรักษา และใช้ทางผ่านที่ดินของนายใจ และไม่เป็นการกระทำที่เป็นการเพิ่มภารยทรัพย์ก็ตาม (ฎ.1730/2503) นาย จิตก็ไม่สามารถทำได้ กรณีไม่ต้องด้วยมาตรา 1391 วรรคแรก เพราะกรณีนี้ภาระจำยอมไม่เกิดขึ้น นายใจ\n\nจึงมีอำนาจห้ามไม่ให้นายจิตเข้ามาในที่ดินของตน และให้ผู้รับเหมารื้อย้ายข้าวของที่จะทำถนนออกไปและ ทำที่ดินให้ดีเหมือนเดิมได้","conclusion":"สรุป นายจิตทำถนนและเทคอนกรีตบนทางเข้าออกบนที่ดินของนายใจไม่ได้","otherSections":["1391"]},{"id":"archive-2551-2-4-74","year":"2551","semester":"ภาค 2","number":4,"page":74,"course":"LAW2001 (LA 201 / LW 204)","title":"ปี 2551 ภาค 2 · ข้อ 4","sections":["1368","1382"],"kind":"old-exam-source","source":"แนวข้อสอบเก่าวิชาทรัพย์สิน.pdf","question":"ข้อ 4 ทองครอบครองปรปักษ์ที่ดินมีโฉนดแปลงหนึ่งของนายนาค ทำสวนลิ้นจี่มาได้แปดปี ถูกศาล พิพากษาจำคุกเป็นเวลาเก้าเดือน เงินซึ่งเป็นเพื่อบ้านทราบจึงได้ขอเช่าสวนลื้นจี่เพื่อให้นักท่องเที่ยวมาเที่ยว ชมสวนเกษตรและเก็บลิ้นจี่ขายนักท่องเที่ยวด้วย เมื่อถูกจำคุกไปได้แปดเดือนขณะอยู่ในเรือนจำ ทองป่วย ต้องเข้าโรงพยาบาล เมื่อพ้นโทษทองจึงได้มารักษาพยาบาลต่ออยู่ในโรงพยาบาลที่กรุงเทพ อีกห้าเดือนเป็น เวลารวมหนึ่งปีกับสองเดือน เมื่อรักษาตัวหายดีแล้วทองจึงได้หางานทำที่กรุงเทพ แต่ที่ดินแปลงนี้ทอง ยังคงให้เงินเช่าต่อ ทองทำงานอยู่ที่กรุงเทพมาได้สองปี เงินและทองถูกนาคฟ้องขับไล่เรียกที่ดินแปลงนี้ คืน\n\nให้ท่านอธิบายว่าทองได้กรรมสิทธิ์ในที่ดินแปลงนี้แล้วหรือยัง นาคฟ้องคดีต่อศาลเรียกที่ดินแปลง นี้คืนจากทองได้หรือไม่ เพราะเหตุใด","rule":"มาตรา 1368 บุคคลอาจได้มาซึ่งสิทธิครอบครองโดยผู้อื่นยึดถือไว้ให้\n\nมาตรา 1382 บุคคลใดครอบครองทรัพย์สินของผู้อื่นไว้โดยความสงบและโดยเปิดเผยด้วยเจตนา เป็นเจ้าของ ถ้าเป็นอสังหาริมทรัพย์ได้ครอบครองติดต่อกันเป็นเวลาสิบปี ถ้าเป็นสังหาริมทรัพย์ได้ ครอบครองติดต่อกันเป็นเวลาห้าปีไซร้ ท่านว่าบุคคลนั้นได้กรรมสิทธิ์ มาตรา 1384 “ถ้าผู้ครอบครองขาดยึดถือทรัพย์สินโดยไม่สมัคร และได้คืนภายในเวลาปีหนึ่งนับตั้งแต่วัน ขาดยึดถือ หรือได้คืนโดยฟ้องคดีภายในกำหนดนั้นไซร้ ท่านมิให้ถือว่าการครอบครองสะดุดหยุดลง”","application":"โดยหลักแล้ว การได้กรรมสิทธิ์ในอสังหาริมทรัพย์โดยการครอบครองปรปักษ์ตามมาตรา 1382 จะต้อง ประกอบด้วยหลักเกณฑ์ดังนี้ คือ 1 เป็นทรัพย์สินของผู้อื่นโดยผู้อื่นมีกรรมสิทธิ์ 2 ได้ครอบครองโดยความสงบ 3 ครอบครองโดยเปิดเผย 4 ครอบครองโดยเจตนาเป็นเจ้าของ 5 ครอบครองติดต่อกันมาเป็นเวลา 10 ปี สำหรับการครอบครองติดต่อกันนั้น จะต้องเป็นกรณีที่ผู้ครอบครอง ไม่มีเจตนาสละการครอบครอง หรือ ขาดการยึดถือโดยสมัครใจ และนับระยะเวลาครอบครองติดต่อกันได้ หากเป็นเพียงการขาดการยึดถือโดย ไม่สมัคร เพราะมีเหตุมาขัดขวางโดยไม่สมัครใจ กฎหมายถือว่าการขาดการยึดถือนั้นไม่ทำให้ขาดอายุ\n\nความ การครอบครองสะดุดหยุดลง หากได้ทรัพย์สินคืนภายใน 1 ปี นับแต่วันที่ขาดการยึดถือ ทั้งนี้ตาม มาตรา 1384 กรณีตามอุทาหรณ์ การที่ทองครอบครองปรปักษ์ที่ดินมีโฉนดแปลงหนึ่งของนายนาค มา 8 ปี โดยทำเป็น สวนลิ้นจี่ ต่อมานายทอง ได้ถูกศาลพิพากษาจำคุกเป็นเวลา 9 เดือน เงินซึ่งเป็นเพื่อบ้านจึงได้ขอเช่าสวน ลิ้นจี่จากทองเพื่อให้นักท่องเที่ยวมาเที่ยวชมสวนเกษตร และเก็บลิ้นจี่ขายนักท่องเที่ยวด้วย กรณีเช่นนี้ ถือ ว่า ทองได้ขาดการยึดถือโดยไม่สมัครใจตามมาตรา 1384 โดยมีเงินผู้เช่าเป็นผู้ยึดถือการครอบครองแทน ตามมาตรา 1368 และเป็นผู้เอาคืนซึ่งการครอบครองให้ภายใน 1 ปี นับตั้งแต่ขาดการยึดถือโดยไม่สมัคร ใจ อายุความการครอบครองจึงไม่สะดุดหยุดลง เมื่อได้ความว่า ทองถูกจำคุกไปได้ 8 เดือน ขณะอยู่ในเรือนจำทองป่วยต้องเข้าโรงพยาบาล เมื่อพ้นโทษ ทองจึงได้มารักษาพยาบาลต่ออยู่ในโรงพยาบาลที่กรุงเทพฯ อีก 5 เดือน ซึ่งเป็นเวลา รวม 1 ปี 2 เดือน เมื่อรักษาตัวหายดีแล้ว ทองจึงได้หางานทำที่กรุงเทพฯ และทองได้ทำงานอยู่ ที่กรุงเทพฯอีก 2 ปี ในกรณีดังกล่าวนี้ ระหว่างที่ทองถูกจำคุกและในระหว่างป่วยและทำงานที่ กรุงเทพฯ จะถือว่าทองขาดการยึดถือไม่ได้ เพราะที่ดินแปลงนี้ก็มีเงินครอบครองปรปักษ์แทนทอง ตลอดเวลาตามมาตรา 1368 ประกอบมาตรา 1384 ดังที่กล่าวไปข้างต้น เมื่อรวมระยะเวลาทั้งหมดติดต่อกัน แล้วเป็นเวลาเกิน 10 ปี ดังนั้น ทองจึงได้กรรมสิทธิ์ในที่ดินแปลงนี้แล้ว โดยการครอบครองปรปักษ์ตาม มาตรา 1382","conclusion":"สรุป ทองได้กรรมสิทธิ์ในที่ดินแปลงนี้แล้ว นาคจึงฟ้องศาลเรียกที่ดินแปลงนี้จากทองไม่ได้","otherSections":["1384"]},{"id":"archive-2551-1-1-76","year":"2551","semester":"ภาค 1","number":1,"page":76,"course":"LAW2001 (LA 201 / LW 204)","title":"ปี 2551 ภาค 1 · ข้อ 1","sections":["1299"],"kind":"old-exam-source","source":"แนวข้อสอบเก่าวิชาทรัพย์สิน.pdf","question":"ข้อ 1 เด่นเป็นเจ้าของที่ดินมีโฉนดจำนวน 2 ไร่ โดยเด่นยกที่ดินด้านทิศเหนือจำนวน 1 ไร่ ให้แก่ดวง โดยไม่ได้จดทะเบียนแบ่งโฉนดให้ ภายหลังจากดวงเข้าครอบครองเป็นเจ้าของที่ดินด้านทิศเหนือติดต่อกัน เป็นเวลากว่า 10 ปีแล้ว เด่นก็ยกที่ดินส่วนที่เหลือจำนวน 1 ไร่ ซึ่งอยู่ด้านทิศใต้ให้แก่เปลว แต่ทำสัญญาจดทะเบียนให้เปลวมีชื่อเป็นเจ้าของโฉนดทั้งแปลง เพราะเปลวรับรองว่าจะจดทะเบียนแบ่ง โอนให้ดวงในภายหลัง แต่เปลวไม่ดำเนินการจดทะเบียนแบ่งโอนให้ดวงตามที่รับรองไว้กับเด่น แต่กลับ นำที่ดินดังกล่าวไปทำสัญญาและจดทะเบียนขายให้กับเพลิง ซึ่งเพลิงรู้ข้อเท็จจริงต่างๆ และรู้ด้วยว่าดวง กำลังจะยื่นฟ้องคดีให้เปลวแบ่งโฉนดให้ดวง แต่เพลิงก็ยังรับซื้อที่ดินนั้นทั้งหมด\n\nดังนี้ให้ท่านวินิจฉัยว่า ระหว่าง ดวง เปลว และเพลิง ผู้ใดมีกรรมสิทธิ์ในที่ดินจำนวน 1 ไร่ ด้าน ทิศเหนือซึ่งเป็นที่พิพาทดีกว่ากัน เพราะเหตุใด","rule":"มาตรา 1299 ภายในบังคับแห่งบทบัญญัติในประมวลกฎหมายนี้หรือกฎหมายอื่น ท่านว่า การ ได้มาโดยนิติกรรมซึ่งอสังหาริมทรัพย์หรือทรัพยสิทธิอันเกี่ยวกับอสังหาริมทรัพย์นั้นไม่บริบูรณ์ เว้นแต่นิติ กรรมจะได้ทำเป็นหนังสือและได้จดทะเบียนการได้มากับพนักงานเจ้าหน้าที่ ถ้ามีผู้ได้มาซึ่งอสังหาริมทรัพย์ หรือทรัพยสิทธิอันเกี่ยวกับอสังหาริมทรัพย์โดยทางอื่นนอกจากนิติ กรรม สิทธิของผู้ได้มานั้น ถ้ายังมิได้จดทะเบียนไซร้ ท่านว่าจะมีการเปลี่ยนแปลงทางทะเบียนไม่ได้ และ สิทธิอันยังมิได้จดทะเบียนนั้น มิให้ยกเป็นข้อต่อสู้บุคคลภายนอกผู้ได้สิทธิมาโดยเสียค่าตอบแทนและโดย สุจริตและได้จดทะเบียนสิทธิโดยสุจริตแล้ว","application":"เด่นยกที่ดินด้านทิศเหนือจำนวน 1 ไร่ ให้ดวง แต่ยังไม่ได้จดทะเบียนแบ่งแยกโฉนดที่ดินให้ ดวงจึงเป็นผู้ ได้มาซึ่งอสังหาริมทรัพย์โดยทางนิติกรรมตามมาตรา 1299 วรรคแรก แต่นิติกรรมดังกล่าวไม่ได้จด ทะเบียนกับพนักงานเจ้าหน้าที่จึงเป็นโมฆะ แต่การที่ดวงเข้าครอบครองเป็นเจ้าของที่ดินนั้นติดต่อกันเป็น เวลากว่า 10 ปีแล้ว ดวงจึงเป็นผู้ได้กรรมสิทธิ์โดยการครอบครองปรปักษ์ อันเป็นการได้มาโดยทาง อื่น นอกจากนิติกรรมตามมาตรา 1299 วรรคสอง แต่ดวงยังไม่ได้จดทะเบียนเปลี่ยนชื่อในโฉนดเป็นของ ตน ดวงจึงไม่สามารถเปลี่ยนแปลงใดๆในทางทะเบียน และไม่สามารถยกเป็นข้อต่อสู้บุคคลภายนอกผู้ได้ สิทธิในอสังหาริมทรัพย์นั้นโดยมีค่าตอบแทน โดยสุจริต และจดทะเบียนสิทธิโดยสุจริต แล้ว (ฎ. 884/2523)\n\nต่อมาเด่นยกที่ดินส่วนที่เหลือด้านทิศใต้จำนวน 1 ไร่ ให้เปลว โดยทำสัญญาและจดทะเบียนให้เปลวมีชื่อ ในโฉนดทั้งแปลง เพราะเปลวรับรองว่าจะจดทะเบียนแบ่งโอนให้ดวงภายหลัง แต่เปลวไม่ดำเนินการจด ทะเบียนแบ่งโอนให้ดวงตามที่รับรองไว้กับเด่น แต่เปลวกลับทำสัญญาและจดทะเบียนขายที่ดินแปลงทิศ เหนือให้เพลิง โดยเพลิงรู้ข้อเท็จจริงต่างๆ แม้เพลิงจะเป็นบุคคลภายนอกที่ได้กรรมสิทธ์ในที่ดินดังกล่าว โดยมีค่าตอบแทนก็จริง แต่การได้มานั้นไม่สุจริต และจดทะเบียนสิทธิโดยไม่สุจริต ดังนั้น ดวงจึงเป็นผู้มีกรรมสิทธิ์ในที่ดินพิพาทดีกว่าเปลว เพราะเปลวได้มาโดยไม่มีค่าตอบแทนไม่ สุจริต และจดทะเบียนสิทธิโดยไม่สุจริต เพราะดวงมีกรรมสิทธิ์ดีกว่าเพลิงตามเหตุผลดังกล่าวข้างต้น","conclusion":"สรุป ดวงมีกรรมสิทธิ์ในที่ดินพิพาทดีกว่าเปลวและเพลิง","otherSections":[]},{"id":"archive-2551-1-3-77","year":"2551","semester":"ภาค 1","number":3,"page":77,"course":"LAW2001 (LA 201 / LW 204)","title":"ปี 2551 ภาค 1 · ข้อ 3","sections":["1382","1387","1401"],"kind":"old-exam-source","source":"แนวข้อสอบเก่าวิชาทรัพย์สิน.pdf","question":"ข้อ 3 หนึ่งเป็นเจ้าของที่ดินแปลงหนึ่งซึ่งให้สองเช่าที่ดินปลูกบ้าน สองได้ใช้ทางเดินผ่านที่ดินของสามเพื่อ ออกไปสู่ถนนสาธารณะ เพราะที่ดินของหนึ่งไม่มีทางเข้าออก โดยสองไม่ได้ขออนุญาตจากสามเลย สอง เช่าที่ดินหนึ่งและใช้ทางผ่านเข้าออกบนที่ดินของสามมาได้สิบห้าปี ทางราชการได้ตัดถนนระหว่างจังหวัด\n\nผ่านที่ดินแปลงนั้น พอดีกับที่สองได้เลิกสัญญาเช่าที่ดินแปลงนั้นจึงถูกปล่อยทิ้งร้างมาได้สองปี หนึ่งได้เข้า มาปลูกบ้านอยู่บนที่ดินแปลงนั้น หนึ่งจึงต้องการที่จะใช้ทางผ่านบนที่ดินของสามเข้าออก โดยหนึ่งอ้างว่าที่ดินของสามตกเป็นภาระจำยอมให้ที่ดินของตนผ่านเข้าออกแล้ว แต่สามอ้างว่าหนึ่งหมด สิทธิที่จะใช้ทางผ่านเข้าออกบนที่ดินของตนแล้ว\n\nให้ท่านอธิบายว่าข้ออ้างระหว่างหนึ่งและสามใครจะรับฟังได้ดีกว่ากัน เพราะเหตุใด","rule":"มาตรา 1382 บุคคลใดครอบครองทรัพย์สินของผู้อื่นไว้โดยความสงบและโดยเปิดเผยด้วยเจตนา เป็นเจ้าของ ถ้าเป็นอสังหาริมทรัพย์ได้ครอบครองติดต่อกันเป็นเวลาสิบปี ถ้าเป็นสังหาริมทรัพย์ได้ ครอบครองติดต่อกันเป็นเวลาห้าปีไซร้ ท่านว่าบุคคลนั้นได้กรรมสิทธิ์\n\nมาตรา 1387 อสังหาริมทรัพย์อาจต้องตกอยู่ในภาระจำยอมอันเป็นเหตุให้เจ้าของต้องยอมรับกรรม บางอย่างซึ่งกระทบถึงทรัพย์สินของตน หรือต้องงดเว้นการใช้สิทธิบางอย่างอันมีอยู่ในกรรมสิทธิ์นั้นเพื่อ ประโยชน์แก่อสังหาริมทรัพย์อื่น\n\nมาตรา 1400 วรรคแรก ถ้าภาระจำยอมหมดประโยชน์แก่สามยทรัพย์ไซร้ ท่านว่าภาระจำยอมนั้น สิ้นไป แต่ถ้าความเป็นไปมีทางให้กลับใช้ภาระจำยอมได้ไซร้ ท่านว่าภาระจำยอมนั้นกลับมีขึ้นอีก แต่ต้อง ยังไม่พ้นอายุความที่ระบุไว้ในมาตราก่อน มาตรา 1401 ภาระจำยอมอาจได้มาโดยอายุความ ท่านให้นำบทบัญญัติว่าด้วยอายุความได้สิทธิกล่าวไว้ใน ลักษณะ 3 แห่งบรรพนี้มาใช้บังคับโดยอนุโลม","application":"หนึ่งเป็นเจ้าของที่ดินแปลงหนึ่งซึ่งให้สองเช่าที่ดินปลูกบ้าน สองได้ใช้ทางเดินผ่านที่ดินของสามเพื่อออก ไปสู่ถนนสาธารณะเพราะที่ดินของหนึ่งไม่มีทางเข้าออก โดยสองไม่ได้ของอนุญาตจากสามเลยสองเช่า ที่ดินหนึ่งและใช้ทางผ่านเข้าออกบนที่ดินของสามมาได้สิบห้าปี ที่ดินของหนึ่งได้ภาระจำยอมในการใช้ ทางเดินผ่านที่ดินของสามเพราะภาระจำยอมมีขึ้นเพื่อประโยชน์อสังหาริมทรัพย์ตามมาตรา 1387 ดังนั้นใคร ก็ตามที่อยู่บนที่ดินก็จะก่อให้เกิดภาระจำยอมโดยการครอบครองปรปักษ์ได้ตามมาตรา 1401 ประกอบ มาตรา 1382 ทางราชการได้ตัดถนนระหว่างจังหวัดผ่านที่ดินแปลงนั้น ภาระจำยอมในการใช้ทางก็หมด ประโยชน์แก่สามยทรัพย์ภาระจำยอมนั้นสิ้นไป เป็นการสิ้นไปโดยผลของกฎหมายมาตรา 1400 วรรค แรก และเมื่อเป็นถนนของทางราชการจึงใช้ได้ตลอดไป เมื่อหนึ่งได้เข้ามาปลูกบ้านอยู่บนที่ดินแปลง นั้น หนึ่งจะใช้ทางผ่านบนที่ดินของสามไม่ได้ เพราะภาระจำยอมสิ้นไปโดยผลของกฎหมายแล้ว ข้อที่สาม อ้างว่าหนึ่งหมดสิทธิที่จะใช้ทางผ่านเข้าออกบนที่ดินของตนจึงรับฟังได้ดีกว่าของหนึ่ง","conclusion":"สรุป ข้ออ้างของสามรับฟังได้ดีกว่า","otherSections":["1400"]},{"id":"archive-2551-1-4-79","year":"2551","semester":"ภาค 1","number":4,"page":79,"course":"LAW2001 (LA 201 / LW 204)","title":"ปี 2551 ภาค 1 · ข้อ 4","sections":["1367","1382","1387","1401"],"kind":"old-exam-source","source":"แนวข้อสอบเก่าวิชาทรัพย์สิน.pdf","question":"ข้อ 4 ที่ดินมือเปล่าแปลงหนึ่งของโอ่งมีที่ดินมือเปล่าของอ่างอยู่ติดทางขวามือ และมีที่ดินมือเปล่าของ เอียดติดอยู่ทางด้านหลัง อ่างได้เข้าไปขุดหน่อไม้ในที่ดินของโอ่งมาขายเป็นประจำเป็นเวลาเกินกว่าสิบปี แล้ว ส่วนเอียดก็ใช้ที่ดินของโอ่งเป็นทางผ่านเข้าออกที่ดินของตนตลอดมาอยู่เกินกว่าสิบปีเช่นกัน ทั้งเอียด และอ่างได้ใช้ที่ดินของโอ่งโดยโอ่งไม่รู้ ต่อมาโอ่งได้ห้ามไม่ให้เอียดและอ่างเข้าไปในที่ดินแปลงนั้นของ ตน\n\nตามประมวลกฎหมายแพ่งและพาณิชย์ลักษณะทรัพย์ อ่างและเอียดมีสิทธิในที่ดินของโอ่งแปลงนั้น อย่างไรบ้าง เพราะเหตุใด","rule":"มาตรา 1367 บุคคลใดยึดถือทรัพย์สินโดยเจตนาจะยึดถือเพื่อตน ท่านว่าบุคคลนั้นได้ซึ่งสิทธิ ครอบครอง\n\nมาตรา 1382 บุคคลใดครอบครองทรัพย์สินของผู้อื่นไว้โดยความสงบและโดยเปิดเผยด้วยเจตนา เป็นเจ้าของ ถ้าเป็นอสังหาริมทรัพย์ได้ครอบคอรงติดต่อกันเป็นเวลาสิบปี ถ้าเป็นสังหาริมทรัพย์ได้ครอบคอ รงติดต่อกันเป็นเวลาห้าปีไซร้ ท่านว่าบุคคลนั้นได้กรรมสิทธิ์\n\nมาตรา 1387 อสังหาริมทรัพย์อาจต้องตกอยู่ในภาระจำยอมอันเป็นเหตุให้เจ้าของต้องยอมรับกรรม บางอย่างซึ่งกระทบถึงทรัพย์สินของตน หรือต้องงดเว้นการใช้สิทธิบางอย่างอันมีอยู่ในกรรมสิทธิ์นั้นเพื่อ ประโยชน์แก่อสังหาริมทรัพย์อื่น\n\nมาตรา 1401 ภาระจำยอมอาจได้มาโดยอายุความ ท่านให้นำบทบัญญัติว่าด้วยอายุความได้สิทธิอัน กล่าวไว้ในลักษณะ 3 แห่งบรรพนี้มาใช้บังคับโดยอนุโลม","application":"ที่ดินมือเปล่าแปลงหนึ่งของโอ่งมีที่ดินมือเปล่าของอ่างอยู่ติดทางขวามือ และมีที่ดินมือเปล่าของเอียดติดอยู่ ทางด้านหลัง อ่างได้เข้าไปขุดหน่อไม้ในที่ดินของโอ่งมาขาย การเข้าไปขุดหน่อไม้มาขายไม่ก่อให้เกิดสิทธิ ครอบครองบนที่ดินของโอ่งเพราะการเข้าไปเก็บหน่อไม้ยังไม่ได้เกี่ยวข้องใช้ประโยชน์ในทรัพย์ถึงขนาด เท่ากับผู้ทรงสิทธิครอบครองในที่ดินมือเปล่าที่ยึดถือใช้ที่ดินทำประโยชน์กับทรัพย์ จึงยังไม่เป็นยึดถือ ทรัพย์สินโดยเจตนายึดถือเพื่อตน ตามมาตรา 1367 และไม่ได้ภาระจำยอมในที่ดินของโอ่ง ตาม มาตรา 1387 ส่วนเอียดก็ใช้ที่ดินของโอ่งเป็นทางผ่านเข้าออกที่ดินของตนตลอดมาเกินกว่าสิบปี โดยโอ่ง ไม่รู้ ที่ดินของเอียดจึงได้ภาระจำยอมโดยการครอบครองปรปักษ์ที่ผ่านเข้าออกบนที่ดินของโอ่งแล้วตาม มาตรา 1401 ประกอบมาตรา 1382","conclusion":"สรุป 1 อ่างไม่มีสิทธิในที่ดินของโอ่ง\n\n2 เอียดได้ภาระจำยอมโดยการครอบครองปรปักษ์ที่ผ่านเข้าออกที่ดินของโอ่ง","otherSections":[]},{"id":"archive-2550-s-1-80","year":"2550","semester":"ภาคฤดูร้อน","number":1,"page":80,"course":"LAW2001 (LA 201 / LW 204)","title":"ปี 2550 ภาคฤดูร้อน · ข้อ 1","sections":["1304","1382","1367"],"kind":"old-exam-source","source":"แนวข้อสอบเก่าวิชาทรัพย์สิน.pdf","question":"ข้อ 1 นายท้วมและนายอ่าเป็นเจ้าของที่ดินอยู่ติดต่อกัน และด้านทิศเหนือของที่ดินทั้งสองแปลงต่างก็ติด กับแม่น้ำปิง เวลาฤดูน้ำ น้ำท่วมเต็มตลิ่งทุกปี เวลาฤดูแล้งน้ำลดลงไป ทั้งนายท้วมและนายอ่าต่างก็เข้าไป ปลุกผักในที่ดินริมตลิ่งที่น้ำลดลงตรงหน้าที่ดินของตน ต่อมานายท้วมสุขภาพไม่ดีจึงเลิกปลูกผักและไม่ได้ เข้าไปใช้ประโยชน์ในที่ดินริมตลิ่งนั้นอีกเลย นายอ่าเห็นนายท้วมไม่ได้เข้าไปครอบครองทำประโยชน์ใน ที่ดินดังกล่าวเป็นเวลากว่า 1 ปีแล้ว\n\nนายอ่าจึงขยายพื้นที่ปลูกผักเข้าไปในที่ดินริมตลิ่งหน้าที่ดินของนายท้วม โดยนายท้วมไม่ทักท้วง หลังจาก นั้น 3 ปี นายท้วมถึงแก่ความตาย นายเท่งบุตรของนายท้วมจดทะเบียนรับมรดกที่ดินของนายท้วม และ ไม่ยอมให้นายอ่าปลูกผักในที่ดินริมตลิ่งหน้าที่ดินที่ตนรับมรดก และต้องการจะเข้าไปปลูกผักเอง นายอ่า ไม่ยอม อ้างว่าได้ครอบครองที่ดินพิพาทซึ่งเป็นที่ดินมือเปล่ามาเกิน 1 ปีแล้ว\n\nนายเท่งจึงไม่มีสิทธิฟ้องเอาคืนซึ่งการครอบครอง เช่นนี้ นายอ่าจะได้กรรมสิทธิ์หรือสิทธิ ครอบครองในที่ดินพิพาทนั้นอย่างไร หรือไม่ และนายเท่งจะให้นายอ่าออกไปจากที่พิพาทได้ หรือไม่ เพราะเหตุใด","rule":"มาตรา 1304 สาธารณะสมบัติของแผ่นดินนั้น รวมทรัพย์สินทุกชนิดของแผ่นดิน ซึ่งใช้เพื่อ สาธารณะประโยชน์ หรือสงวนไว้เพื่อประโยชน์ร่วมกัน เช่น (2) ทรัพย์สินสำหรับพลเมืองใช้ร่วมกัน เป็นต้นว่าที่ชายตลิ่ง ทางน้ำ ทางหลวง ทะเลสาบ\n\nมาตรา 1306 ท่านห้ามมิให้ยกอายุความขึ้นเป็นข้อต่อสู้กับแผ่นดินในเรื่องทรัพย์สินอันเป็นสา ธารณสมบัติของแผ่นดิน","application":"ที่พิพาทเป็นที่ดินริมตลิ่งหน้าที่ดินของนายท้วมและนายอ่า ซึ่งเวลาฤดูน้ำ น้ำท่วมถึงเต็มตลิ่งทุกปี เวลาฤดู แล้งน้ำลดลงไป ที่ดินริมตลิ่งทั้งสองแปลงดังกล่าว ย่อมถือได้ว่าเป็นที่ชายตลิ่ง อันเป็นสาธารณสมบัติของ แผ่นดินประเภททรัพย์สินสำหรับพลเมืองใช้ร่วมกัน ตามมาตรา 1304 (2) ผู้ใดหามีกรรมสิทธิ์หรือสิทธิ\n\nครอบครองไม่ ดังนั้นทั้งนายท้วมและนายอ่าจึงไม่มีกรรมสิทธิ์หรือสิทธิ์ครอบครองในที่ดินพิพาทแต่อย่าง ใด (ฎ. 2199/2515)\n\nนอกจากนี้ แม้นายท้วมและนายอ่าจะเข้าไปปลูกผักในที่ชายตลิ่งหน้าที่ดินของตนนานเท่าใด ก็ไม่ สามารถยกอายุความการครอบครองปรปักษ์ (มาตรา 1382) หรือแม้แต่ในเรื่องสิทธิครอบครอง (มาตรา 1367) ขึ้นเป็นข้อต่อสู้กับแผ่นดินได้ ตามมาตรา 1306 แม้การยึดถือครอบครองสาธารณสมบัติของแผ่นดินจะไม่ก่อให้เกิดสิทธิใดๆ แก่ผู้ยึดถือ ครอบครอง หมายถึงใช้ยันต่อรัฐหรือแผ่นดินไม่ได้ แต่ในระหว่างเอกชนด้วยกันนั้นใช้ยันกันเองได้ โดยถือ หลักว่าผู้ที่เป็นฝ่ายครอบครองที่สาธารณสมบัติของแผ่นดินอยู่ก่อนและยังคงครอบครองอยู่ ผู้นั้นย่อมมี สิทธิดีกว่า (ฎ. 3908/2535) ซึ่งสิทธิดังกล่าวจะมีอยู่ตลอดเวลาที่ครอบครองเท่านั้น ดังนั้นหากผู้ที่ ครอบครองอยู่ก่อนแล้วสละการครอบคอรงที่พิพาทนั้นไป ผู้ครอบครองรายหลังซึ่งยังคงครอบครองทำ ประโยชน์อยู่ย่อมมีสิทธิดีกว่า กรณีตามอุทาหรณ์ นายท้วมไม่ได้เข้าไปครอบครองทำประโยชน์ในที่ดินดังกล่าวเป็นเวลา 1 ปี แล้ว และ การที่นายอ่าขยายพื้นที่ปลูกผักเข้าไปในที่ดินริมตลิ่งหน้าที่ดินของนายท้วม นายท้วมก็ไม่ได้ทักท้วงแต่อย่าง ใด เช่นนี้ถือว่า นายท้วมสละการครอบคอรงแล้ว เมื่อนายอ่าเข้าไปครอบครองทำประโยชน์ต่อ นายอ่าจึง เป็นผู้มีสิทธิในที่พิพาทดีกว่านายท้วมและนายเท่ง ดังนั้นนายเท่งจึงไม่สามารถให้นายอ่าออกไปจากที่ดิน พิพาทได้ (ฎ. 279/2530)","conclusion":"สรุป นายอ่าไม่มีกรรมสิทธิ์หรือสิทธิครอบครองในที่ดินพิพาทแต่อย่างใด และนายเท่งจะให้นาย อ่าซึ่งเป็นผู้มีสิทธิดีกว่าตนออกไปจากที่ดินพิพาทไม่ได้เช่นกัน","otherSections":["1306"]},{"id":"archive-2550-s-4-83","year":"2550","semester":"ภาคฤดูร้อน","number":4,"page":83,"course":"LAW2001 (LA 201 / LW 204)","title":"ปี 2550 ภาคฤดูร้อน · ข้อ 4","sections":["1382","1387","1401"],"kind":"old-exam-source","source":"แนวข้อสอบเก่าวิชาทรัพย์สิน.pdf","question":"ข้อ 4 นายสำลีมีอาชีพทำไร่และเลี้ยงปลาขาย ที่ดินของสำลีที่ใช้ทั้งอาศัยปลูกบ้านและทำไร่เลี้ยงปลาอยู่ ตรงข้ามกับที่ดินของนายสายมีทางเดินเท้าสาธารณะคั่นอยู่ ที่ดินของนายสายมีสระน้ำอยู่ในที่ดินนั้น นาย สำลีทำท่อฝังใต้ถนนสาธารณะสูบน้ำข้ามถนนเข้ามาในที่ดินของนายสำลีโดยไม่ได้ขออนุญาตนายสายแต่\n\nอย่างใด เพื่อใช้ทำไร่เลี้ยงปลาประจำมาได้แปดปี ต่อมานายสำลีได้ยกท่อน้ำขึ้นมาวางไว้บนถนน ทำให้ ชาวบ้านซึ่งใช้ถนนเส้นนั้นเข้าออกไม่สะดวก ชาวบ้านจึงได้บอกกับกำนันให้มาบอกให้นายสำลีรื้อท่อน้ำ นั้นออกไปจากถนน แต่นายสำลีไม่ยอมรื้อ หลังจากนั้นมาได้สองปีครึ่งนายสายทราบจึงห้ามไม่ให้นายสำลี สูบน้ำจากที่ดินของตนและให้รื้อท่อน้ำนั้นออกไป แต่นายสำลีไม่ยอม\n\nตามประมวลกฎหมายแพ่งและพาณิชย์ นายสำลีจะได้ภาระจำยอมโดยการครอบครองปรปักษ์ใน การใช้น้ำในบ่อนั้นหรือไม่ เพราะเหตุใด","rule":"มาตรา 1382 บุคคลใดครอบครองทรัพย์สินของผู้อื่นไว้โดยความสงบและโดยเปิดเผยด้วยเจตนา เป็นเจ้าของ ถ้าเป็นอสังหาริมทรัพย์ได้ครอบคอรงติดต่อกันเป็นเวลาสิบปี ถ้าเป็นสังหาริมทรัพย์ได้ครอบคอ รงติดต่อกันเป็นเวลาห้าปีไซร้ ท่านว่าบุคคลนั้นได้กรรมสิทธิ์\n\nมาตรา 1387 อสังหาริมทรัพย์อาจต้องตกอยู่ในภาระจำยอมอันเป็นเหตุให้เจ้าของต้องยอมรับกรรม บางอย่างซึ่งกระทบถึงทรัพย์สินของตน หรือต้องงดเว้นการใช้สิทธิบางอย่างอันมีอยู่ในกรรมสิทธิ์นั้นเพื่อ ประโยชน์แก่อสังหาริมทรัพย์อื่น\n\nมาตรา 1401 ภาระจำยอมอาจได้มาโดยอายุความ ท่านให้นำบทบัญญัติว่าด้วยอายุความได้สิทธิอัน กล่าวไว้ในลักษณะ 3 แห่งบรรพนี้มาใช้บังคับโดยอนุโลม","application":"นายสำลีมีอาชีพทำไร่และเลี้ยงปลาขาย ที่ดินของสำลีที่ใช้ทั้งอาศัยปลูกบ้านและทำไร่เลี้ยงปลาอยู่ตรงข้าม กับที่ดินของนายสายมีทางเดินเท้าสาธารณะขั้นอยู่ ที่ดินของนายสายมีสระน้ำอยู่ในที่ดินนั้นนายสำลีทำท่อ ฝังใต้ถนนสาธารณะสูบน้ำเข้ามาในที่ดินของนายสำลีโดยไม่ได้ขออนุญาตจากนายสายแต่อย่างใด เพื่อใช้ทำ ไร่เลี้ยงปลาเป็นการใช้เพื่อประโยชน์อสังหาริมทรัพย์ทำให้ที่ดินของนายสำลีเข้าลักษณะภาระจำยอมโดย การครอบครองปรปักษ์แล้ว เมื่อใช้มาได้ประจำแปดปีนายสำลีได้ยกท่อน้ำนั้นขึ้นมาบนถนน ทำให้ ชาวบ้านซึ่งใช้ถนนเส้นนั้นเข้าออกไม่สะดวก ชาวบ้านจึงได้บอกกับกำนันให้มาบอกให้นายสำลีรื้อถอนท่อ น้ำนั้นออกไปจากถนน แต่นายสำลีก็ยังไม่ยอมรื้อออก หลังจากนั้นมาได้สองปีครึ่งนายสายทราบจึงห้าม ไม่ให้นายสำลีสูบน้ำจากที่ดินของตนและรื้อท่อน้ำนั้นออกไป แต่นายสำลีไม่ยอม ดังนี้นายสำลีได้ภาระจำ ยอมโดยการครอบครองปรปักษ์ในการใช้น้ำในบ่อนั้นอันได้มาโดยอายุความแล้ว ตาม มาตรา 1387 ประกอบมาตรา 1382 และมาตรา 1401","conclusion":"สรุป นายสำลีย่อมได้ภาระจำยอมโดยการครอบครองปรปักษ์ในการใช้น้ำในบ่อน้ำนั้นแล้ว","otherSections":[]},{"id":"archive-2550-2-1-85","year":"2550","semester":"ภาค 2","number":1,"page":85,"course":"LAW2001 (LA 201 / LW 204)","title":"ปี 2550 ภาค 2 · ข้อ 1","sections":["146"],"kind":"old-exam-source","source":"แนวข้อสอบเก่าวิชาทรัพย์สิน.pdf","question":"ข้อ 1 ปริญญาเช่าที่ดินของดุษฎีเพื่อก่อสร้างโครงเหล็กติดป้ายโฆษณาเป็นเวลา 5 ปี โดยสัญญาเช่าระบุว่า ทรัพย์สินใดๆที่ได้ปลูกสร้างและติดตั้งในสถานที่เช่านี้อันเกิดจากการเช่าเป็นกรรมสิทธิ์ของผู้เช่า และเมื่อ ครบกำหนดสัญญาเช่า ผู้เช่ามีสิทธิ์รื้อถอนคืนไปได้ทั้งสิ้น หลังจากปริญญาติดตั้งโครงเหล็กไป ได้ 4 ปี พอขึ้นปีที่ 5 ปริญญาขอบอกเลิกสัญญาเช่าและขอรื้อเฉพาะโครงเหล็กออกไปจากที่ดินเช่า ดุษฎี ไม่ขัดข้องแต่แจ้งให้ปริญญาส่งมอบที่ดินคืนให้ดุษฎีในสภาพเดิม คือต้องรื้อถอนตอม่อและเสาเข็มที่ฝังไว้ ใต้ดินออกไปด้วย ปริญญาไม่ต้องการรื้อถอนตอม่อกับเสาเข็มเพราะเสียค่าใช้จ่ายมาก\n\nปริญญาจึงมาปรึกษาท่านว่า จะรื้อเฉพาะโครงเหล็กอย่างเดียวไม่รื้อถอนตอม่อและเสาเข็มออกไป ได้หรือไม่ และดุษฎีจะฟ้องบังคับให้ปริญญาต้องรื้อตอม่อและเสาเข็มออกไปด้วยได้หรือไม่ เพราะเหตุใด","rule":"มาตรา 146 ทรัพย์ซึ่งติดกับที่ดินหรือติดกับโรงเรือนเพียงชั่วคราวไม่ถือว่าเป็นส่วนควบกับที่ดิน หรือโรงเรือนนั้น ความข้อนี้ให้ใช้บังคับแก่โรงเรือนหรือสิ่งปลูกสร้างอย่างอื่น ซึ่งผู้มีสิทธิในที่ดินของผู้อื่น ใช้สิทธินั้นปลูกสร้างไว้ในที่ดินนั้นด้วย","application":"ปริญญาเป็นผู้มีสิทธิในที่ดินของดุษฎีตามสัญญาเช่าที่ดินเพื่อก่อสร้างโครงเหล็กติดตั้งป้ายโฆษณาเป็น เวลา 5 ปี และได้ใช้สิทธินั้นปลูกสร้างเสาเข็ม ตอม่อ ซึ่งเป็นส่วนประกอบของโครงเหล็กในที่ดินที่ เช่า ดังนั้นภายในระยะเวลาตามสัญญาเช่า เสาเข็ม ตอม่อ และโครงเหล็กจึงไม่เป็นส่วนควบของที่ดินตาม\n\nมาตรา 146 หลังจากปริญญาติดตั้งโครงเหล็กได้ 4 ปี พอขึ้นปีที่ 5 ปริญญาขอบอกเลิกสัญญาเช่า แล้ว จะรื้อเฉพาะโครงเหล็กออกไปจากที่ดินที่เช่าเพียงอย่างเดียวไม่ได้ ดุษฎีสามารถฟ้องบังคับให้ปริญญา รื้อทั้งตอม่อและเสาเข็มออกไปและส่งมอบที่ดินคืนให้แก่ตนในสภาพเดิมได้ โดยปริญญาเป็นผู้ออก ค่าใช้จ่ายในการรื้อถอนดังกล่าว","conclusion":"สรุป ปริญญาต้องรื้อทั้งโครงเหล็ก ตอม่อ และเสาเข็มออกไป หากปริญญาไม่รื้อตอม่อและ เสาเข็ม ดุษฎีสามารถฟ้องบังคับให้รื้อถอนได้","otherSections":[]},{"id":"archive-2550-1-1-89","year":"2550","semester":"ภาค 1","number":1,"page":89,"course":"LAW2001 (LA 201 / LW 204)","title":"ปี 2550 ภาค 1 · ข้อ 1","sections":["1299"],"kind":"old-exam-source","source":"แนวข้อสอบเก่าวิชาทรัพย์สิน.pdf","question":"ข้อ 1 นายน้ำเข้าครอบครองที่ดินมีโฉนดของนายเปลวโดยสงบ เปิดเผย และมีเจตนาเป็นเจ้าของติดต่อกัน ได้เก้าปี พอขึ้นปีที่สิบ นายเปลวได้ฟ้องขับไล่นายน้ำให้ออกไปจากที่ดินแปลงนั้น คดีอยู่ระหว่างการ พิจารณาของศาล นายน้ำกับนายเปลวตกลงยอมความกัน โดยนายเปลวยินยอมให้นายน้ำเช่าซื้อที่ดิน พิพาท หากชำระค่าเช่าซื้อครบถ้วนแล้วนายเปลวยอมให้ที่ดินพิพาทตกเป็นกรรมสิทธิ์ของนายน้ำทันที และ นายเปลวจะจดทะเบียนโอนกรรมสิทธิ์ให้แก่นายน้ำ หากไม่ปฏิบัติตามข้อตกลงให้ถือเอาคำพิพากษาแทน การแสดงเจตนา\n\nและศาลมีคำพิพากษาตามยอม คดีถึงที่สุดแล้ว หลังจากนายน้ำชำระราคาครบถ้วน นายเปลวยัง ไม่ได้ไปจดทะเบียนโอนกรรมสิทธิ์ที่ดินพิพาทให้นายน้ำ นายเปลวก็ถึงแก่ความตาย นายเพลิงซึ่งเป็นบุตร ของนายเปลวได้จดทะเบียนรับมรดกที่ดินพิพาทในฐานะทายาทโดยชอบธรรม และไม่รู้เรื่องสัญญา ประนีประนอมยอมความระหว่างนายน้ำกับนายเปลวแต่อย่างใด\n\nดังนี้ให้ท่านวินิจฉัยว่า นายน้ำจะฟ้องขอให้เพิกถอนการจดทะเบียนรับมรดกที่ดินพิพาทและบังคับ ให้นายเพลิงจดทะเบียนโอนกรรมสิทธิ์ให้แก่ตนได้หรือไม่ เพราะเหตุใด","rule":"มาตรา 1299 ภายในบังคับแห่งบทบัญญัติในประมวลกฎหมายนี้หรือกฎหมายอื่น ท่านว่า การ ได้มาโดยนิติกรรมซึ่งอสังหาริมทรัพย์หรือทรัพยสิทธิอันเกี่ยวกับอสังหาริมทรัพย์นั้นไม่บริบูรณ์ เว้นแต่นิติ กรรมจะได้ทำเป็นหนังสือและได้จดทะเบียนการได้มากับพนักงานเจ้าหน้าที่\n\nมาตรา 1300 ถ้าได้จดทะเบียนการโอนอสังหาริมทรัพย์ หรือทรัพยสิทธิอันเกี่ยวกับ อสังหาริมทรัพย์ เป็นทางเสียเปรียบแก่บุคคลผู้อยู่ในฐานะอันจะให้จดทะเบียนสิทธิของตนได้อยู่ก่อน ไซร้ ท่านว่าบุคคลนั้นอาจเรียกให้เพิกถอนการจดทะเบียนนั้นได้ แต่การโอนอันมีค่าตอบแทน ซึ่งผู้รับโอน กระทำการโดยสุจริตนั้น ไม่ว่ากรณีจะเป็นประการใด ท่านว่าจะเรียกให้เพิกถอนทะเบียนไม่ได้","application":"นายน้ำแย่งการครอบครองปรปักษ์ที่ดินของนายเปลวติดต่อกันยังไม่ครบสิบปี ก็ถูกนายเปลวฟ้อง ขับไล่จึงยังไม่ได้กรรมสิทธิ์โดยการครอบครองปรปักษ์ แต่ขณะที่คดีอยู่ระหว่างการพิจารณาของศาลนาย น้ำกับนายเปลวตกลงยอมความกัน โดยนายเปลวยินยอมให้นายน้ำเช่าซื้อที่ดินพิพาท หากชำระค่าเช่าซื้อ ครบถ้วนแล้วนายเปลวยอมให้ที่ดินพิพาทตกเป็นกรรมสิทธิ์ของนายน้ำทันที และนายเปลวจะจดทะเบียน\n\nโอนกรรมสิทธิ์ให้แก่นายน้ำ หากปฏิบัติตามข้อตกลงให้ถือเอาคำพิพากษาแทนการแสดงเจตนา และศาลมี คำพิพากษาตามยอม คดีถึงที่สุดแล้ว และนายน้ำชำระราคาเช่าซื้อครบถ้วนแล้ว เช่นนี้นายน้ำจึงได้ กรรมสิทธิ์ที่ดินพิพาท โดยสัญญาประนีประนอม ยอมความในชั้นศาล ซึ่งเป็นการได้มาโดยทางนิติกรรม ตามมาตรา 1299 วรรคแรก เมื่อยังไม่ได้จดทะเบียนกับพนักงานเจ้าหน้าที่ การได้ซึ่งกรรมสิทธิ์จึงยังไม่ บริบูรณ์ในฐานะทรัพยสิทธิ แต่ยังคงมีผลบังคับนายน้ำกับนายเปลวในฐานะบุคคลสิทธิ ซึ่งนายน้ำสามารถ ฟ้องบังคับให้นายเปลวไปจดทะเบียนโนกรรมสิทธิ์ให้แก่ตนได้ หลังจากนั้น นายเปลวถึงแก่ความตาย นายเพลิงซึ่งเป็นบุตรของนายเปลวได้จดทะเบียนรับมรดกที่ดิน พิพาทในฐานะทายาทโดยชอบธรรม ซึ่งเป็นผู้สืบสิทธิของนายเปลวต้องรับไปทั้งสิทธิและหน้าที่ของ เจ้าของมรดกและการจดทะเบียนรับมรดกดังกล่าวทำให้นายน้ำผู้อยู่ในฐานะอันจะให้จดทะเบียนสิทธิของ ตนได้ก่อนต้องเสียเปรียบนายน้ำจึงสามารถฟ้องศาลให้เพิกถอนการจดทะเบียนรับมรดกของนายเพลิงได้ ตามมาตรา 1300 เพราะเป็นการได้มาซึ่งกรรมสิทธิ์โดยไม่มีค่าตอบแทน และบังคับให้นายเพลิงจด ทะเบียนโอนกรรมสิทธิ์ให้แก่ตนได้","conclusion":"สรุป นายน้ำสามารถฟ้องให้เพิกถอนการจดทะเบียนรับมรดกและบังคับให้นายเพลิงจดทะเบียน โอนกรรมสิทธิ์แก่ตนได้","otherSections":["1300"]},{"id":"archive-2550-1-2-90","year":"2550","semester":"ภาค 1","number":2,"page":90,"course":"LAW2001 (LA 201 / LW 204)","title":"ปี 2550 ภาค 1 · ข้อ 2","sections":["144"],"kind":"old-exam-source","source":"แนวข้อสอบเก่าวิชาทรัพย์สิน.pdf","question":"ข้อ 2 นายเอกมีที่ดินแปลงหนึ่งอยู่ติดกับที่ดินของนายโท นายเอกได้สร้างบ้านบนที่ดินของตนโดยก่อน ปลูกสร้างได้เรียกเจ้าพนักงานมารังวัดสอบเขตแล้ว แต่เมื่อสร้างเสร็จจึงพบว่ารั้วกำแพงและท่อระบายน้ำรุก ล้ำอยู่ในเขตที่ดินของนายโท 1 ตารางวา\n\nดังนี้ นายเอกจะต้องรื้อถอนรั้วกำแพงและท่อระบายน้ำหรือไม่ นายเอกและนายโทมีหน้าที่จะต้อง ปฏิบัติต่อกันอย่างไร หรือไม่ จงอธิบาย","rule":"มาตรา 144 ส่วนควบของทรัพย์ หมายความว่า ส่วนซึ่งโดยสภาพแห่งทรัพย์หรือโดยจารีต ประเพณีแห่งท้องถิ่นเป็นสาระสำคัญในความเป็นอยู่แห่งทรัพย์นั้น และไม่อาจแยกจากกันได้นอกจากจะ ทำลาย ทำให้บุบสลาย หรือทำให้ทรัพย์นั้นเปลี่ยนแปลงรูปทรงหรือสภาพไป เจ้าของทรัพย์ย่อมมีกรรมสิทธิ์ในส่วนควบของทรัพย์นั้น\n\nมาตรา 1312 วรรคแรก บุคคลใดสร้างโรงเรือนรุกล้ำเข้าไปในที่ดินของผู้อื่นโดยสุจริตไซร้ ท่าน ว่าบุคคลนั้นเป็นเจ้าของโรงเรือนที่สร้างขึ้น แต่ต้องเสียเงินให้แก่เจ้าของที่ดินเป็นค่าใช้ที่ดินนั้นและจด ทะเบียนสิทธิเป็นภาระจำยอม ต่อภายหลังถ้าโรงเรือนนั้นสลายไปทั้งหมด เจ้าของที่ดินจะเรียกให้เพิกถอน การจดทะเบียนเสียก็ได้","application":"การที่นายเอกทำการรังวัดสอบเขตก่อนปลูกบ้านเป็นการปลูกสร้างที่สุจริต เพราะไม่ได้เพิกเฉยละเลยในการ ตรวจสอบแนวเขต แต่เมื่อสร้างเสร็จพบว่ารั้วกำแพงและท่อระบายน้ำรุกล้ำอยู่ในเขตของนายโท นายเอกจึง ต้องรื้อถอนรั้วกำแพงและท่อระบายน้ำออกจากที่ดินของนายโท แม้ว่าจะเป็นการปลูกสร้างที่สุจริตก็ ตาม เพราะรั้วกำแพงและท่อระบายน้ำมิใช่ส่วนควบของโรงเรือน ตามมาตรา 144 จึงไม่อยู่ในความหมาย ของการปลูกสร้างโรงเรือนรุกล้ำในมาตรา 1312 วรรคแรก ดังนั้น นายเอกจึงมีหน้าที่ต้องรื้อถอนรั้ว กำแพง และท่อระบายน้ำออกไปจากที่ดินของนายโท แม้ว่าจะเป็นการสร้างรุกล้ำที่สุจริตก็ตาม","conclusion":"สรุป นายเอกมีหน้าที่ต้องรื้อถอนรั้วกำแพงและท่อระบายน้ำออกไปจากที่ดินของนายโท","otherSections":["1312"]},{"id":"archive-2550-1-3-91","year":"2550","semester":"ภาค 1","number":3,"page":91,"course":"LAW2001 (LA 201 / LW 204)","title":"ปี 2550 ภาค 1 · ข้อ 3","sections":["1382","1387","1401"],"kind":"old-exam-source","source":"แนวข้อสอบเก่าวิชาทรัพย์สิน.pdf","question":"ข้อ 3 นายสมเป็นเจ้าของกรรมสิทธิ์ในที่ดินแปลงหนึ่งซึ่งไดภาระจำยอมในการใช้ทางผ่านที่ดินของนาย แสงตลอดไป และได้จดทะเบียนไว้แล้ว แต่เมื่อใช้ภาระจำยอมไปได้ระยะหนึ่ง นายสมได้กั้นรั้วแบ่งแยก ที่ดินแปลงนั้นของตนออกเป็นสองส่วน ที่ดินอีกส่วนที่แบ่งแยกออกไปได้ให้นายสดเช่าปลูกบ้าน นายสด ปลูกบ้านอยู่บนที่ดินแปลงนั้น และใช้ทางผ่านเข้าออกบนที่ดินของนายสวยเพื่อออกสู่ทางสาธารณะ และ ไม่เคยได้ใช้ทางผ่านที่ดินของนายแสงอีกเลย มีเพียงแต่นายสมเท่านั้นใช้ทางผ่านที่ดินของนายแสง นายสด ได้ใช้ถนนผ่านเข้าออกบนที่ดินของนายสวยเพื่อออกสู่สาธารณะโดยไม่เคยขอหรือบอกนายสวยเลย\n\nให้นักศึกษาอธิบายว่า\n\n1 นายแสงจะขอให้ที่ดินส่วนที่นายสดครอบครองพ้นจากภาระจำยอมได้หรือไม่ เพราะเหตุใด\n\n2 ถ้านายสดใช้ทางผ่านที่ดินของนายสวยจะก่อให้เกิดภาระจำยอมบนที่ดินของนายสมและส่วน ที่นายสดครอบครองนั้นได้หรือไม่เพียงใด อธิบายให้ละเอียด","rule":"มาตรา 1382 บุคคลใดครอบครองทรัพย์สินของผู้อื่นไว้โดยความสงบและโดยเปิดเผยด้วยเจตนา เป็นเจ้าของ ถ้าเป็นอสังหาริมทรัพย์ได้ครอบครองติดต่อกันเป็นเวลาสิบปี ถ้าเป็นสังหาริมทรัพย์ได้ ครอบครองติดต่อกันเป็นเวลาห้าปีไซร้ ท่านว่าบุคคลนั้นได้กรรมสิทธิ์\n\nมาตรา 1387 อสังหาริมทรัพย์อาจต้องตกอยู่ในภาระจำยอมอันเป็นเหตุให้เจ้าของต้องยอมรับกรรม บางอย่างซึ่งกระทบถึงทรัพย์สินของตน หรือต้องงดเว้นการใช้สิทธิบางอย่างอันมีอยู่ในกรรมสิทธิ์นั้นเพื่อ ประโยชน์แก่อสังหาริมทรัพย์อื่น\n\nมาตรา 1395 ถ้ามีการแบ่งแยกสามยทรัพย์ ท่านว่าภาระจำยอมยังคงมีอยู่เพื่อประโยชน์แก่ทุกส่วน ที่แยกออกนั้น แต่ถ้าภาระจำยอมนั้นไม่ใช้ และใช้ไม่ได้ตามรูปการเพื่อประโยชน์แก่ส่วนใดไซร้ ท่านว่า เจ้าของภารยทรัพย์จะเรียกให้พ้นจากภาระจำยอมอันเกี่ยวกับทรัพย์ส่วนนั้นก็ได้\n\nมาตรา 1399 ภาระจำยอมนั้น ถ้ามิได้ใช้สิบปี ท่านว่าย่อมสิ้นไป\n\nมาตรา 1401 ภาระจำยอมอาจได้มาโดยอายุความ ท่านให้นำบทบัญญัติว่าด้วยอายุความได้สิทธิอัน กล่าวไว้ในลักษณะ 3 แห่งบรรพนี้มาใช้บังคับโดยอนุโลม","application":"นายสมเป็นเจ้าของกรรมสิทธิ์ในที่ดินแปลงหนึ่ง ซึ่งได้ภาระจำยอมในการใช้ทางผ่านที่ดินของนายแสง ตลอดไป และจดทะเบียนไว้แล้ว แต่เมื่อใช้ภาระจำยอมไปได้ระยะหนึ่ง นายสมได้แบ่งแยกกั้นรั้วที่ดิน แปลงนั้นของตนออกเป็นสองส่วน ส่วนหนึ่งให้นายสดปลูกบ้านเช่าอยู่ นายสดจึงปลูกบ้านอยู่บนที่ดิน แปลงนั้น และนายสดก็ไม่เคยใช้ทางผ่านที่ดินของนายแสงอีกเลย มีเพียงนายสมเท่านั้นใช้ทางผ่านที่ดิน ของนายแสงนายสดใช้ถนนผ่านเข้าออกบนที่ดินของนายสวยเพื่อออกสู่สาธารณะแทนโดยไม่เคยขอหรือ บอกนายสวยเลย\n\n1 นายแสงจะขอให้ที่ดินส่วนที่นายสดครอบครองพ้นจากภาระจำยอมไม่ได้ เพราะไม่ใช่ แบ่งแยกกรรมสิทธิ์ ที่ดินทั้งแปลงยังเป็นของนายสม จึงไม่มีสิทธิ์ที่จะขอให้พ้นจากภาระจำยอมตาม มาตรา 1395 และภาระจำยอมก็ยังไม่สิ้นไปตามมาตรา 1399 เพราะนายสมยังคงใช้ภาระจำยอมผ่านที่ดิน ของนายแสงอยู่\n\n2 ถ้านายสดใช้ทางผ่านที่ดินของนายสวยจะก่อให้เกิดภาระจำยอมบนที่ดินของนายสมทั้งแปลง ทั้งส่วนของนายสดที่ครอบครองอยู่ ในการผ่านที่ดินของนายสวยโดยการครอบครองปรปักษ์ไม่จำเป็นต้อง เป็นเจ้าของสามยทรัพย์ใครก็ตามที่อยู่ในสามยทรัพย์ก่อให้เกิดภาระจำยอมโดยการครอบครองปรปักษ์ ได้ มาตรา 1387","conclusion":"สรุป 1 นายแสงไม่มีสิทธิที่จะขอให้พ้นจากภาระจำยอมได้\n\n2 นายสดจะก่อให้เกิดภาระจำยอมบนที่ดินของนายสมทั้งแปลง รวมทั้งส่วนของนายสด ครอบครองอยู่ได้โดยการครอบครองปรปักษ์","otherSections":["1395","1399"]},{"id":"archive-2550-1-4-92","year":"2550","semester":"ภาค 1","number":4,"page":92,"course":"LAW2001 (LA 201 / LW 204)","title":"ปี 2550 ภาค 1 · ข้อ 4","sections":["1367","1375"],"kind":"old-exam-source","source":"แนวข้อสอบเก่าวิชาทรัพย์สิน.pdf","question":"ข้อ 4 นายแดงได้กู้ยืมเงินนายดำมาจำนวน 500,000 บาท กำหนดชำระเงินคืนภายในสามปี และได้ให้นาย ดำเข้าครอบคอรงทำประโยชน์บนที่ดินมือเปล่าแปลงหนึ่งของนายแดงแทนค่าดอกเบี้ยเงินกู้ ต่อมาเมื่อกู้ยืม เงินกันไปได้หนึ่งปี นายขาวบุตรชายของนายแดงได้มาทำสัญญาขายที่ดินแปลงนั้นกับนายดำ โดยนายดำ ได้ให้เงินนายขาวไปจำนวน 200,000 บาท แต่ก่อนที่จะครบสามปีตามสัญญากู้ยืม โดยนายดำได้นำ เงิน 500,000 บาท มาชำระหนี้เงินกู้ และเรียกที่ดินแปลงนั้นคืน แต่นายดำไม่ยอมรับและไม่ยอมออกไป จากที่ดินแปลงนั้นโดยอ้างว่าที่ดินแปลงนั้นนายขาวได้ขายให้ตนมาได้เกินกว่าหนึ่งปีแล้ว\n\nดังนี้ถ้านายแดงมาปรึกษาท่าน ท่านจะให้คำแนะนำกับนายแดงอย่างไร เพราะเหตุใด","rule":"มาตรา 1367 บุคคลใดยึดถือทรัพย์สินโดยเจตนาจะยึดถือเพื่อตน ท่านว่าบุคคลนั้นได้ซึ่งสิทธิ ครอบครอง\n\nมาตรา 1375 ถ้าผู้ครอบครองถูกแย่งการครอบครองโดยมิชอบด้วยกฎหมายไซร้ ท่านว่าผู้ ครอบครองมีสิทธิจะได้คืนซึ่งการครอบครอง เว้นแต่อีกฝ่ายหนึ่งมีสิทธิเหนือทรัพย์สินดีกว่า ซึ่งจะเป็นเหตุ ให้เรียกคืนจากผู้ครอบครองได้ การฟ้องคดีเพื่อเอาคืนซึ่งการครอบครองนั้น ท่านว่าต้องฟ้องภายในหนึ่งปีนับแต่เวลาถูกแย่งการ ครอบครอง\n\nมาตรา 1381 บุคคลใดยึดถือทรัพย์สินอยู่ในฐานะเป็นผู้แทนผู้ครอบครอง บุคคลนั้นจะเปลี่ยน ลักษณะแห่งการยึดถือได้ก็แต่โดยบอกกล่าวไปยังผู้ครอบครองว่า ไม่เจตนาจะยึดถือทรัพย์สินแทนผู้ ครอบครองต่อไป หรือตนเองเป็นผู้ครอบครองโดยสุจริต อาศัยอำนาจใหม่อันได้จากบุคคลภายนอก","application":"นายแดงได้กู้ยืมเงินมาจากนายดำจำนวน 500,000 บาท กำหนดชำระเงินคืนภายในสามปี และได้ให้นายดำ เข้าใช้ประโยชน์บนที่ดินมือเปล่าแปลงหนึ่งของนายแดงแทนค่าดอกเบี้ยเงินกู้ ต่อมาเมื่อกู้ยืมเงินไปได้หนึ่ง ปี นายขาวบุตรชายของนายแดงได้มาทำสัญญาขายที่ดินแปลงนั้นกับนายดำโดยนายดำได้ให้เงินนายขาวไป จำนวน 200,000 บาท แต่ก่อนที่ครบสามปีตามสัญญากู้ยืมเงิน นายแดงได้นำเงิน 500,000 บาท มาชำระ หนี้เงินกู้และเรียกที่ดินแปลงนั้นคืน แต่นายดำไม่ยอมรับและก็ไม่ยอมออกไปจากที่ดินแปลงนั้น โดยอ้างว่า ที่ดินแปลงนั้นนายขาวได้ขายที่ดินแปลงนี้ให้ตนมาได้กว่าหนึ่งปีแล้ว ดังนี้ นายแดงต้องฟ้องเรียกคืนที่ดิน แปลงนั้นจากนายดำภายในระยะเวลาหนึ่งปีนับตั้งแต่นายแดงไปชำระหนี้เงินกู้ และนายดำไม่ยอมรับชำระ หนี้กู้ยืมไม่ยอมออกไปและไม่ส่งที่ดินแปลงนั้นคืนนายแดง โดยอ้างว่าได้ซื้อที่ดินแปลงนั้นจากนายขาว บุตรชายของนายแดงแล้ว แสดงว่านายดำได้แย่งการครอบครองที่ดินมือเปล่าแปลงนั้นจากนายแดงสำเร็จ แล้ว ตามมาตรา 1381 นายดำครอบครองที่ดินแปลงนั้นด้วยตนเองตามมาตรา 1367 นายแดงต้องฟ้องต่อ ศาลเรียกคืนที่ดินแปลงนั้นภายในระยะเวลาหนึ่งปีตามมาตรา 1375","conclusion":"สรุป ข้าพเจ้าจะแนะนำให้นายแดงฟ้องต่อศาลเรียกคืนที่ดินแปลงนั้นภายในระยะเวลา 1 ปี นับแต่ วันที่นายดำไม่ยอมรับชำระหนี้เงินกู้ และไม่ยอมออกไปจากที่ดิน","otherSections":["1381"]},{"id":"archive-2549-s-1-94","year":"2549","semester":"ภาคฤดูร้อน","number":1,"page":94,"course":"LAW2001 (LA 201 / LW 204)","title":"ปี 2549 ภาคฤดูร้อน · ข้อ 1","sections":["144"],"kind":"old-exam-source","source":"แนวข้อสอบเก่าวิชาทรัพย์สิน.pdf","question":"ข้อ 1 นายคงทำสัญญาเช่าตึกแถวของนายมั่นเพื่ออยู่อาศัยเป็นเวลา 5 ปี โดยสัญญาเช่าระบุว่าทรัพย์ใดๆที่ นายคงผู้เช่าดัดแปลงหรือต่อเติมลงในตึกแถวที่เช่าให้ทรัพย์นั้นตกเป็นของนายมั่นผู้ให้เช่าทันที หลังจากที่ นายคงเข้าไปอยู่ในตึกแถวดังกล่าวได้ 2 ปี นายคงได้ทำฝากั้นห้องที่บริเวณชั้น 3 ของตึก และติดตั้ง เครื่องปรับอากาศเพื่อใช้เป็นห้องนอนเพิ่มอีกห้องหนึ่ง เมื่อครบกำหนดตามสัญญาเช่า นายคงจะรื้อถอนเอา ไม้ที่ทำเป็นฝากั้นห้องและเครื่องปรับอากาศออกไป นายมั่นไม่ยอมโดยอ้างว่าทั้งไม้และเครื่องปรับอากาศเป็นกรรมสิทธิ์ของนายมั่นแล้วตามสัญญาเช่าดังกล่าว\n\nดังนี้ ให้ท่านวินิจฉัยว่า นายคงจะรื้อถอนไม้ฝากั้นห้องและเครื่องปรับอากาศออกไปได้ หรือไม่ เพราะเหตุใด","rule":"มาตรา 144 ส่วนควบของทรัพย์ หมายความว่า ส่วนซึ่งโดยสภาพแห่งทรัพย์หรือโดยจารีต ประเพณีแห่งท้องถิ่นเป็นสาระสำคัญในความเป็นอยู่แห่งทรัพย์นั้น และไม่อาจแยกจากกันได้นอกจากจะ ทำลาย ทำให้บุบสลาย หรือทำให้ทรัพย์นั้นเปลี่ยนแปลงรูปทรงหรือสภาพไป เจ้าของทรัพย์ย่อมมีกรรมสิทธิ์ในส่วนควบของทรัพย์นั้น","application":"นายคงทำสัญญาเช่าตึกแถวของนายมั่นเพื่ออยู่อาศัยเป็นเวลา 5 ปี หลังจากนายคงเข้าไปอยู่ในตึกแถว ได้ 2 ปี นายคงได้ทำฝากั้นห้องที่บริเวณชั้น 3 ของตึก และติดตั้งเครื่องปรับอากาศเพื่อใช้เป็นห้องนอน นั้น ทั้งฝากั้นห้องและเครื่องปรับอากาศไม่เป็นส่วนควบของตึก เพราะไม่เป็นสาระสำคัญในความเป็นอยู่ ของตึกอันไม่อาจแยกออกได้นอกจากทำให้ตัวตึกเสียรูปทรง จึงไม่ตกเป็นกรรมสิทธิ์ของนายมั่นผู้ให้เช่า ตามมาตรา 144\n\nดังนั้นเมื่อครบกำหนดตามสัญญาเช่า นายคงสามารถรื้อถอนเอาไม้ที่ทำเป็นฝากั้นห้องและ เครื่องปรับอากาศออกไปได้ แม้ในสัญญาเช่าระบุว่าทรัพย์ใดๆที่นายคงผู้เช่าดัดแปลงหรือต่อเติมลงใน ตึกแถวที่เช่า ให้ทรัพย์นั้นตกเป็นของนายมั่นผู้ให้เช่าทันทีก็ตาม แต่ทั้งนี้ทรัพย์ที่ต่อเติมนั้นหมายความถึง การกระทำที่มาเป็นส่วนควบของตึก เมื่อฝากั้นห้องและเครื่องปรับอากาศไม่เป็นส่วนควบของตึกดังกล่าว แล้ว นายคงจึงสามารถรื้อถอนออกไปได้","conclusion":"สรุป นายคงสามารถรื้อถอนไม้ฝากั้นห้องและเครื่องปรับอากาศออกไปได้","otherSections":[]},{"id":"archive-2549-s-2-95","year":"2549","semester":"ภาคฤดูร้อน","number":2,"page":95,"course":"LAW2001 (LA 201 / LW 204)","title":"ปี 2549 ภาคฤดูร้อน · ข้อ 2","sections":["1304"],"kind":"old-exam-source","source":"แนวข้อสอบเก่าวิชาทรัพย์สิน.pdf","question":"ข้อ 2 นายก้องได้เข้าครอบครองทำไร่ในที่ดินแปลงหนึ่งซึ่งมีสภาพเป็นป่าเสื่อมโทรม แต่ทางราชการยังไม่ ออกพระราชกฤษฎีกาเพิกถอนการเป็นที่ป่าสงวนแห่งชาติ หลังจากที่นายก้องทำไร่ในที่ดินดังกล่าว ได้ 5 ปี นายก้องได้ไปพบนายขำเพื่อนของตน และขอให้นายขำซึ่งเป็นเจ้าพนักงานที่ดินช่วยออกหนังสือ รับรองการทำประโยชน์ (น.ส.3) ให้ ทั้งที่กรมที่ดินยังไม่ได้ประกาศให้ประชาชนเช้าจับจองเป็นเจ้าของ หรือออกเอกสารสิทธิแต่อย่างใด\n\nเมื่อนายก้องได้หนังสือรับรองการทำประโยชน์ (น.ส.3) มาแล้ว นายก้องได้ทำหนังสือและจด ทะเบียนกับพนักงานเจ้าหน้าที่ขายที่ดินดังกล่าวให้กับนายแก้ว ต่อมาทางราชการได้แจ้งให้นายแก้วออกไป จากที่ดินดังกล่าว แต่นายแก้วไม่ยอมย้ายออกจากที่ดินแปลงนั้น โดยต่อสู้ว่าตนซื้อที่ดินมาโดยสุจริตและจด ทะเบียนสิทธิโดยสุจริต\n\nดังนี้ ให้ท่านวินิจฉัยว่า ข้อต่อสู้ของนายแก้วรับฟังได้หรือไม่ เพราะเหตุใด","rule":"มาตรา 1304 สาธารณะสมบัติของแผ่นดินนั้น รวมทรัพย์สินทุกชนิดของแผ่นดิน ซึ่งใช้เพื่อ สาธารณะประโยชน์ หรือสงวนไว้เพื่อประโยชน์ร่วมกัน เช่น (1) ที่ดินรกร้างว่างเปล่า และที่ดินซึ่งมีผู้เวนคืนหรือทอดทิ้งหรือกลับมาเป็นของแผ่นดินโดยประการอื่นตาม กฎหมายที่ดิน\n\nมาตรา 1305 ทรัพย์สินซึ่งเป็นสาธารณสมบัติของแผ่นดินนั้นจะโอนแก่กันมิได้ เว้นแต่อาศัย อำนาจแห่งบทกฎหมายเฉพาะหรือพระราชกฤษฎีกา\n\nมาตรา 1306 ท่านห้ามมิให้ยกอายุความขึ้นเป็นข้อต่อสู้กับแผ่นดินในเรื่องทรัพย์สินอันเป็นสา ธารณสมบัติของแผ่นดิน","application":"ป่าเสื่อมโทรมที่ทางราชการยังไม่ออกพระราชกฤษฎีกาเพิกถอนการเป็นที่ป่าสงวนแห่งชาตินั้นยังมีสภาพ เป็นสาธารณสมบัติของแผ่นดินตามมาตรา 1304(1) ดังนั้นแม้นายก้องจะเข้าไปครอบครองทำไร่ในที่ดิน ดังกล่าวนานเท่าใด นายก้องก็ไม่ได้กรรมสิทธิ์หรือสิทธิครอบครองในที่ดินแปลงนั้น เพราะสาธารณสมบัติ ของแผ่นดินไม่สามารถยกอายุความขึ้นต่อสู้กับแผ่นดินตามมาตรา 1306 ส่วนการที่นายก้องไปพบนายขำเพื่อนของตน และขอให้นายขำเป็นเจ้าพนักงานที่ดินช่วยออกหนังสือ รับรองการทำประโยชน์ (น.ส.3) ให้ ทั้งที่กรมที่ดินยังไม่ได้ประกาศให้ประชาชนเข้าจับจองเป็นเจ้าของ หรือออกเอกสารสิทธิแต่อย่างใด จึงเป็นการออกหนังสือรับรองการทำประโยชน์ (น.ส.3) โดยมิชอบด้วย กฎหมาย กรมที่ดินสามารถเพิกถอนหนังสือรับรองการทำประโยชน์ (น.ส.3) นั้นได้ และนายก้องไม่ สามารถทำสัญญาและจดทะเบียนขายที่ดินนั้นให้กับนายแก้ว เพราะมาตรา 1305 มีหลักกฎหมายความ ว่า ทรัพย์สินซึ่งเป็นสาธารณสมบัติของแผ่นดินนั้นจะโอนแก่กันมิได้ เว้นแต่อาศัยอำนาจแห่งบทกฎหมาย เฉพาะหรือพระราชกฤษฎีกา ดังนั้นเมื่อทางราชการได้แจ้งให้นายแก้วออกไปจากที่ดินดังกล่าว นายแก้วจึง\n\nต้องย้ายออกไปจากที่ดินอันเป็นสาธารณสมบัติของแผ่นดินนั้น ข้อต่อสู้ของนายแก้วที่ว่าตนซื้อที่ดินมาโดย สุจริต และจดทะเบียนสิทธิโดยสุจริตจึงรับฟังไม่ได้","conclusion":"สรุป ข้อต่อสู้ของนายแก้งฟังไม่ขึ้น เพราะที่ดินดังกล่าวเป็นสาธารณสมบัติของแผ่นดิน","otherSections":["1305","1306"]},{"id":"archive-2549-s-3-96","year":"2549","semester":"ภาคฤดูร้อน","number":3,"page":96,"course":"LAW2001 (LA 201 / LW 204)","title":"ปี 2549 ภาคฤดูร้อน · ข้อ 3","sections":["1368"],"kind":"old-exam-source","source":"แนวข้อสอบเก่าวิชาทรัพย์สิน.pdf","question":"ข้อ 3 นายชุ่มทำไร่ในที่ดินมือเปล่าแห่งหนึ่ง ต่อมานายชุ่มได้ขายที่ดินแปลงนี้ให้นายชม และนายชมได้ให้ นายชุ่มอยู่ทำไร่ดูแลที่ดินแปลงนี้ต่อให้ เมื่อนายชุ่มครอบครองที่ดินแปลงนี้ต่อมาได้เจ็ดปี นายชุ่มได้นำ ที่ดินแปลงนี้ไปขายให้นายชิตส่งมอบการครอบครองให้นายชิต โดยนายชิตไม่ทราบว่าที่ดินแปลงนี้เป็น ของนายชม นายชิตซื้อที่ดินแปลงนี้จากนายชุ่มมาได้สามเดือน เมื่อเจ้าพนักงานรังวัดสำรวจเพื่อออกหนังสือสำคัญสำหรับที่นายชิตได้แจ้งการครอบครองที่ดินแปลงนี้ว่า เป็นของตนต่อเจ้าพนักงาน นายชมได้ไปร้องคัดค้าน และฟ้องขับไล่นายชิตให้ออกไปจากที่ดินแปลงนี้\n\nให้ท่านวินิจฉัยว่า ระหว่างนายชมและนายชิตใครมีสิทธิครอบครองในที่ดินแปลงนี้ดีกว่า กัน เพราะเหตุใด","rule":"มาตรา 1368 บุคคลอาจได้มาซึ่งสิทธิครอบครองโดยผู้อื่นยึดถือไว้ให้\n\nมาตรา 1380 การโอนไปซึ่งการครอบครองย่อมเป็นผลแม้ ผู้โอนยังยึดถือทรัพย์สินอยู่ ถ้าผู้โอน แสดงเจตนาว่าต่อไปจะยึดถือทรัพย์สินนั้นแทนผู้รับโอน ถ้าทรัพย์สินนั้นผู้แทนของผู้โอนยึดถืออยู่ การโอนไปซึ่งการครอบครองจะทำโดยผู้โอนสั่งผู้แทนว่า ต่อไป ให้ยึดถือทรัพย์สินไว้แทนผู้รับโอนก็ได้","application":"นายชุ่มได้ทำไร่ในที่ดินมือเปล่าแปลงหนึ่ง ต่อมานายชุ่มได้ขายที่ดินแปลงนี้ให้นายชมและนายชมได้ให้นาย ชุ่มอยู่ทำไร่ดูแลที่ดินแปลงนั้นให้ตน นายชุ่มจึงยึดถือที่ดินแปลงนั้นแทนนายชมตามมาตรา 1380 นายชม จึงมีสิทธิครอบครองที่ดินมือเปล่าแปลงนั้นดีกว่านายชุ่มตามมาตรา 1368 เมื่อนายชุ่มครอบครองที่ดิน แปลงนั้นต่อมาได้เจ็ดปี นายชุ่มได้นำที่ดินแปลงนั้นไปขายให้นายชิตส่งมอบการครอบครองให้นาย ชิต โดยนายชิตไม่ทราบว่าที่ดินแปลงนั้นเป็นของนายชม เมื่อนายชิตรับโอนจากนายชุ่มซึ่งไม่มีสิทธิดีกว่า นายชม นายชิตจึงไม่มีสิทธิในที่ดินมือเปล่าแปลงนั้นดีกว่านายชม ดังนั้นระหว่างนายชมและนายชิตนายชม ย่อมมีสิทธิครอบครองในที่ดินแปลงนั้นดีกว่านายชิต","conclusion":"สรุป นายชมย่อมมีสิทธิครอบครองในที่ดินแปลงนั้นดีกว่านายชิต","otherSections":["1380"]},{"id":"archive-2548-1-1-114","year":"2548","semester":"ภาค 1","number":1,"page":114,"course":"LAW2001 (LA 201 / LW 204)","title":"ปี 2548 ภาค 1 · ข้อ 1","sections":["1299"],"kind":"old-exam-source","source":"แนวข้อสอบเก่าวิชาทรัพย์สิน.pdf","question":"ข้อ 1 เมฆครอบครองที่ดินมีโฉนดแปลงหนึ่งของฝนมาเป็นเวลากว่า 10 ปี โดยไม่ได้ดำเนินการเปลี่ยนชื่อ ในโฉนดจนมาถึงปีที่ 15 ฝนได้ขายที่ดินแปลงนี้ให้พายุ โดยพายุไม่มีเวลาไปดูที่ดินที่จะซื้อจึงไม่รู้ว่าเมฆ ครอบครองอยู่ หลังจากจดทะเบียนซื้อขายกันเรียบร้อยแล้ว พายุนัดหมายนายดำผู้รับเหมาก่อสร้างไปดูที่ดิน ที่ซื้อจากฝนเพื่อตกลงเรื่องการปลูกบ้าน เมื่อไปดูที่ดินพบเมฆครอบครองอาศัยอยู่จึงแจ้งให้เมฆขนย้ายรื้อ ถอนบ้านออกไป แต่เมฆไม่สนใจ พายุจึงปรึกษาทนายความ\n\nถ้าท่านเป็นทนายความ จงให้คำแนะนำพายุว่าระหว่างพายุและเมฆ ใครมีสิทธิในที่ดินแปลงนี้ ดีกว่ากัน เพราะเหตุใด","rule":"มาตรา 1299 วรรคสอง ถ้ามีผู้ได้มาซึ่งอสังหาริมทรัพย์ หรือทรัพยสิทธิอันเกี่ยวกับ อสังหาริมทรัพย์โดยทางอื่นนอกจากนิติกรรม สิทธิของผู้ได้มานั้น ถ้ายังมิได้จดทะเบียนไซร้ ท่านว่าจะมี การเปลี่ยนแปลงทางทะเบียนไม่ได้ และสิทธิอันยังมิได้จดทะเบียนนั้น มิให้ยกเป็นข้อต่อสู้บุคคลภายนอกผู้ ได้สิทธิมาโดยเสียค่าตอบแทนและโดยสุจริตและได้จดทะเบียนสิทธิโดยสุจริตแล้ว","application":"เมฆครอบครองที่ดินของฝนมากว่า 10 ปีจึงเป็นผู้ได้กรรมสิทธิ์มาโดยการครอบครองปรปักษ์ เป็นการ ได้มาตามวรรคสองของมาตรา 1299 แต่เมื่อไม่ได้เปลี่ยนแปลงทางทะเบียน จึงอาจมีสิทธิด้อยกว่า บุคคลภายนอกที่ได้มาโดยสุจริต เสียค่าตอบแทนและจดทะเบียนสิทธิโดยสุจริตแล้ว พายุซื้อที่ดินจากฝนโดยไม่เคยไปดูที่ดินก่อนซื้อจึงไม่รู้ว่าเมฆครอบครองปรปักษ์อยู่ แต่การซื้อขายที่ดินนั้น มีหลายรายที่ไม่เคยไปดูที่ก็ทำการซื้อขายกัน จึงเป็นการซื้อที่สุจริต ดังนั้นพายุจึงเป็นบุคคลภายนอกที่ได้ ที่ดินมาโดยสุจริต เสียค่าตอบแทนและจดทะเบียนสิทธิโดยสุจริต สิทธิของพายุจึงดีกว่าเมฆ","conclusion":"สรุป พายุมีสิทธิในที่ดินแปลงนี้ดีกว่าเมฆ","otherSections":[]},{"id":"archive-2547-1-1-126","year":"2547","semester":"ภาค 1","number":1,"page":126,"course":"LAW2001 (LA 201 / LW 204)","title":"ปี 2547 ภาค 1 · ข้อ 1","sections":["146","1299"],"kind":"old-exam-source","source":"แนวข้อสอบเก่าวิชาทรัพย์สิน.pdf","question":"ข้อ 1 นายหลีทำสัญญาขายที่ดินมีโฉนดของตนแปลงหนึ่งให้กับนายหลามในราคาห้าแสนบาท ในวันทำ สัญญานายหลามได้ชำระราคาแล้วหนึ่งแสนบาท และนายหลีอนุญาตให้นายหลามเข้าไปในที่ดินเพื่อสร้าง บ้านอยู่อาศัยหรือทำประโยชน์ในที่ดินตามสัญญาได้ โดยสัญญาซื้อขายระบุว่าผู้ซื้อและผู้ขายจะไปจด ทะเบียนโอนกรรมสิทธิ์และชำระราคาส่วนที่เหลือทั้งหมดภายใน 1 ปีนับแต่วันทำสัญญา หลังจากนาย หลามสร้างบ้านลงบนที่ดินนั้นได้เพียง 8 เดือน นายหลีทำสัญญาและจดทะเบียนกับพนักงานเจ้าหน้าที่ขาย ที่ดินแปลงนี้ให้กับนายแหลม\n\nโดยสัญญาซื้อขายไม่ได้ระบุเรื่องบ้านไว้ให้ชัดเจน และนายแหลมก็ไม่รู้ข้อเท็จจริงเรื่องการซื้อขาย ที่ดินระหว่างนายหลีกับนายหลามมาก่อนหลังจากจดทะเบียนโอนกกรมสิทธิ์แล้ว นายแหลมได้แจ้งให้นาย หลามออกจากบ้านและที่ดินดังกล่าว\n\nดังนี้ให้ท่านวินิจฉัยว่าระหว่างนายหลามกับนายแหลมผู้ใดมีกรรมสิทธิ์ในบ้านและที่ดินแปลง ดังกล่าวดีกว่ากัน เพราะเหตุใด","rule":"มาตรา 146 ทรัพย์ซึ่งติดกับที่ดินหรือติดกับโรงเรือนเพียงชั่วคราวไม่ถือว่าเป็นส่วนควบกับที่ดิน หรือโรงเรือนนั้น ความข้อนี้ให้ใช้บังคับแก่โรงเรือนหรือสิ่งปลูกสร้างอย่างอื่น ซึ่งผู้มีสิทธิในที่ดินของผู้อื่น ใช้สิทธินั้นปลูกสร้างไว้ในที่ดินนั้นด้วย\n\nมาตรา 1299 ภายในบังคับแห่งบทบัญญัติในประมวลกฎหมายนี้หรือกฎหมายอื่น ท่านว่า การ ได้มาโดยนิติกรรมซึ่งอสังหาริมทรัพย์หรือทรัพยสิทธิอันเกี่ยวกับอสังหาริมทรัพย์นั้นไม่บริบูรณ์ เว้นแต่นิติ กรรมจะได้ทำเป็นหนังสือและได้จดทะเบียนการได้มากับพนักงานเจ้าหน้าที่","application":"สัญญาซื้อขายที่ดินระหว่างนายหลีกับนายหลามที่ระบุว่า ผู้ซื้อและผู้ขายจะไปจดทะเบียนโอนกรรมสิทธิ์ และชำระราคาส่วนที่เหลือทั้งหมดภายใน 1 ปีนับแต่วันทำสัญญา เป็นเพียงสัญญาจะซื้อจะขายกรรมสิทธิ์ ในที่ดินจึงยังไม่โอนไปยังนายหลามผู้จะซื้อ นายหลามจึงยังไม่ถือว่าเป็นผู้ได้มาซึ่งอสังหาริมทรัพย์โยทาง นิติกรรมตาม ป.พ.พ. มาตรา 1299 วรรค 1 แต่เนื่องจากในวันทำสัญญา นายหลามได้ชำระราคาแล้วหนึ่ง แสนบาท และนายหลีอนุญาตให้นายหลามเข้าไปในที่ดินเพื่อสร้างบ้านอยู่อาศัยหรือทำประโยชน์ในที่ดิน ตามสัญญาได้ บ้านที่นายหลามสร้างขึ้นจึงไม่ถือเป็นส่วนควบของที่ดิน และยังเป็นกรรมสิทธิ์ของนาย หลามอยู่ เพราะนายหลามเป็นผู้มีสิทธิในที่ดินของผื่นและนายหลามได้ใช้สิทธินั้นปลูกสร้างไว้ตาม ป. พ.พ. มาตรา 146\n\nหลังจากนายหลามสร้างบ้านลงบนที่ดินนั้นได้เพียง 8 เดือน นายหลีทำสัญญาและจดทะเบียนกับ พนักงานเจ้าหน้าที่ขายที่ดินแปลงนี้ให้กับนายแหลม โดยสัญญาซื้อขายไม่ได้ระบุเรื่องบ้านไว้ให้ ชัดเจน และนายแหลมก็ไม่รู้ข้อเท็จจริงเรื่องการซื้อขายที่ดินระหว่างนายหลีกับนายหลามมาก่อน นาย แหลมจึงเป็นผ้มีกรรมสิทธิ์ในที่ดินแปลงดังกล่าวโดยสมบูรณ์ และมีสิทธิดีกว่านายหลาม ส่วนบ้านเมื่อไม่ เป็นส่วนควบของที่ดินและยังคงเป็นกรรมสิทธิ์ของนายหลามอยู่ นายแหลมผู้รับโอนจึงไม่มีสิทธิดีกว่าผู้ โอน นายหลามจึงมีสิทธิในบ้านดีกว่านายแหลม","conclusion":"สรุป นายหลามมีสิทธิในบ้านดีกว่านายแหลม ส่วนนายแหลมมีสิทธิในที่ดินดีกว่านายหลาม","otherSections":[]}];})();